vector<int>cnt;
void solve() {
	string S; cin >> S;
	int K; cin >> K;
	VREVERSE(S);
	S += '0';
	int N = S.size();
	int m = 0;
	int c = 0;
	REP(i, N) {
		if (S[i] == '1')c++;
		else {
			cnt.push_back(c);
			c = 0;
		}
	}
	int n = cnt.size();
	dp[0][0][0][0] = 1;
	REP(i, n+1) {
		//if (i < n) { pe(i); print(cnt[i]); };
		REP(j, K + 1)REP(k, K + 1)dp[i][j][k][0] += dp[i][j][k][1] + dp[i][j][k][2];
		REP(j, K+1) {
			REP(k, j + 1) {
				//1を取る
				if (i<n&&cnt[i]) {
					dp[i + 1][j + 1][k + 1][1] += dp[i][j][k][0];
					int mn = min(j + cnt[i], K);
					int d = mn - j;
					dp[i + 1][j + d + 1][k + d + 1][1] -= dp[i][j][k][0];
				}
				//1を置く
				dp[i + 1][j][0][2] += dp[i][j][k][0];
				dp[i + 1][j][k + 1][2] -= dp[i][j][k][0];
			}
			//REP(k, K + 1)
		}
		REP(j, K + 1) {
			REP(k, K + 1) {
				dp[i + 1][j + 1][k + 1][1] += dp[i + 1][j][k][1];
				dp[i + 1][j][k + 1][2] += dp[i + 1][j][k][2];
			}
		}
	}
	mint ans = 0;
	REP(j, K + 1)ans += dp[n][j][0][0];
	print(ans);
}





