    for (int i = 1; i < p.size(); ++i) {
        a.push_back(p[i] - p[i - 1] - 1);
    }
    int ones = (int)s.size() - (int)p.size();
    k = min(k, ones);
    vector<vector<int> > d(ones + 1, vector<int> (k + 1, 0));
