        for (int i1 = 0; i1 <= ones; ++i1) {
            for (int i2 = 0; i2 <= k; ++i2) {
                pr[i1][i2] += d[i1][i2];
                if ((i1 > 0) && (i2 > 0))
                    pr[i1][i2] += pr[i1 - 1][i2 - 1];
                pr[i1][i2] %= mod;
            }
        }
        for (int i1 = 0; i1 <= ones; ++i1) {
            for (int i2 = 0; i2 <= k; ++i2) {
                if ((i1 >= a[i] + 1) && (i2 >= a[i] + 1))
                    dd[i1][i2] = pr[i1][i2] - pr[i1 - a[i] - 1][i2 - a[i] - 1];
                else 
                    dd[i1][i2] = pr[i1][i2];
                dd[i1][i2] %= mod;
                dd[i1][i2] += mod;
                dd[i1][i2] %= mod;
            }
        }
        for (int i2 = 0; i2 <= k; ++i2) {
            ll add = 0;
            for (int i1 = ones; i1 >= 0; --i1) {

                dd[i1][i2] += add;
                dd[i1][i2] %= mod;
                add += d[i1][i2];
                add %= mod;
            }
        }
        /*
        for (int nv = a[i] + 1; nv < s.size() + 1; ++nv) {
            for (int i1 = 0; i1 + nv - a[i] <= ones; ++i1) {
                for (int i2 = 0; i2 <= k; ++i2) {
