mint func(){
  vector<int> line;
  int val = 0;
  {
    string str = in<string>();
    int cnt = 0;
    foreach(i,str){
      if(i=='0'){
        if(cnt){
          val += cnt;
          line.emplace_back(cnt);
          cnt = 0;
        }
        line.emplace_back(0);
      }else{
        ++cnt;
      }
    }
    if(cnt){
      val += cnt;
      line.emplace_back(cnt);
    }
  }
  int n = line.size();
  int k = in();
  val;


  method(func,mint,int place,int need,int applyed){
    if(place>=n){
      if(need==applyed){
        return 1;
      }
      return 0;
    }
    static vvvector<mint> dp(n,vvector<mint>(val+1,vector<mint>(val+1)));
    static vvvector<bool> used(n, vvector<bool>(val+1, vector<bool>(val+1,false)));
    mint &it = dp[place][need][applyed];
    if(used[place][need][applyed])return it;
    used[place][need][applyed] = true;
    it = 0;
    if(line[place]){
      if(place+1<n){
        rep(i,need+1,min(k,val)+1){
          it += func(place+2,i,applyed);
        }
      }
      rep(i,min(need-applyed,line[place])+1){
        it += func(place+2,need,applyed+i);
      }
    }else{
      if(need<min(k,val)){
        it += func(place,need+1,applyed);
      }
      it += func(place+1,need,applyed);
    }
    return it;
  };

  return func(0,0,0);
}

