const long long mod = 998244353;
string S;
int K, no = 0;
vector<int> cnt;
vector<int> pfx;
long long dptable[301][301][301][2];
long long dp(int a, int b, int c, bool d) {
	if (b > no || c < 0) return 0;
	if (a == cnt.size()) return 1;
	if (dptable[a][b][c][d] != -1) return dptable[a][b][c][d];
	if (d == true) {
		if (a + 1 == cnt.size()) return dptable[a][b][c][d] = dp(a + 1, b, c, d);
		dptable[a][b][c][d] = 0;
		for (int i = max(b, pfx[a + 1]); i < b + cnt[a + 1]; ++i) dptable[a][b][c][d] += dp(a + 1, i, c, 1), dptable[a][b][c][d] %= mod;
		dptable[a][b][c][d] = (dptable[a][b][c][d] + dp(a + 1, b + cnt[a + 1], c, 0)) % mod;
		return dptable[a][b][c][d];
	} else return dptable[a][b][c][d] = (dp(a, b, c, 1) + dp(a, b + 1, c - 1, 0)) % mod;
}
int main() {
	memset(dptable, -1, sizeof dptable);
	ios_base::sync_with_stdio(false);
