int main() {
    SPEED
    string S; cin >> S;
    int K; cin >> K;
    S = S + "2";
    while(1){
        int flg = 1;
        for(int i = 0; i+1 < S.size(); ++i) {
            if(S[i]=='0' && S[i+1]=='0') {
                S = S.substr(0,i+1)+"2"+S.substr(i+1,S.size());
                flg = 0;
                break;
            }
        }
        if(flg) break;
    }

    int M = 0;
    for(int i = 0; i < S.size(); ++i) if(S[i]=='1') M++;
    auto R = Rarts(S);
    CombinationMod<MOD2> CM(M);
    K = min(K,M);

    int N = R.size();
    auto dp1 = multivector(N,M+1,K+1,modint(0));
    auto dp2 = multivector(N,M+1,modint(0));
    dp1[N-1][0][0]=1;
    dp2[N-1][0]=1;
    for(int i = N-2; 0 <= i; --i) {
        if(R[i].first=='0') {
            dp2[i] = dp2[i+1];
        }
        if(R[i].first=='1') {
            int L = R[i].second;
            for(int j = 0; j <= M; ++j) {
                for(int k = 0; k <= L; ++k) {
                    if(j+k<=M) dp2[i][j+k] += dp2[i+1][j]*CM.binom(L,k);
                }
            }
        }
        if(R[i].first=='2') {
            dp2[i] = dp2[i+1];
        }
    }

    for(int i = N-2; 0 <= i; --i) {
        if(R[i].first == '0') {
            //j ko nokotteru
            for(int j = 0; j <= M; ++j) {
                //k ko tsukau
                for(int k = 0; k <= M; ++k) {
                    if(j+k>M) break;
                    //l kai ikeru
                    for(int l = K; 0 <= l; --l) {
                        if(l-k<0) break;
                        dp1[i][j][l] += dp1[i+1][j+k][l-k]*dp2[i+1][k];
                    }
                }
            }            
        }
        if(R[i].first=='1') {
            int L = R[i].second;
            for(int j = 0; j <= M; ++j) {
                if(j+L>M) continue;
                for(int k = 0; k <= K; ++k) {
                    dp1[i][j+L][k] = dp1[i+1][j][k];
                }
            }
        }
        if(R[i].first=='2') {
            for(int j = 0; j <= M; ++j) {
                for(int k = 0; k <= K; ++k) {
                    dp1[i][j][k] = dp1[i+1][j][k];
                }
            }
        }
    }
    modint ans = 0;
    for(int i = 0; i <= M; ++i) {
        for(int j = 0; j <= K; ++j) {
            ans += dp1[0][i][j];
        }
    }
    cout << ans << endl;
    for(int i = 0; i < N; ++i) print(i,R[i],dp1[i],dp2[i]);
    return 0;
}

