int n, k, cnt; string s;
map<int, int> dp[N][N][N];
int yo(int i, int j, int used, int shift, int move) {
	if (i > n || j > n || used > cnt || move > k) return 0;
	if (i == n && j == n) return used == cnt && shift == 0 && move <= k;
	map<int, int> &ret = dp[i][used][move];
	if (ret.find(shift) != ret.end()) return ret[shift]; int z = shift;
	long long ans = 0;
	if (s[i] == '0') {
		ans = yo(i + 1, j + 1, used + (s[i] == '1'), shift, move);
		if (cnt - used > 0) ans += yo(i, j + 1, used + 1, shift + 1, move + 1);
	}
	else {
		ans = yo(i + 1, j + 1, used + (s[i] == '1'), shift, move);
		int z = i;
		while (z < n && shift && s[z] == '1') z++, shift--;
		if (z < n) ans += yo(z + 1, j + 1, used, shift, move);
		else ans += yo(z, j, used, shift, move);
	}
	ans %= mod;
	return ret[z] = ans;
}
