template<typename T>
struct Polynomial : vector<T> {
  using vector<T>::vector;
  using P = Polynomial;
  int n = (*this).size();
  P operator-() const {
    P res(n);
    rep(i, n) res[i] = -(*this)[i];
    return res;
  }
  P &operator+=(const P q) {
    rep(i, min(n, int(q.size()))) (*this)[i] += q[i];
    return *this;
  }
  P &operator-=(const P q) {
    rep(i, min(n, int(q.size()))) (*this)[i] -= q[i];
    return *this;
  }
  P &operator*=(const P q) { // dense
    drep(i, n) {
      (*this)[i] *= q[0];
      rep2(j, 1, int(q.size())) if (j <= i) (*this)[i] += (*this)[i-j] * q[j];
    }
    return *this;
  }
  template<typename T2>
  P &operator*=(map<int, T2> q) { // sparse
    drep(i, n) {
      (*this)[i] *= q[0];
      for (auto &[j, b] : q) if (j > 0 && j <= i) (*this)[i] += (*this)[i-j] * b;
    }
    return *this;
  }
  P &operator/=(const P q) { // dense
    rep(i, n) {
      rep2(j, 1, int(q.size())) if (j <= i) (*this)[i] -= (*this)[i-j] * q[j];
      (*this)[i] /= q[0];
    }
    return *this;
  }
  template<typename T2>
  P &operator/=(map<int, T2> q) { // sparse
    rep(i, n) {
      for (auto &[j, b] : q) if (j > 0 && j <= i) (*this)[i] -= (*this)[i-j] * b;
      (*this)[i] /= q[0];
    }
    return *this;
  }
  template<typename T2> P operator+(const T2 q) const { return P(*this) += q; }
  template<typename T2> P operator-(const T2 q) const { return P(*this) -= q; }
  template<typename T2> P operator*(const T2 q) const { return P(*this) *= q; }
  template<typename T2> P operator/(const T2 q) const { return P(*this) /= q; }
};
