using Pol2 = Polynomial<Pol>;


int main() {
  string s; cin >> s;
  int K; cin >> K;

  V a(1);
  for (auto c : s) {
    if (c == '0') a.push_back(0);
    if (c == '1') a.back()++;
  }
  int n = a.size();
  auto b = a;
  rep(i, n-1) b[i+1] += b[i];
  int m = b[n-1];

  Pol2 dp(m+1, Pol(m+1));
  dp[0][0] = 1;

  rep(i, n) {
    map<int, map<int, mint>> q1, q2, q3, q4;

    q1[0][0] = 1;
    q1[a[i]][0] += -1;

    q2[0][0] = 1;
    q2[1][0] = -1;

    q3[a[i]][0] = 1;

    q4[0][0] = 1;
    q4[1][1] = -1;

    dp = dp*q1/q2 + dp*q3/q4;
    rep(j, b[i]) dp[j] = Pol(m+1);
  }

  chmin(K, m);
  mint ans = 0;
  rep(k, K+1) ans += dp[m][k];
  cout << ans << "\n";
  return 0;
}

