int main() {
  constexpr std::int64_t kModulus = 998244353;
  std::string S;
  int K;
  std::cin >> S >> K;
  const int N = S.size();
  K = std::min(K, N);
  std::vector<int> zeros;
  for (int i = 0; i < N; ++i) {
    if (S[i] == '0') {
      zeros.push_back(i);
    }
  }
  const int num_zeros = zeros.size();
  if (num_zeros == 0 || num_zeros == N) {
    std::cout << 1 << std::endl;
    return 0;
  }
  zeros.push_back(N);
  std::vector<std::vector<std::vector<std::int64_t>>> mem(num_zeros + 1, std::vector<std::vector<std::int64_t>>(N + 1, std::vector<std::int64_t>(K + 1)));
  mem[num_zeros][N][0] = 1;
  for (int i = num_zeros - 1; i >= 0; --i) {
    for (int j = zeros[i]; j < N; ++j) {
      for (int k = std::max(j + 1, zeros[i + 1]); k <= N; ++k) {
        int m = std::max(0, (j - zeros[i]) - (k - zeros[i + 1]));
        for (int l = 0; l + m <= K; ++l) {
          mem[i][j][l + m] += mem[i + 1][k][l];
          mem[i][j][l + m] %= kModulus;
        }
      }
    }
  }
  std::int64_t sum = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j <= K; ++j) {
      sum += mem[0][i][j];
    }
  }
  std::cout << sum % kModulus << std::endl;
  return 0;
}

