auto make_vector(sizetype const(&sizes)[N], Tp const& x = Tp()) {
	std::vector<size_t> s(N);
	for (size_t i = 0; i < N; ++i) s[i] = sizes[N-i-1];
	return makevectordetail::make_vector<Tp, N>(s, x);
}
