void solve() {
	string S;
	ll K;
	cin>>S>>K;
	ll size=S.size();
	ll kugiri=0;
	rep(i,size){
		if(S[i]=='0')kugiri++;
	}
	if(kugiri==0){
		p(1);return;
	}
	vector<ll> v;
	ll t=0;
	rep(i,size){
		if(S[i]=='0'){
			v.push_back(t);t=0;
		}else{
			t++;
		}
	}
	v.push_back(t);
	reverse(all(v));

	ll k=min(size-kugiri,K);
	kugiri++;
	//kugiri区切り位置、残り移動回数、x保留中の0
	/*
	using dptype = ll;
	vector<vector<vector<Modint>>> dp = make_vector<Modint>({kugiri+1, k+1, k+1}, 0);
	vector<vector<vector<bool>>> checked = make_vector<bool>({kugiri+1, k+1, k+1}, false);
	auto f = [&](auto&& f, ll index, ll nokori, ll x) -> dptype {
		//debug(index,nokori,x);
		if(index>=kugiri) {
			return (x==0) ? 1 : 0;
		}
		if(checked[index][nokori][x]) return dp[index][nokori][x];
		dptype ans = 0;
		ll i=v[index]-nokori;
		if(i<0)i=0;
		for(;i<=v[index];i++){
			if(nokori-(v[index]-i)>=0)ans+=f(f,index+1,nokori-(v[index]-i),x+(v[index]-i));
		}
		repeq(i,x){
			ans+=f(f,index+1,nokori,x-i);
		}

		checked[index][nokori][x] = true;
		return dp[index][nokori][x] = ans;
	};
	dptype ans = f(f, 0, k, 0);
	p(ans);
	*/

	//要makevector
	using dptype = Modint;
	ll dpeachsize[] = {kugiri, k+1, k+1};
	ll dpeacharrsize = extent<decltype(dpeachsize),0>::value;
	vector<ll> dpitemsize(dpeacharrsize+1, 1);
	for(ll i=0; i<dpeacharrsize; i++) dpitemsize[i+1] = dpitemsize[i] * dpeachsize[i];
	auto dp = make_vector<dptype>(dpeachsize, 0);
	vector<bool> checked(dpitemsize.back(), false);
	auto getindex = [&](auto&&... args) {
		assert(sizeof...(args) == dpeacharrsize);
		ll ans = 0, i = 0;
		for(auto&& n : {args...}) ans += dpitemsize[i] * n, i++;
		return ans;
	};
	auto f = [&](auto&& f, ll index, ll nokori, ll x) -> dptype {
		if(index>=kugiri) {
			return (x==0) ? 1 : 0;
		}
		if(checked[getindex(index,nokori,x)]) return dp[index][nokori][x];
		dptype ans = 0;
		ll i=v[index]-nokori;
		if(i<0)i=0;
		for(;i<=v[index];i++){
			if(nokori-(v[index]-i)>=0)ans+=f(f,index+1,nokori-(v[index]-i),x+(v[index]-i));
		}
		repeq(i,x){
			ans+=f(f,index+1,nokori,x-i);
		}

		checked[getindex(index,nokori,x)] = true;
		return dp[index][nokori][x] = ans;
	};
	dptype ans = f(f, 0, k, 0);
	p(ans);
}

