using namespace std;

class CShift {
    class Solver {
    public:
        io::input_reader in;
        io::output_writer out;

        Solver(std::istream &in, std::ostream &out) : in(in), out(out) {}

        void solve() {
            // <code here>
            string s;
            int k;
            in >> s >> k;
            s.pb('0');
            int number_of_1 = 0;
            for (char c : s) if (c == '1') number_of_1++;
            vi chunk_of_1;
            int n = s.size();
            for (int i = 0; i < n; i++) {
                if (s[i] == '0') {
                    chunk_of_1.push_back(0);
                } else {
                    int j = i;
                    int cur = 0;
                    while (j < n && s[j] == '1') cur++, j++;
                    chunk_of_1.pb(cur);
                    i = j;
                }
            }
            assert(accumulate(all(chunk_of_1), 0) == number_of_1);
            n = chunk_of_1.size();
            vector<vvmi> dp(n + 1, vvmi(number_of_1 + 1, vmi(number_of_1 + 1)));
            dp[0][0][0] = 1;
            int ones_left = number_of_1;
            fori(i, n) {
                ones_left -= chunk_of_1[i];
                fori(action_used, number_of_1 + 1) {
                    fori(action_paid_for, action_used + 1) {
                        int cur = dp[i][action_used][action_paid_for];
                        if (cur == 0) continue;
                        fori(noo2u, chunk_of_1[i] + ones_left + 1) {
                            if (noo2u < chunk_of_1[i]) {
                                if (action_paid_for + chunk_of_1[i] - noo2u <= action_used) {
                                    dp[i + 1][action_used][action_paid_for + chunk_of_1[i] - noo2u] += cur;
                                }
                            } else if (noo2u == chunk_of_1[i]) {
                                dp[i + 1][action_used][action_paid_for] += cur;
                            } else {
                                int missing1 = noo2u - chunk_of_1[i];
                                if (missing1 > ones_left) break;

                                int new_action = action_used + missing1;
                                if (new_action > k) break;
                                dp[i + 1][new_action][action_paid_for] += cur;
                            }
                        }
                    }
                }
            }
            mi ans = 0;
            fori(i, number_of_1+1) ans += dp.back()[i][i];
            // </code here>
            out.println(ans);
        }
    };

public:
    void solve(std::istream &in, std::ostream &out) {
        Solver(in, out).solve();
    }
};

int main() {
	std::ios_base::sync_with_stdio(false), cin.tie(0);
	CShift solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

