int solvedp(int voy, int k, int tengo, int puse, string &s, vvvvi &dp) {
	if(voy == -1) {
		return tengo == 0;
	}

	if(dp[voy][k][tengo][puse] != -1) {
		return dp[voy][k][tengo][puse];
	}

	tint ans = 0;
	if(s[voy] == '0') {
		if(tengo) {
			ans += solvedp(voy, k, tengo-1, 1, s, dp);
			ans %= MOD;
		}

		if(!puse) {
			ans += solvedp(voy-1, k, tengo, 0, s, dp);
			ans %= MOD;
		} else {
			int next = voy-1;
			while(next >= 0 && s[next] == '1') next--;
			ans += solvedp(next, k, tengo, 0, s, dp);
			ans %= MOD;
		}
	} else {
		if(k) {
			ans += solvedp(voy-1, k-1, tengo+1, 0, s, dp);
			ans %= MOD;
		}
		int next = voy-1;
		while(next >= 0 && s[next] == '1') next--;
		ans += solvedp(next, k, tengo, 0, s, dp);
		ans %= MOD;
	}
	dp[voy][k][tengo][puse] = ans;
	return ans;
}

