    return 0;
  }
  if(j==m-1){
    if(abs(sum-csum-a.at(j))<=max_error-error){
      return 1;
    }else{
      return 0;
    }
  }

  if(3*abs(sum2.at(m)-sum2.at(j)-(sum-csum))<=max_error-error){
    return COM(sum-csum+m-j-1,sum-csum);
  }
  for(ll i=max<ll>(0,a.at(j)-(max_error-error));i<=min<ll>(sum-csum,a.at(j)+(max_error-error));i++){
    b.push_back(i);
    ret+=dfs(a,b,error+abs(a.at(j)-i),max_error,csum+i,sum,j+1);
    ret%=MOD;
    b.pop_back();
  }
  return ret;
}

