ll totalOnes = 0;
ll table[301][301][301];

int main(){
    std::cout<<std::fixed<<std::setprecision(10);

    string S;
    ll K;

    cin >> S >> K;

    vector<int> boxes;

    ll numOne = 0;
    for(int i = 0; i < S.size(); i++ ){
        if( S[i] == '0' ){
            boxes.push_back(numOne);
            numOne = 0;
        }else{
            numOne++;
            totalOnes++;
        }
    }
    boxes.push_back(numOne);

    REP(i,301){ REP(j,301) { REP(k,301) {
       if( i == 0 ){
          table[i][j][k] = 1;
       }else{
          table[i][j][k] = 0;
       }
    }}}

    ll currentOnes = boxes[0];
    for( int box = 1; box <= boxes.size()-1; box++ ){
        currentOnes += boxes[box];
        for( int ones = 0; ones <= (totalOnes-currentOnes); ones++){
           for( int ops = 0; ops <= min(K,totalOnes); ops++){
               for( int b = 0; b <= boxes[box]+ones; b++ ){
                  ll new_ops= ops - max(boxes[box]-b,0);
                  if( new_ops >= 0 ){
                     table[box][ones][ops] += (table[box-1][boxes[box]+ones-b][new_ops]%MOD);
                     table[box][ones][ops]%=MOD;
                  }
               }
           }
        }
    }

    cout << table[boxes.size()-1][0][min(K, totalOnes)] << endl;
}

