    cin >> K;
    K = min<unsigned long>(count(begin(S), end(S), '1'), K);

    vector dp(K + 1, vector(K + 1, 0UL)), tmp(K + 1, vector(K + 1, 0UL));
    dp[0][0] = 1;
    unsigned long cnt{0};
    for(const auto& c : S){
        if(c == '1')++cnt;
        else{
            for(auto&& i : tmp)fill(begin(i), end(i), 0UL);
            for(unsigned long i{0}; i < K; ++i){
                for(unsigned long j{0}; j + i < K; ++j){
                    tmp[j + i + 1][i] = tmp[j + i][i] + dp[j + i][i];
                    if(j >= cnt)tmp[j + i + 1][i] -= dp[j - cnt + i][i];
                }
            }
            for(auto&& i : dp)partial_sum(begin(i), end(i), begin(i));
            for(unsigned long i{0}; i <= K; ++i){
                for(unsigned long j{0}; j <= i; ++j){
                    (dp[i][j] += tmp[i][j]) %= MOD;
                }
            }
            cnt = 0;
        }
    }
    unsigned long ans{0};
    for(auto&& i : dp)partial_sum(begin(i), end(i), begin(i));
    for(unsigned long i{0}; i <= K; ++i)ans += dp[i][i];
