mint dp[301][301][301];
vll miny(301);
vll cury(301);
void solve()
{
    string S;
    ll K;
    in(S, K);
    ll idx = 0;
    // 先頭の'1'を取り除く
    while (idx < (ll)S.size() && S[idx] == '1') {
        idx++;
    }
    S = S.substr(idx);
    // 末尾の'0'を取り除く
    idx = S.size() - 1;
    while (idx >= 0 && S[idx] == '0') {
        idx--;
    }
    S = S.substr(0, idx + 1);
    dump(S);
    if (S.size() == 0) {
        print(1);
        return;
    }
    if (K == 0) {
        print(1);
        return;
    }
    ll len = S.size();
    ll y = 0;
    ll x = 0;
    miny[0] = 0;
    for1 (i, len) {
        if (S[i] == '0') {
            x++;
            miny[x] = y;
            cury[x] = y;
        }
        else {
            y++;
            cury[x] = y;
        }
    }
    chmin(K, 300LL);
    dp[0][0][0] = 1;
    ll maxy = y;
    ll maxx = x;
    // dump(miny);
    // dump(cury);
    for1 (x, maxx + 1) {
        for1 (k, K + 1) {
            for1 (y, maxy + 1) {
                // dump(y, x, k);
                if (x == 0 && y == 0) continue;
                if (y < miny[x]) continue;
                if (x > 0) {
                    dp[y][x][k] += dp[y][x - 1][k];
                }
            }
            for2 (y, 1, maxy + 1) {
                if (k > 0 && y >= cury[x] + k) {
                    // dump("!!!", y, x, k);
                    dp[y][x][k] += dp[y - 1][x][k - 1];
                }
            }
            // ノーコストで上がれる幅は cury[x]-miny[x]
            if (cury[x] != miny[x]) {
                vector<mint> cdp(maxy + 2);
                for1 (y, maxy + 1) {
                    cdp[y + 1] += cdp[y] + dp[y][x][k];
                }
                for2 (y, miny[x] + 1, maxy + 1) {
                    ll y2 = max(y - 1, miny[x]);
                    ll y1 = max(y - (cury[x] - miny[x]), miny[x]);
                    dp[y][x][k] += cdp[y2 + 1] - cdp[y1];
                }
            }
        }
    }
    /*
    for1 (k, K + 1) {
        dump(k);
        for1 (y, maxy + 1) {
            cerr << "y=" << y << ": ";
            for1 (x, maxx + 1) {
                cerr << dp[y][x][k] << " ";
            }
            cerr << endl;
        }
    }
    */
    mint ans = 0;
    for1 (k, K + 1) {
        dump(maxy, maxx, k, dp[maxy][maxx][k]);
        ans += dp[maxy][maxx][k];
    }
    print(ans);
}
