using namespace std;
typedef long long ll;

constexpr ll MOD = 998244353;

int main() {
    string s;
    int k;
    cin >> s >> k;
    int n = s.size();
    reverse(s.begin(), s.end());

    int oneCount = 0;
    while (oneCount < n && s[oneCount] == '1')oneCount++;

    vector<vector<ll>> dp(n + 1, vector<ll>(n + 1));
    for (int i = 0; i <= oneCount; i++) dp[i][oneCount - i] = 1;
    for (int i = 0; i < n; i++) {
        if (s[i] == '1') continue;

        int followingOne = 0;
        while (i + followingOne + 1 < n && s[i + followingOne + 1] == '1')followingOne++;

        vector<vector<ll>> after(n + 1, vector<ll>(n + 1));
        for (int prevCount = 0; prevCount <= oneCount; prevCount++) {
            for (int nowCount = prevCount; nowCount <= oneCount + followingOne; nowCount++) {
                for (int prevCost = 0; prevCost <= n; prevCost++) {
                    int add = nowCount - prevCount, nowCost = -1;
                    if (add <= followingOne) {
                        nowCost = prevCost + (followingOne - add);
                    } else {
                        int remain = oneCount - prevCount;
                        nowCost = prevCost + max(0, (add - followingOne) - remain);
                    }

                    if (nowCost > n)continue;
                    after[nowCount][nowCost] += dp[prevCount][prevCost];
                    after[nowCount][nowCost] %= MOD;
                }
            }
        }

        oneCount += followingOne;
        dp = after;
    }

    ll ret = 0;
    for (int j = 0; j <= min(n, k); j++)ret += dp[oneCount][j], ret %= MOD;
    cout << ret << endl;
    return 0;
}

