const int N = 305;

Mint dp[N][N][N];

void solve() {
	string s;
    sc(s);
    int K;
    sc(K);
    int n = sz(s);
    vector<int> v, pre;
    if(s[0] == '0') {
        v.pb(0);
    }
    else {
        int j = 0;
        while(j < n && s[j] == '1') j++;
        v.pb(j - 1);
    }
    fr(i, 0, n - 1) {
        if(s[i] == '0') {
            int j = i + 1;
            while(j < n && s[j] == '1') j++;
            v.pb(j - i - 1);
        }
    }
    int sum = 0;
    fr(i, 0, sz(v) - 1) {
        sum += v[i];
        pre.pb(sum);
    }
    dp[0][0][0] = 1;
    int nn = sz(v);
    fr(i, 0, nn) {
        fr(j, 0, n) {
            fr(k, 0, n) {
                if(!dp[i][j][k]) continue;
                Mint val = dp[i][j][k];
                int used = (i == 0 ? 0 : pre[i - 1]) + j;
                if(i == nn) continue;
                int lr = max(v[i] - j, 0);
                int rr = pre[nn - 1] - used;
                int kk;
                fr(l, lr, rr) {
                    kk = k + max(0, l - v[i]);
                    dp[i + 1][j + l - v[i]][kk] += val;
                }
            }
        }
    }
    Mint ans = 0;
    fr(k, 0, min(pre[nn - 1], K))
        ans += dp[nn][0][k];
    cout << ans;
}

