                // }
            }
        }
        for(int j = 1; j <= sum; j++){
            for(int k = 1; k <= 2*K; k++){
                buf1[j][k] += buf1[j-1][k-1];
                buf1[j][k] %= MOD;
            }
        }
        for(int j = 1; j <= sum+2*K; j++){
            for(int k = 1; k <= j; k++){
                int l = j-k;
                buf0[k][l] += buf0[k-1][l+1];
                buf0[k][l] %= MOD;
            }
        }

        for(int j = 0; j <= 300; j++){
            for(int k = 0; k <= 600; k++){
                dp[i+1][j][k] = buf0[j][k]+buf1[j][k];
                dp[i+1][j][k] %= MOD;
            }
        }
        tmp += v[i];
    }
    ll ans = 0;

    for(int i = 0; i <= 2*K; i++){
        ans += dp[sz][sum][i];
        ans %= MOD;
    }
    cout << (ans+MOD)%MOD << endl;
}

