int main() {
    ll mod = 998244353;
    string S;
    cin >> S;
    int N = S.size();
    int K;
    cin >> K;
    if (count(S.begin(), S.end(), '0') == 0 || count(S.begin(), S.end(), '1') == 0) {
        cout << 1 << endl;
        return 0;
    }

    vector<ll> A;
    ll cnt = 0;
    for (int i = 0; i < N; i++) {
        if (S[i] == '0') {
            A.push_back(cnt);
            cnt = 0;
        }
        else cnt++;
    }
    A.push_back(cnt);
    ll M = A.size();
    vector<ll> Asum(M);
    Asum[0] = A[0];
    for (int i = 1; i < M; i++) Asum[i] = Asum[i-1]+A[i];


    vector<vector<ll>> from(N+1, vector<ll>(N+1, 0));
    from[0][0] = 1;
    for (int i = 0; i < M; i++) {
        vector<vector<ll>> to(N+1, vector<ll>(N+1, 0));
        vector<vector<ll>> nanamesum(N+2, vector<ll>(N+2, 0));
        for (int j = 0; j <= N; j++) {
            for (int k = 0; k <= N; k++) {
                if (j >= 1 && k >= 1) nanamesum[j][k] = (nanamesum[j-1][k-1] + from[j][k])%mod;
                else nanamesum[j][k] = from[j][k];
                //cout << i << j << k << " " << nanamesum[j][k] << endl;
            }
        }

        for (int k = 0; k <= N; k++) {
            to[N][k] = nanamesum[N][k];
            ll sum = 0;
            if (A[i] > 0) sum = from[N][k];
            for (int j = N-1; j >= 0; j--) {
                to[j][k] = (nanamesum[j][k] + sum)%mod;
                sum += from[j][k];
                if (j+A[i] <= N) {
                    sum -= from[j+A[i]][k];
                    if (sum < 0) sum += mod;
                }
                //cout << i << j << k << " " << to[j][k] << endl;
            }
        }
        swap(from, to);
    }

    ll ans = 0;
    for (ll i = 0; i <= min(N, K); i++) ans += from[0][i];
    cout << ans%mod << endl;
    return 0;
}

