typedef int32_t i32;
typedef uint64_t u64;

const u64 mod = 998244353;

#define ALLOC(size,type) ((type*)calloc((size),sizeof(type)))
#define POS(i, j) ((i) * len + (j))

void run (void) {
    char *s = ALLOC (301, char);
    i32 k;
    scanf ("%s%" SCNi32, s, &k);
    i32 len = strlen (s);
    u64 *buf = ALLOC (2 * len * len, u64);
    u64 *dp = buf;
    u64 *next = buf + len * len;
    dp[POS(0, 0)] = 1;
    i32 size = 1;
    for (i32 i = len - 1, one = 0; i >= 0; --i) {
        if (s[i] == '1') {
            one += 1;
            continue;
        }
        i32 w = size + one;
        for (i32 i = 0; i < w; ++i) {
            for (i32 j = 0; j < w; ++j) {
                next[POS(i, j)] = 0;
            }
        }
        for (i32 i = 0; i < w; ++i) {
            u64 s = 0;
            for (i32 j = 0; j <= i; ++j) {
                s += dp[POS(i, j)];
                next[POS(i, j)] = s;
            }
        }
        for (i32 i = 0; i < w; ++i) {
            for (i32 j = 0; j <= i; ++j) {
                for (i32 k = i + 1; k < i + 1 + one; ++k) {
                    next[POS(k, j)] += dp[POS(i, j)];
                }
            }
        }
        one = 0;
        u64 *swap = dp;
        dp = next;
        next = swap;
        size = w;
        for (i32 i = 0; i < size; ++i) {
            for (i32 j = 0; j <= i; ++j) {
                dp[POS(i, j)] %= mod;
            }
        }
    }
    u64 ans = 0;
    i32 w = size - 1 < k ? size - 1 : k;
    for (i32 i = 0; i <= w; ++i) {
        for (i32 j = 0; j <= i; ++j) {
            ans += dp[POS(i, j)];
        }
    }
    ans %= mod;
    printf ("%" PRIu64 "\n", ans);
}

int main (void) {
    run();
    return 0;
}

