const long long MAXN = 310;
const long long MOD = 998244353;
long long dp[MAXN][MAXN][MAXN];
long long b[MAXN][MAXN];
long long n;
long long c[MAXN][MAXN];
long long arr[MAXN];
int main(){
    string s;
    cin>>s;
    long long m;
    cin>>m;
    m = min(m,(long long)s.length());
    long long len = s.length();
    long long last = -1;
    n++;
    for(long long i=0;i<s.length();i++){
        if(s[i] == '0'){

            arr[n] = i-last - 1;
             n++;
            last = i;
        }
    }
    arr[n] = s.length() - last - 1;
    dp[0][0][0] = 1;
    //dp[i][j][k] = i one segments, difference between pref[i] and newpref[i] = j, k operations performed
    for(long long i=1;i<=n;i++){
        for(long long j=0;j<=len;j++){
            for(long long k=0;k<=m;k++){
                b[j][k] = 0;
                c[j][k] = 0;
            }
        }

        for(long long j=0;j<=len;j++){
            for(long long k=0;k<=m;k++){
                long long hold = dp[i-1][j][k];
                if(hold == 0){
                    continue;
                }
                b[j-min(j,arr[i])][k]+=hold;
                b[j-min(j,arr[i])][k]%=MOD;
                b[j+1][k]-=hold;
                b[j+1][k]+=MOD;
                b[j+1][k]%=MOD;
                c[j+1][k+1]+=hold;
                c[j+1][k+1]%=MOD;

                //b[j][k] = transfers from the ith segment to earlier segments(b[j][k] holds dp[i-1][j+arr[i]][k]+dp[i-1][j+arr[i]-1][k]+dp[i-1][j+arr[i]-2][k]+...+dp[i-1][j][k])
                //c[j][k] = transfers before the ith segement, new ones added to the current segment is added from the right(c[j][k] holds dp[i-1][j-1][k-1]+dp[i-1][j-2][k-2]+dp[i-1][j-3][k-3]+....)


            }
        }
        for(long long j=0;j<=len;j++){
            for(long long k=0;k<=m;k++){
                if(j){
                    b[j][k] += b[j-1][k];
                    b[j][k]%=MOD;
                }
                if(j && k){
                    c[j][k]+=c[j-1][k-1];
                    c[j][k]%=MOD;
                }
                dp[i][j][k] = b[j][k]+c[j][k];
                dp[i][j][k]%=MOD;
            }
        }
    }
    long long ans = 0;
    for(long long i=0;i<=m;i++){
        ans+=dp[n][0][i];
        ans%=MOD;
    }
    cout<<ans<<endl;
}

