int dp(int now, int left, int moves){
    if(moves < 0){
        return 0;
    }
    if(now == vec.size()){
        if(left == 0)return 1;
        else return 0;
    }

    int& ret = memo[now][left][moves];
    if(ret != -1)return ret;

    ret = 0;

    int min_place = max(0, pf[now] - (n1 - left));
    REP(place, min_place, left){
