const int MOD = 998244353;

int main(void){
    int N, K;
    string S;
    vector<int> numOne(1, 0);
    int numOneAll = 0;
    //dp[i][j][k] : numOne[i to max], j times moved, numOne[i]+=k
    vector<vector<vector<int>>> dp;
    cin >> S >> K;
    N = S.size();
    for(int i=0; i<N; i++){
        if(S[i]=='0'){
            numOne.push_back(0);
        }else{
            numOne[numOne.size()-1]++;
            numOneAll++;
        }
    }
    int efcK = min(K, numOneAll);
    dp.assign(numOne.size(), vector<vector<int>>(efcK+1, vector<int>(efcK+1, 0)));
    dp[numOne.size()-1][0][0] = 1;
    for(int i=numOne.size()-2; i>=0; i--){
        for(int j=0; j<=efcK; j++){
            int dpsumbuf = 0;
            for(int k=j; k>=0; k--){
                //terms of the same k
                dpsumbuf += dp[i+1][j][k];
                dpsumbuf %= MOD;
                dp[i][j][k] += dpsumbuf;
                dp[i][j][k] %= MOD;
            }
            //terms of the different k
            dpsumbuf = 0;
            for(int k=0; j+k+1<=efcK; k++){
                //use only numOne[i+1] terms
                dpsumbuf += dp[i+1][j+k][k];
                dpsumbuf %= MOD;
                if(k >= numOne[i+1]){
                    dpsumbuf += MOD - dp[i+1][j+k-numOne[i+1]][k-numOne[i+1]];
                    dpsumbuf %= MOD;
                }
                dp[i][j+k+1][k+1] += dpsumbuf;
                dp[i][j+k+1][k+1] %= MOD;
            }
        }
    }
    int res = 0;
    for(int j=0; j<=efcK; j++){
        for(int k=0; k<=j; k++){
            res += dp[0][j][k];
            res %= MOD;
        }
    }
    cout << res << endl;
    return 0;
}

