    if(S[i] == '1'){
      len++;
      N1++;
    }else{
      one.emplace_back(len);
      len = 0;
      N0++;
    }
  }
  one.emplace_back(len);
  vector<int> oneS;
  oneS = one;
  for(int i=1; i<one.size(); i++){
    oneS[i] += oneS[i-1];
  }
