  dp[0][0][0] = 1;
  for(int i=0; i<=N0; i++){
    // 区間iの1の数はone[i]未満
    for(int j=0; j<=K; j++){
      // sは(k-one[i],k]の区間の累積和
      ll s = 0;
      for(int k=0; k<=N1; k++){
        s += dp[i][j][k];
        if(k >= one[i]){
          s -= dp[i][j][k-one[i]];
          s += mod;
          s %= mod;
        }
        // kがoneS[i]以上じゃなければ遷移できない
        if(k >= oneS[i]){
          dp[i+1][j][k] += s;
          dp[i+1][j][k] %= mod;
