    if(st.empty() || st.back().first != S[i] || S[i] == '0') {
      st.emplace_back(S[i], 0);
    }
    st.back().second++;
  }

  auto dp = make_v< modint >(K + 1, K + 1);
  dp[0][0] = 1;
  vector< int > sum(st.size() + 1);
  for(int i = (int) st.size() - 1; i >= 0; i--) {
    sum[i] = sum[i + 1];
    if(st[i].first == '1') sum[i] += st[i].second;
    chmin(sum[i], K);
  }

  for(int i = 0; i < st.size(); i++) {
    auto dp2 = make_v< modint >(K + 1, K + 1);
    if(i + 1 < st.size() && st[i].first == '1' && st[i + 1].first == '0') {
      for(int j = 0; j <= sum[i]; j++) {
        for(int k = j; k <= K; k++) {
          for(int l = 0; l <= st[i].second && j - l >= 0; l++) { // 減らす or 変えない
            dp2[k][j - l] += dp[k][j];
          }
          for(int l = 1; j + l <= sum[i + 1] && k + l <= K; l++) {
            dp2[k + l][j + l] += dp[k][j];
          }
        }
      }
      ++i;
    } else if(st[i].first == '0') {
      for(int j = 0; j <= sum[i]; j++) {
        for(int k = j; k <= K; k++) {
          for(int l = 0; j + l <= sum[i] && k + l <= K; l++) {
            dp2[k + l][j + l] += dp[k][j];
          }
        }
      }
    } else {
      for(int k = 0; k <= K; k++) {
        for(int j = 0; j <= sum[i]; j++) {
          dp2[k][max(0, j - st[i].second)] += dp[k][j];
          if(j + 1 <= K) dp2[k][j + 1] -= dp[k][j];
        }
        for(int j = 1; j <= K; j++) {
          dp2[k][j] += dp2[k][j - 1];
        }
      }
    }
    dp.swap(dp2);
  }

  modint ret = 0;
  for(int i = 0; i <= K; i++) ret += dp[i][0];
  cout << ret << "\n";
}

