		dptable[a][b][c][d] = (dptable[a][b][c][d] + dp(a + 1, b + cnt[a + 1], c, 0)) % mod;
		return dptable[a][b][c][d];
	} else return dptable[a][b][c][d] = (dp(a, b, c, 1) + dp(a, b + 1, c - 1, 0)) % mod;
}
