typedef long long ll;
const int MAXN = 310;
const ll MOD = 998244353;

int N;
string S;
int K;

int N0, N1;
int nbuck[MAXN];
int ps[MAXN];

ll dp[MAXN][2*MAXN][MAXN]; // i=bucket, j=#1s, k=sum of smaller vals
ll dps[MAXN][2*MAXN][MAXN];

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> S >> K;
    N = S.length();
    for (int i = 0; i < S.length(); i++)
    {
        if (S[i] == '0') N0++;
        else
        {
            nbuck[N0]++;
            N1++;
        }
    }

    ps[0] = 0;
    for (int i = 0; i < MAXN - 1; i++)
        ps[i+1] = ps[i] + nbuck[i];

    N0++;
    dp[0][0][0] = 1;
    for (int i = 0; i <= N0; i++)
    {
        //cout << i << " " << nbuck[i] << "\n";
        for (int k = 0; k <= N; k++)
        {
            for (int j = 1; j <= N; j++)
            {
                dps[i][j][k] += dps[i][j-1][k];
                dps[i][j][k] %= MOD;
            }
        }

        for (int j = ps[i]; j <= N1; j++)
        {
            for (int k = 0; k <= N; k++)
            {
                dp[i][j][k] = (dp[i][j][k] + dps[i][j][k]) % MOD;
                if (!dp[i][j][k]) continue;
                //cout << i << " " << j << " " << k << " " << dp[i][j][k] << "\n";
                for (int l = 0; l < nbuck[i]; l++)
                {
                    dp[i+1][j+l][k+nbuck[i]-l] += dp[i][j][k];
                    dp[i+1][j+l][k+nbuck[i]-l] %= MOD;
                }
                dps[i+1][j+nbuck[i]][k] += dp[i][j][k];
                dps[i+1][j+nbuck[i]][k] %= MOD;
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i <= N; i++)
    {
        if (i <= K)
            ans = (ans + dp[N0][N1][i]) % MOD;
    }
    cout << ans << "\n";
}

