    mint& operator*=(const mint a) { (x *= a.x) %= MOD; return *this;}
    mint operator+(const mint a) const { return mint(*this) += a;}
    mint operator-(const mint a) const { return mint(*this) -= a;}
    mint operator*(const mint a) const { return mint(*this) *= a;}
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime MOD
    mint inv() const { return pow(MOD-2);}
    mint& operator/=(const mint a) { return *this *= a.inv();}
    mint operator/(const mint a) const { return mint(*this) /= a;}
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}
typedef vector<mint> Vmint;

struct combination {
    vector<mint> fact, ifact;
    combination(int n):fact(n+1),ifact(n+1) {
        assert(n < MOD);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
    }
    mint operator()(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n]*ifact[k]*ifact[n-k];
    }
};

int solve(){
    string s;
    ll k;
    cin>>s>>k;
    vector<pair<char, ll>> rl = run_length_encoding(s);
    ll n = s.length();
    k = min(n,k);
    dbg(rl);
    Vec v(n);
    ll id = 0;
    Each(p, rl){
        if(p.fi=='0'){
            id += p.se;
        } else{
            v[id] = p.se;
        }
    }

    reverse(ALL(v));
    dbg(v);

    vector<vector<Vmint>> dp (n+1,vector<Vmint>(n+1, Vmint(n+1,0)));
    dp[0][0][0] = 1;
    //i番目まででsub個引いてadd足した場合。
    rep(i,n){
        rep(sub,n+1){
            rep(add,sub+1){
                //sub
                rep(cnt,v[i]+1){
                    if(sub+cnt>k)continue;
                    dp[i+1][sub+cnt][add] += dp[i][sub][add];
                }
                //add
                if(sub<add)continue;
                REP(cnt,1,n+1){
                    if(add+cnt>k)continue;
                    dp[i+1][sub][add+cnt] += dp[i][sub][add];
                }
            }
        }
    }
    mint ans = 0;
   // dbg(dp);
    rep(i,k+1){
        ans += dp[n][i][i];
    }
    out(ans);
    return  0;
}

