bool visited[303][303][303];

// [x, y, 操作回数]
mint rec(int x, int y, int k) {
    if (k > K) return mint(0);
    if (x == 0) return mint(1);
    if (visited[x][y][k]) return dp[x][y][k];
    visited[x][y][k] = true;
    mint ret = 0;

    // 上から
    if (v[x - 1] >= y + 1) ret += rec(x, y + 1, k);

    // 左から
    if (v[x - 1] == y)  ret += rec(x - 1, y, k);
    else ret += rec(x - 1, y, k + 1);

    return dp[x][y][k] = ret;
}

