mint get_sum(int len,int steps,int extra){
	if (extra == -1){
		return 0;
	}
	if (vis2[len][steps][extra]){
		return pref_sum[len][steps][extra];
	}

	vis2[len][steps][extra] = true;
	pref_sum[len][steps][extra] = ways(len,steps,extra) + get_sum(len,steps,extra-1);
	return pref_sum[len][steps][extra];

}

mint get_sum2(int len,int steps,int total){
	if (steps == -1) return 0;

	if (vis3[len][steps][total]) return diag_sum[len][steps][total];

	vis3[len][steps][total] = true;

	mint& ans = diag_sum[len][steps][total];

	ans = ways(len,steps,total - steps) + get_sum2(len,steps - 1, total);
	return ans;
}

vector<int> curr;

mint ways(int len,int steps,int extra){
	assert(steps >= 0 && len>=0 && extra >=0);

	if (vis[len][steps][extra]){
		return dp[len][steps][extra];
	}
	if (len == 0){
		if (extra != 0) return 0;
		return 1;
	}
	vis[len][steps][extra] = true;
	mint& ans = dp[len][steps][extra];
	ans = get_sum(len-1,steps,extra);
	// for(int u = 1;u<=extra;++u){
		// ans += ways(len-1,steps,extra-u);
	// }
	// for(int z = 1; z<=curr[len-1] && z<=steps;++z){
		// ans += ways(len-1,steps-z,extra + z);
	// }
	ans += get_sum2(len-1,steps - 1, steps + extra);
	if (curr[len-1] < steps){
		ans -= get_sum2(len-1,steps - 1 - curr[len-1],steps + extra);
	}
	return ans;
}


