                    U[i+1][A+1][A+1-nj+nk] %= mod;
                }
                U[i+1][j+1][k+1] += U[i+1][j][k];
                U[i+1][j+1][k+1] %= mod;
            }
        }
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                int nj = j, nk = k + T[i];
                if (nj < C) {
                    int d = C - nj;
                    nj += d, nk -= d;
                }
                if (nk > k) {
                    D[i+1][nj][nk] += P[i][j][k];
                    D[i+1][nj][nk] %= mod;
                    D[i+1][j+T[i]][k] += mod - P[i][j][k];
                    D[i+1][j+T[i]][k] %= mod;
                }
                if (k) {
                    D[i+1][j+1][k-1] += D[i+1][j][k];
                    D[i+1][j+1][k-1] %= mod;
                }
            }
        }
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                P[i+1][j][k] = (U[i+1][j][k] + D[i+1][j][k]) % mod;
            }
        }        
    }
    long long Ans = 0;
    for (int i = 0; i <= 2*K; i++) {
        Ans += P[N][A][i] % mod;
    }
    cout << Ans % mod << "\n";
    return 0;
}

