vi clean(string& s) {
  vi ret;
  int idx = 0;
  int n = s.size();
  rep (i, n) {
    if (s.at(i) == '0') {
      ret.push_back(i - idx);
      idx = i + 1;
    }
  }
  if (idx < n) {
    ret.push_back(idx - n);
  }
  return ret;
}

