void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	string s;
	int k;

	while (cin >> s >> k)
//	s = string(150, '0') + string(150, '1');
//	k = int(1e9);

	{
		vector<int> parts;

		{
			int cur_part = 0;
			for (int i = 0; i < int(s.size()); i++)
			{
				if (s[i] == '0')
				{
					parts.push_back(cur_part);
					cur_part = 0;
				}
				else
					cur_part++;
			}
			parts.push_back(cur_part);
		}

		vector<int> sums(parts.size() + 1);
		partial_sum(parts.begin(), parts.end(), sums.begin() + 1);

		vector<vector<vector<int>>> dp(int(parts.size()) + 1, vector<vector<int>>(sums.back() + 1,
		                                                                          vector<int>(sums.back() + 1)));
		dp[0][0][0] = 1;

		for (int i = 0; i + 1 < int(dp.size()); i++)
			for (int j = sums[i]; j < int(dp[i].size()); j++)
				for (int ops = 0; ops < int(dp[i][j].size()); ops++)
				{
					const int cur = dp[i][j][ops];
					const int debt = j - sums[i];

					if (cur && debt <= sums.back() - sums[i])
					{
						assert(debt >= 0);

						for (int pay = 1; pay <= min(debt, parts[i]) && ops + pay <= int(sums.back()); pay++)
						{
							if (j + parts[i] - pay <= int(sums.back()))
								add(dp[i + 1][j + parts[i] - pay][ops + pay], cur);
						}

						for (int borrow = 0; j + borrow + parts[i] <= sums.back(); borrow++)
						{
							assert(j + borrow + parts[i] <= sums.back());
							add(dp[i + 1][j + borrow + parts[i]][ops], cur);
						}
					}
				}

		int ans = 0;
		for (int i = 0; i < min(k + 1, int(dp.back()[sums.back()].size())); i++)
			add(ans, dp.back()[sums.back()][i]);
		cout << ans << endl;
	}
}

