constexpr int64 P = 998244353;

struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 x) : x(x) {
    if (x > P || x < 0) { cerr << "Invalied FiniteField!" << endl; exit(1); }
  }
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

template<typename T>
vector<vector<vector<T>>>
Make3DVector(int d1, int d2, int d3, T default_value) {
  return vector<vector<vector<T>>>(
      d1, vector<vector<T>>(d2, vector<T>(d3, default_value)));
}

FiniteField Solve() {
  string s;
  int64 op_max;
  cin >> s >> op_max;

  // for (int i = 0; i < 100; i++) s.push_back('0');
  // for (int i = 0; i < 200; i++) s.push_back('1');
  // op_max = 1E9;

  if (op_max == 0) return 1;

  auto encode_fn = [](const string& s) -> vector<int> {
    vector<int> xs;
    int count = 0;
    for (char c : s) {
      if (c == '1') {
        count++;
      } else if (c == '0') {
        xs.push_back(count);
        count = 0;
      }
    }
    xs.push_back(count);
    reverse(xs.begin(), xs.end());
    return xs;
  };
  vector<int> xs = encode_fn(s);
  int n = xs.size();
  if (n == 1) return 1;

  int m = 0;
  for (char c : s) {
    if (c == '1') {
      m++;
    }
  }

  if (m == 0) return 1;

  if (DEBUG) cout << "xs: " << xs << endl;

  auto dp = Make3DVector<FiniteField>(n + 1, m + 1, m + 1, 0);

  dp[0][0][0] = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= m; j++) {
      for (int k = 0; k <= j; k++) {
        dp[i][j][k] += dp[i - 1][j][k];
        for (int l = 1; k + l <= j; l++) {
          dp[i][j][k] += dp[i - 1][j][k + l];
        }
        for (int l = 1; j - l >= 0 && k - l >= 0 && l <= xs[i - 1]; l++) {
          dp[i][j][k] += dp[i - 1][j - l][k - l];
        }
      }
    }
  }

  FiniteField ans = 0;
  for (int i = 0; i <= m && i <= op_max; i++) {
    ans += dp[n][i][0];
  }
  return ans;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve().Value() << endl;
}

