const int maxN = 311;
const int mod = 998244353;

int n, k;
char s[maxN];
vector<int> groups;
int dp[maxN][maxN][maxN];

void upd(int& dest, int sour, int coef = 1) {
  dest += (1LL * sour * coef) % mod;
  if (dest >= mod) dest -= mod;
}

void getGroups() {
  int curr = 0;
  for (int i = 0; i < n; i++) {
    if (s[i] == '1') {
      curr++;
    } else {
      groups.pb(curr);
      curr = 0;
    }
  }
  groups.pb(curr);
}

void compute() {
  dp[0][0][0] = 1;
  for (int i = 0; i < groups.size(); i++) {
    int nextCount = groups[i];

    for (int active = 0; active <= k; active++) {
      for (int used = active; used <= k; used++) {
         if (dp[i][active][used] == 0) continue;

         int limit = min(nextCount, active);
         for (int taken = 1; taken <= limit; taken++)
           upd(dp[i + 1][active - taken][used], dp[i][active][used]);

         limit = k - used;
         for (int added = 1; added <= limit; added++)
           upd(dp[i + 1][active + added][used + added], dp[i][active][used]);

        upd(dp[i + 1][active][used], dp[i][active][used]);
      }
    }
  }
}

