    A.push_back(j - i);
    i = j;
  }

  const int N = A.size();
  vector<int> sa(N + 1);
  for (int i = N - 1; ~i; --i) sa[i] = sa[i + 1] + A[i];

  static int d[301][301][301];
  static int svd[302][301]; // sum vertical
  static int dgd[602][302]; // sum diagonal
  d[N][0][0] = 1;
  for (int i = N - 1; ~i; --i) {
    for (int t = 0; t <= min(K, 300); ++t) {
      for (int s = 0; s <= 300; ++s) {
        svd[s + 1][t] = (svd[s][t] + d[i + 1][s][t]) % M;
      }
    }
    for (int r = 0; r <= 300; ++r) {
      for (int c = 0; c <= r; ++c) {
        dgd[r][c + 1] = (dgd[r][c] + d[i + 1][r - c][c]) % M;
        dgd[300 + r][c + 1] = (dgd[300 + r][c] + d[i + 1][300 + r - c][c]) % M;
      }
    }
    for (int s = 0; s <= sa[i]; ++s) {
      for (int t = 0; t <= min(K, 300); ++t) {
        if (1 <= min(sa[i + 1], s - A[i])) {
          (d[i][s][t] += svd[s - (A[i] + 1) + 1][t]) %= M;
          (d[i][s][t] -= svd[s - (A[i] + min(sa[i + 1], s - A[i]))][t]) %= M;
        }
        if (max(A[i] - s, 0) <= min(A[i], t)) {
          (d[i][s][t] += dgd[s - A[i] + t][t - max(A[i] - s, 0) + 1]) %= M;
          (d[i][s][t] -= dgd[s - A[i] + t][t - min(A[i], t)]) %= M;
          /* for (int j = max(A[i] - s, 0); j <= min(A[i], t); ++j) { */
          /*   (d[i][s][t] += d[i + 1][s - (A[i] - j)][t - j]) %= M; */
          /* } */
        }
      }
    }
  }

  /* for (int i = N; ~i; --i) */
  /*   for (int j = 0; j <= 300; ++j) */
  /*     for (int k = 0; k <= 300; ++k) */
  /*       if (d[i][j][k]) */
  /*         printf("d[%d][%d][%d] = %d\n", i, j, k, d[i][j][k]); */

  int res = 0;
  for (int i = 0; i <= min(300, K); ++i) {
    (res += d[0][sa[0]][i]) %= M;
  }
  if (res < 0) res += M;

  cout << res << endl;

  return 0;
}

