const int MOD = 998244353;
const int MAXN = 305;

char s[MAXN];
int n, k, nxt[MAXN], dp[MAXN][MAXN][MAXN];

int main(){	
	scanf("%s %d", s, &k);
	n = strlen(s);
	k = min(n, k);

	for(int i = n; i >= 0; i--){
		if(i == n)nxt[i] = i;
		else if(s[i] == '0')nxt[i] = i;
		else nxt[i] = nxt[i + 1];
	}

	for(int i = n; i >= 0; i--)
	for(int j = n; j >= 0; j--)
	for(int r = 0; r <= k; r++){
		if(i == n){
			if(j == 0)dp[i][j][r] = 1;
			else dp[i][j][r] = 0;
		}else{
			if(s[i] == '0'){
				dp[i][j][r] = dp[i + 1][j][r];
				if(r > 0 && j + 1 <= n)dp[i][j][r] = (dp[i][j][r] + dp[i][j + 1][r - 1]) % MOD;
			}else{
				dp[i][j][r] = dp[i + 1][j][r];
				if(j >= nxt[i] - i)dp[i][j][r] = (dp[i][j][r] + dp[(nxt[i] == n ? n : nxt[i] + 1)][j - (nxt[i] - i)][r]) % MOD;
			}
		}
	}

	printf("%d\n", dp[0][0][k]);

	return 0;
}

