	for (int i = 0; i <= n; ++i) {
		if (i == n || str[i] == '0') {
			A.push_back(num1);
			num1 = 0;
		} else ++num1;
	}
//	dbv(A);
	int m = A.size();
	for (int k = 0; k <= K; ++k) F[k][0] = 1;
	for (int i = m - 1; i >= 0; --i) {
		swap(F, oldF);
		for (int k = K; k >= 0; --k) {
			for (int j = K; j >= 0; --j) {
				G[k][j] = G[k + 1][j + 1] + oldF[k][j];
			}
			Mint sum = 0;
			for (int j = 0; j <= K; ++j) {
				sum += oldF[k][j];
				if (j > A[i]) sum -= oldF[k][j - A[i] - 1];
