      vector<vector<Mint>> dec(K + 1, vector<Mint>(K + 1));
      for (int deg = 0; deg <= K; ++deg) {
         for (int tot = 0; tot <= K; ++tot) {
            if (deg) inc[deg - 1][tot] += dp[deg][tot];
            if (deg < K && tot < K) dec[deg + 1][tot + 1] += dp[deg][tot];
