int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  std::string S; int K; std::cin >> S >> K;
  std::vector<int> a;
  int sum_one = 0, k = 0;
  for(auto it = S.rbegin(); it!= S.rend(); ++it) {
    if(*it == '1') ++sum_one;
    else if(sum_one > 0) { 
      a.push_back(sum_one);
      k += sum_one;
    }
  }
  if(K > k) K = k;
  auto tmp = mk2d(K+1, sum_one+1, mint(0)); 
  auto dp = mk1d(a.size()+1, tmp);
  dp[0][0][0] = 1;
  for(int i = 0; i < a.size(); ++i) {
    std::vector<std::vector<mint>>& cur = dp[i+1];
    std::vector<std::vector<mint>>& pre = dp[i];
    int ai1 = 0;
    if(i > 0) ai1 = a[i-1];
    for(int l = 0; l <= ai1; ++l) {
      int p = ai1 - l;
      for(int k = 0; k <= K; ++k) {
        int ma = std::min(K-k+p, a[i]-l);
        for(int j = 0; j <= std::min(p, ma); ++j) cur[k][a[i]-j] += pre[k][l];
        for(int j = p+1; j <= ma; ++j) cur[k+j-p][a[i]-j] += pre[k][l];
      }
    }
  }
  mint ans;
  for(int k = 0; k <= K; ++k) for(int l = 0; l <= sum_one; ++l) ans += dp[a.size()][k][l];
  fin(ans.v_);
  return 0;
}

