	}
	M += 1;
	// debug(vi(A, A + M));
	rep(i, 0, M) {
		D[i + 1] = D[i] + A[i];
	}
	N = accumulate(A, A + N, 0);
	int now = 0, nex = 1;
	dp[0][0][0] = 1;
	rep(i, 0, M) {
		memset(dp[nex], 0, sizeof(dp[nex]));
		memset(ep, 0, sizeof(ep));
		// put less then A[i]
		rep(j, 0, N + 1) { //how many put
			if(j < D[i]) continue;
			rep(k, 0, N + 1) { //diff
				ADD(dp[nex][j + A[i]][k + A[i]], mod - dp[now][j][k]);
				ADD(dp[nex][j][k], dp[now][j][k]);
			}
		}
		rep(j, 0, N + 1) {
			rep(k, 0, 610) {
				if(j + k <= 610) {
					ADD(dp[nex][j + 1][k + 1], dp[nex][j][k]);
