		// 		debug(i, j, k, dp[nex][j][k]);
		// 	}
		// }
		// debug("omoend");
		//else
		rep(j, 0, N + 1) {
			rep(k, 0, N + 1) {
				if(j + A[i] <= N && j >= D[i]) {
					ADD(ep[j + A[i]][k + A[i]], dp[now][j][k]);
					ADD(ep[N + 1][k + A[i]], mod - dp[now][j][k]);
				}
			}
		}
		rep(k, 0, N + 1) {
			rep(j, 0, N + 1) {
				ADD(ep[j + 1][k], ep[j][k]);
			}
		}
		rep(k, 0, N + 1) {
			rep(j, 0, N + 1) {
				ADD(dp[nex][j][k], ep[j][k]);
			}
		}
		// debug("yes");
