		// 		debug(i, j, k, dp[nex][j][k]);
		// 	}
		// }
		// debug("yesend");

		swap(now, nex);
	}
	ll res = 0;
	rep(i, 0, N + 1) {
		int dif = N - i;
		if(dif <= K) ADD(res, dp[now][N][i]);
	}
	cout << res << "\n";
