void solve() {
    ll K;
    cin >> s >> K;
    n = s.size();
    ll cnt = 0;
    vector<ll> v;
    for(ll i=0;i<n;i++){
        if(s[i] == '0'){
            v.pb(cnt);
            cnt = 0;
        }else{
            cnt ++;
        }
    }
    v.pb(cnt);
    cnt = 0;
    m = v.size();
    dp[0][0][0] = 1;
    ll maxi = 0;
    ll sum = 0;
    for(auto u : v){
        maxi = max(maxi, u);
        sum += u;
    }
    K = min(K, sum);
    for(ll i=1;i<=m;i++){
        for(ll j=0;j<=n;j++){
            // if use j ?
            for(ll k=0;k<=K;k++){
                for(ll l=0;l<=k;l++){
                    ll my_use = j;
                    ll norm = v[i-1];
                    ll nx, ny;
                    if (my_use >= norm) {
                        nx = k + my_use - norm;
                        ny = l;
                    } else {
                        nx = k;
                        ny = l + norm - my_use;
                    }
                    if (nx <= K && ny <= K && nx >= ny) dp[i][nx][ny] += dp[i-1][k][l];
                    dp[i][nx][ny] %= mod;
                }
            }
        }
    }
    ll ans = 0;
    for(ll i=0;i<=K;i++){
        ans += dp[m][i][i];
        ans %= mod;
    }
    p(ans);
    return;
}

