constexpr long long int MOD = 998244353;
static int sum;
std::vector<std::vector<std::vector<long long int>>> memo;
long long int pattern(const std::vector<int>& run_length, const int current_pos, const int current_use, const int k) {
	if (k < 0) return 0LL;
	if (run_length.size() <= current_pos) return current_use == sum ? 1LL : 0LL;
	if (current_use == sum) return 1LL;
	if (memo[current_pos][current_use][k] >= 0) return memo[current_pos][current_use][k];
	long long int result{ 0 };
	for (auto use = 0; current_use + use <= sum; ++use) {
		result += pattern(run_length, current_pos + 1, current_use + use, k - std::max(0, use - run_length[current_pos]));
	}
	return memo[current_pos][current_use][k] = result % MOD;
}
int main() {
	std::string str; int k; std::cin >> str >> k;
	std::vector<int> run_length{ 0 };
	for (const auto c: str) {
		if (c == '1') {
			run_length.back()++;
		}
		else {
			run_length.push_back(0);
		}
	}
	const auto all_one = std::count(str.begin(), str.end(), '1');
	sum = all_one;
	memo = std::vector<std::vector<std::vector<long long int>>>(run_length.size(), std::vector<std::vector<long long int>>(all_one + 1, std::vector<long long int>(std::min<int>(k, all_one) + 1, -1)));
	int prev{ 0 };
	for (auto i = 0; i < run_length.size(); ++i) {
		for (auto j = 0; j < prev; ++j) {
			std::fill(memo[i][j].begin(), memo[i][j].end(), 0);
		}
		prev += run_length[i];
	}
	std::cout << pattern(run_length, 0, 0, std::min<int>(k, all_one));
}

