template<typename T>
struct Polynomial : vector<T> {
  using vector<T>::vector;
  using P = Polynomial;
  P operator-() const {
    P res((*this).size());
    rep(i, (*this).size()) res[i] = -(*this)[i];
    return res;
  }
  P &operator+=(const P q) {
    rep(i, (*this).size()) if (i < q.size()) (*this)[i] += q[i];
    return *this;
  }
  P &operator-=(const P q) {
    rep(i, (*this).size()) if (i < q.size()) (*this)[i] -= q[i];
    return *this;
  }
  P &operator*=(const P q) { // dense
    drep(i, (*this).size()) {
      (*this)[i] *= q[0];
      rep2(j, 1, q.size()) if (j <= i) (*this)[i] += (*this)[i-j] * q[j];
    }
    return *this;
  }
  template<typename T2>
  P &operator*=(map<int, T2> q) { // sparse
    drep(i, (*this).size()) {
      (*this)[i] *= q[0];
      for (auto &[j, b] : q) if (j > 0 && j <= i) (*this)[i] += (*this)[i-j] * b;
    }
    return *this;
  }
  P &operator/=(const P q) { // dense
    rep(i, (*this).size()) {
      rep2(j, 1, q.size()) if (j <= i) (*this)[i] -= (*this)[i-j] * q[j];
      (*this)[i] /= q[0];
    }
    return *this;
  }
  template<typename T2>
  P &operator/=(map<int, T2> q) { // sparse
    rep(i, (*this).size()) {
      for (auto &[j, b] : q) if (j > 0 && j <= i) (*this)[i] -= (*this)[i-j] * b;
      (*this)[i] /= q[0];
    }
    return *this;
  }
  template<typename T2> P operator+(const T2 q) const { return P(*this) += q; }
  template<typename T2> P operator-(const T2 q) const { return P(*this) -= q; }
  template<typename T2> P operator*(const T2 q) const { return P(*this) *= q; }
  template<typename T2> P operator/(const T2 q) const { return P(*this) /= q; }
};
using Pol = Polynomial<mint>;
using Pol2 = Polynomial<Pol>;


int main() {
  string s; cin >> s;
  int K; cin >> K;

  V a(1);
  for (auto c : s) {
    if (c == '0') a.push_back(0);
    if (c == '1') a.back()++;
  }
  int n = a.size();
  auto b = a;
  rep(i, n-1) b[i+1] += b[i];
  int m = b[n-1];

  Pol2 dp(m+1, Pol(m+1));
  dp[0][0] = 1;

  rep(i, n) {
    Pol2 p(m+1, Pol(m+1));
    map<int, map<int, mint>> q1, q2, q3, q4;

    q1[0][0] = 1;
    q1[a[i]][0] += -1;

    q2[0][0] = 1;
    q2[1][0] = -1;

    q3[a[i]][0] = 1;

    q4[0][0] = 1;
    q4[1][1] = -1;

    p = dp*q1/q2 + dp*q3/q4;
    rep(j, b[i]) p[j] = Pol(m+1);
    swap(dp, p);
  }

  chmin(K, m);
  mint ans = 0;
  rep(k, K+1) ans += dp[m][k];
  cout << ans << "\n";
  return 0;
}

