namespace math {

template <typename T>
constexpr T pow(const T &n, ll k) {
    T ret = n.mul_id_ele();
    T cur = n;
    while (k) {
        if (k & 1) ret *= cur;
        cur *= cur;
        k /= 2;
    }
    return ret;
}

}

namespace math {

template <ll Mod>
struct Modint {

    constexpr Modint(ll x) noexcept : x((Mod + x % Mod) % Mod) { }

    constexpr Modint() noexcept : Modint(0) { }

    constexpr Modint<Mod> add_id_ele() const noexcept { 
        return Modint<Mod>(0); 
    }

    constexpr Modint<Mod> mul_id_ele() const noexcept {
        return Modint<Mod>(1); 
    }

    constexpr ll& value() noexcept { 
        return x; 
    }

    constexpr ll value() const noexcept {
        return x; 
    }

    constexpr Modint& operator +=(const Modint &oth) noexcept {
        x += oth.value();
        if (Mod <= x) x -= Mod;
        return *this;
    }

    constexpr Modint& operator -=(const Modint &oth) noexcept {
        x += Mod - oth.value();
        if (Mod <= x) x -= Mod;
        return *this;
    }

    constexpr Modint& operator *=(const Modint &oth) noexcept {
        x *= oth.value();
        x %= Mod;
        return *this;
    }

    constexpr Modint& operator /=(const Modint &oth) noexcept {
        x *= oth.inv().value();
        x %= Mod;
        return *this;
    }

    constexpr Modint operator +(const Modint &oth) const noexcept {
        return Modint(x) += oth;
    }

    constexpr Modint operator -(const Modint &oth) const noexcept {
        return Modint(x) -= oth;
    }

    constexpr Modint operator *(const Modint &oth) const noexcept {
        return Modint(x) *= oth;
    }

    constexpr Modint operator /(const Modint &oth) const noexcept {
        return Modint(x) /= oth;
    }

    constexpr Modint operator -() const noexcept {
        return Modint((x != 0) * (Mod - x)); 
    }

    template <typename T>
    constexpr typename std::enable_if<std::is_integral<T>::value, const Modint&>::type
    operator =(T t) noexcept {
        (*this) = Modint(std::forward<T>(t)); 
        return *this;
    }

    constexpr Modint inv() const noexcept {
        return ::math::pow(*this, Mod - 2);
    }

    constexpr ll mod() const noexcept {
        return Mod;
    }

private:
    ll x;
};

}

namespace math {

template <ll Mod>
class Factorial {
    using mint = Modint<Mod>;

    ssize_t maxv;
    vec<mint> factv, ifactv;

public:
    Factorial(ssize_t maxv) : maxv(maxv), factv(maxv + 1), ifactv(maxv + 1) {
        factv[0] = mint(1);
        for (ll i = 1; i <= maxv; i++) factv[i] = factv[i - 1] * i;
        ifactv.back() = factv.back().inv();
        for (ll i = maxv - 1; 0 <= i; i--) ifactv[i] = ifactv[i + 1] * (i + 1);
    }

    mint fact(ll n) const {
        return factv[n]; 
    }

    mint ifact(ll n) const {
        return ifactv[n];
    }

    mint perm(ll n, ll k) const {
        return factv[n] * ifactv[n - k];
    }

    mint comb(ll n, ll k) const {
        return perm(n, k) * ifactv[k];
    }
};

}

const ll mod = 998244353;
using mint = math::Modint<mod>;

const ssize_t SIZE = 310;
mdarray<mint, SIZE, SIZE, SIZE> dp;

int main() {
    std::string s;
    ll k;
    std::cin >> s >> k;
    ll n = s.size();
    vec<ll> nxt0(n + 1);
    nxt0[n - 1] = nxt0[n] = n;
    for (ll i = n - 2; 0 <= i; i--) {
        if (s[i + 1] == '0') nxt0[i] = i + 1;
        else nxt0[i] = nxt0[i + 1];
    }


    dp[0][0][0] = 1;
    for (ll i = 0; i < n; i++) {
        for (ll j = 0; j <= i; j++) {
            for (ll l = 0; l <= k; l++) {
                // put 0
                if (s[j] == '0') {
                    dp[i + 1][j + 1][l] += dp[i][j][l];
                } else {
                    ll idx = nxt0[j] + 1;
                    if (idx <= i + 1) dp[i + 1][idx][l] += dp[i][j][l];
                }

                // put 1
                if (s[j] == '0') {
                    if (l + 1 <= k) dp[i + 1][j][l + 1] += dp[i][j][l];
                } else {
                    dp[i + 1][j + 1][l] += dp[i][j][l];
                }
            }
        }
    }

    mint ans = 0;
    for (ll b = n; 1 <= b; b--) {
        for (ll i = 0; i <= k; i++) ans += dp[n][b][i];
        ll rest = n - b;
        if (s[n - 1 - rest] == '0') break;
    }
    std::cout << ans.value() << "\n";
    return 0;
}

