mint dp[333][1333], ep[333][1333];
mint r1[1333][1333], r2[1333][1333];
void solve() {
  ins(S);
  ini(K);

  vi v;
  rep(i, sz(S)) {
    if (S[i] == '0') v.pb(i);
  }
  trc(v);
  if (sz(v) == 0) die(1);

  dp[0][0] = 1;

  int off = 310;
  rep(i, sz(v)) {
    // 累積和
    //rep(i, off + 1) rep(j, off + 1) ep[i][j] = 0;
    int truth = (i ? v[i] - v[i - 1] : v[i]);
    rep(k, 1001) {
      rep(j, sz(S)) {
        r1[k][k + j] = dp[j][k];
        r2[k][k - j + off] = dp[j][k];
        if(k){
          r1[k][k + j] += r1[k - 1][k + j];
          r2[k][k - j + off] += r2[k - 1][k - j + off];
        }
      }
      rep(j, sz(S)) {
        // 0を置く場所 k 変化した回数
        int kpj = k + (j - truth);
        int kmj = k - (j - truth) + off;
        ep[j][k] = r1[k][kpj] + r2[k][kmj];
        if (j - truth >= 0) ep[j][k] -= dp[j - truth][k];
        if (kpj >= j) ep[j][k] -= r1[k-kpj][kpj];
      }

    }
    swap(dp, ep);
  }

  mint ans = 0;
  for (int i = v.back(); i < sz(S); i++)
    for (int j = 0; j <= min( ll(K) * 2 + i - v.back(), 1000LL); j++) ans += dp[i][j];

  if (K == 1) ans -= 1;
  out(ans);
}

