const int P = 998244353;

int &add(int &a, int b) {
  if ((a += b) >= P) {
    a -= P;
  }
  return a;
}

const int MAXN = 310;
int dp[2][MAXN][MAXN];

bool solve() {
  static char s[400];
  int k;
  if (scanf("%s%d", s, &k) != 2) return false;

  int n = strlen(s);
  reverse(s, s + n);

  vector<int> a;
  a.push_back(0);
  int ones = 0;
  for (int i = 0; i < n; ++i) {
    if (s[i] == '0') {
      a.push_back(0);
    } else {
      ones++;
      a.back()++;
    }
  }

  for (int x : a) {
    dbg("%d ", x);
  }
  dbg("\n");

  k = min(ones, k);
  int m = int(a.size());

  memset(dp, 0, sizeof(dp));

  auto get = [&](int i, int j, int p) -> int&{
    return dp[i&1][j][p];
  };

  for (int j = 0; j <= a[0]; ++j) {
    get(0, j, j) = 1;
  }

  for (int i = 1; i <= m; ++i) {
    for (int j = 0; j <= k; ++j) {
      for (int p = 0; p <= k; ++p) {
        auto &cur = get(i - 1, j, p);
        if (cur == 0) { continue; }
        dbg("dp[%d][%d][%d] = %d\n", i - 1, j, p, cur);
        if (i == m) { continue; }

        for (int q = 0; q <= ones; ++q) {
          int delta = a[i] - q;
          int newJ = j + (delta < 0 ? 0 : delta);
          int newP = p + delta;
          if (newJ > k || newP < 0 || newP > k) { continue; }
          auto &next = get(i, newJ, newP);
          add(next, cur);
        }

        cur = 0;
      }
    }
  }

  int ans = 0;
  for (int j = 0; j <= k; ++j) {
    add(ans, get(m - 1, j, 0));
  }
  printf("%d\n", ans);

  return true;
}

int main() {
  while (solve());
  return 0;
}

