void update_dp_help(int i) {
  for(int j = 0;j <= n;j++) {
    for(int k = n;k >= 0;k--) {
      help[i][j][k] = dp[i][j][k];
      if(j-1 >= 0 && k+1 <= n) {
        help[i][j][k] += help[i][j-1][k+1];
      }
      help[i][j][k] %= mod;
      if(j-1 >= 0) {
        dp[i][j][k] += dp[i][j-1][k];
      }
      dp[i][j][k] %= mod;
    }
  }
}

