int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    string s;
    li k;
//    cin >> s >> k;

    s = string(150, '0') + string(150, '1');
    k = 1e9;

    li cnt = 0;
    vector<li> cnts;
    for (char i : s) {
        if (i == '0') {
            cnts.push_back(cnt);
            cnt = 0;
        } else {
            cnt++;
        }
    }
    cnts.push_back(cnt);
    reverse(cnts.begin(), cnts.end());

    const li n = cnts.size();
    const li zeros = n - 1;
    k = min(k, zeros);
    vector<vector<vector<mint>>> dp(n + 1, vector<vector<mint>>(zeros + 1, vector<mint>(k + 1, 0)));
    // dp[fixed][carry][used k]
    dp[0][0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        const li cur_zeros = cnts[i - 1];
        for (int carry = 0; carry <= zeros; ++carry) {
            for (int to_k = 0; to_k <= k; ++to_k) {
                for (int new_zeros = 0; new_zeros <= zeros; ++new_zeros) {
                    const li consume = new_zeros - cur_zeros;
                    const li prev_carry = carry + consume;
                    if (prev_carry < 0 || prev_carry > zeros) {
                        continue;
                    }
                    const li prev_k = to_k - max(0LL, -consume);
                    if (prev_k < 0 || prev_k > k) {
                        continue;
                    }
                    dp[i][carry][to_k] += dp[i - 1][prev_carry][prev_k];
                }
//                cerr << i << " " << carry << " " << to_k << " " << dp[i][carry][to_k].x << endl;
            }
        }
    }

    mint ans = 0;
    for (int i = 0; i < k + 1; ++i) {
        ans += dp[n][0][i];
    }
    cout << ans.x << endl;
    return 0;
}

