void ADD(int &a, int b) {
    a += b; 
    if (a >= mod) a -= mod; 
}

int pref[maxn];

void solve() {
    cin >> s >> k; 
    s.pb('0'); 
    int n = s.size(); 
    vector<int> null; 
    for (int i = 0; i < n; ++i) if (s[i] == '0') null.pb(i); 
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + s[i] - '0'; 
    dp[0][0][0] = 1; 
    for (int i = 0; i < null.size(); ++i) {
        for (int len = 0; len <= n; ++len) {
            for (int cnt = 0; cnt <= n; ++cnt) {
                if (!dp[i][len][cnt]) continue;                 
                for (int add = 0; add <= pref[n] - len; ++add) {
                    if (add + len < pref[null[i] + 1]) continue; 
                    int new_cnt = cnt + max(0, add - pref[null[i] + 1] + pref[(i == 0 ? 0 : null[i - 1])]); 
                    if (new_cnt >= maxn) continue; 
                    ADD(dp[i + 1][len + add][new_cnt], dp[i][len][cnt]); 
                }
            }            
        }
    }
    int ans = 0; 
    for (int cnt = 0; cnt <= min(n, k); ++cnt) {
        ADD(ans, dp[null.size()][pref[n]][cnt]); 
    }
    cout << ans; 
}                                

