constexpr int mod = 998244353;
constexpr int M = 350;
long long U[M][M][2*M], D[M][M][2*M], P[M][M][2*M];

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    string S; cin >> S;
    int K; cin >> K;
    K = min(K, M-10);
    vector<int> T;
    int cnt = 0, A = 0;
    for (auto &x: S) {
        if (x == '0') {
            T.emplace_back(cnt);
            cnt = 0;
        } else {
            cnt++, A++;
        }
    }
    int B = A + 10;
    T.emplace_back(cnt);
    int N = T.size(), C = 0;
    P[0][0][0] = 1;
    for (int i = 0; i < N; i++) {
        C += T[i];
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                P[i][j][k] %= mod;
                int nj = j + T[i], nk = k;
                if (C > nj) {
                    int d = C - nj;
                    nj += d, nk += d;
                }
                if (nj <= A) {
                    U[i+1][nj][nk] += P[i][j][k];
                    U[i+1][nj][nk] %= mod;
                    U[i+1][A+1][A+1-nj+nk] += mod - P[i][j][k];
                    U[i+1][A+1][A+1-nj+nk] %= mod;
                }
            }
        }
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                U[i+1][j+1][k+1] += U[i+1][j][k];
                U[i+1][j+1][k+1] %= mod;
            }
        }
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                int nj = j, nk = k + T[i];
                if (nj < C) {
                    int d = C - nj;
                    nj += d, nk -= d;
                }
                if (nk > k) {
                    D[i+1][nj][nk] += P[i][j][k];
                    D[i+1][nj][nk] %= mod;
                    D[i+1][j+T[i]][k] += mod - P[i][j][k];
                    D[i+1][j+T[i]][k] %= mod;
                }
            }
        }
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                if (k) {
                    D[i+1][j+1][k-1] += D[i+1][j][k];
                    D[i+1][j+1][k-1] %= mod;
                }
            }
        }
        for (int j = 0; j <= B; j++) {
            for (int k = 0; k <= B*2; k++) {
                P[i+1][j][k] = (U[i+1][j][k] + D[i+1][j][k]) % mod;
            }
        }        
    }
    long long Ans = 0;
    for (int i = 0; i <= 2*K; i++) {
        Ans += P[N][A][i] % mod;
    }
    cout << (Ans % mod + mod) % mod << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

template <int mod = (int)(998244353)>
struct ModInt {
  int x;
  ModInt() : x(0) {}
  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}
  ModInt &operator+=(const ModInt &p) {
    if ((x += p.x) >= mod) x -= mod;
    return *this;
  }
  ModInt &operator-=(const ModInt &p) {
    if ((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }
  ModInt &operator*=(const ModInt &p) {
    x = (int)(1LL * x * p.x % mod);
    return *this;
  }
  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }
  ModInt operator-() const { return ModInt(-x); }
  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }
  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }
  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }
  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }
  bool operator==(const ModInt &p) const { return x == p.x; }
  bool operator!=(const ModInt &p) const { return x != p.x; }
  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while (b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }
  ModInt pow(int64_t n) const {
    ModInt res(1), mul(x);
    while (n) {
      if (n & 1) res *= mul;
      mul *= mul;
      n >>= 1;
    }
    return res;
  }
  friend ostream &operator<<(ostream &os, const ModInt &p) { return os << p.x; }
  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt<mod>(t);
    return (is);
  }
  static int get_mod() { return mod; }
};

struct Combination {
  vector<ModInt<>> _fact, _rfact, _inv;
  Combination(long long nsize = 5000000)
      : _fact(nsize + 1), _rfact(nsize + 1), _inv(nsize + 1) {
    _fact[0] = _rfact[nsize] = _inv[0] = 1;
    for (int i = 1; i <= nsize; i++) _fact[i] = _fact[i - 1] * i;
    _rfact[nsize] /= _fact[nsize];
    for (int i = nsize - 1; i >= 0; i--) _rfact[i] = _rfact[i + 1] * (i + 1);
    for (int i = 1; i <= nsize; i++) _inv[i] = _rfact[i] * _fact[i - 1];
  }
  inline ModInt<> fact(int k) const { return _fact[k]; }

  inline ModInt<> rfact(int k) const { return _rfact[k]; }

  inline ModInt<> inv(int k) const { return _inv[k]; }

  ModInt<> P(int n, int r) const {
    if (r < 0 || n < r) return 0;
    return fact(n) * rfact(n - r);
  }

  ModInt<> C(int p, int q) const {
    if (q < 0 || p < q) return 0;
    return fact(p) * rfact(q) * rfact(p - q);
  }
  // n types,choose r
  ModInt<> H(int n, int r) const {
    if (n < 0 || r < 0) return (0);
    return r == 0 ? 1 : C(n + r - 1, r);
  }
};

