    Int mi = INF;
    Int sum = 0;
    for (Int i = 0; i < (Int)a.size(); i++) {
        sum += a[i];
        mi = min(mi, a[i]);
    }
    if (k >= sum - mi + cnt) {
        Int x = COM(z + sum - 1, sum);
        Int res = x;
        for (Int i = 0; i < (Int)cnt; i++) {
            res += x * z % mod;
            res %= mod;
        }
        print(res);
    } else {
        assert(false);
    }
    return 0;
}

