void smain() {
    string s;
    int k;
    cin >> s >> k;
    vi a;
    int cnt = 0;
    for (auto c : s) {
        if (c == '0') {
            a.push_back(cnt);
            cnt = 0;
        } else {
            cnt++;
        }
    }
    a.push_back(cnt);
    reverse(ALL(a));
    int n = a.size();
    inmin(k, N - 1);
    dp[0][0][k] = 1;
    for (int i = 0; i < n; ++i) {
        /* dec */;
        for (int t = 0; t < N; ++t) {
            for (int r = 0; r < N; ++r) {
                for (int x = 1; x <= min(a[i], r); ++x) {
                    insum(dp[i + 1][t + x][r - x], dp[i][t][r]);
                }
            }
        }
        /* inc */;
        for (int r = 0; r < N; ++r) {
            int sum = 0;
            for (int t = N - 1; t >= 0; --t) {
                insum(dp[i + 1][t][r], sum);
                insum(sum, dp[i][t][r]);
            }
        }
        /* same */;
        for (int t = 0; t < N; ++t) {
            for (int r = 0; r < N; ++r) {
                insum(dp[i + 1][t][r], dp[i][t][r]);
