//                    cerr << "dp[" << i << "][" << t << "][" << r << "] = " << dp[i][t][r] << endl;
//                }
            }
        }
    }
    int ans = 0;
    for (int r = 0; r < N; ++r) {
        insum(ans, dp[n][0][r]);
    }
    cout << ans;
}

