int rob(int pos, int dod, int kara) {
	if (kara < 0) return 0;
	if (pos == 0) {
		if (kara < dod) return 0;
		return 1;
	}
	if (memo.find({pos,{dod,kara}}) != memo.end()) {
		return memo[{pos,{dod,kara}}];
	}
	int ans = 0;
	FOR(i,0,w[pos]+dod+1) {
		ans = ans + rob(pos-1,dod+w[pos]-i, kara-abs(w[pos]-i));
		if (ans >= mod) ans -= mod;
	}
	memo[{pos,{dod,kara}}] = ans;
	return ans;
}	

