vector<vector<vl>> dp;
vi c;

lint mod = 998244353;
lint mypow(lint a, lint n){
    lint res = 1;
    lint base = a;
    while(n > 0){
        if (n%2) res = res*base%mod;
        base = base*base%mod;
        n = n/2;
    }
    return res;
}

lint rev(lint a){
    return mypow(a, mod-2);
}

vl la, rela;

lint comb(lint n, lint m, vl &la, vl &rela){
    return (la[n] * rela[m] % mod) * rela[n-m] % mod;
}

lint res(int len, int pos, int k){//  k
    assert(k>=0);
    if (dp[len][pos][k] != -1) return dp[len][pos][k];
    if (len == 1) {
        if (pos == 1 && k == 0) return dp[len][pos][k] = 1;
        else return dp[len][pos][k] = 0;
    }
    lint ans = 0;
    // not sub
    if (pos > 1) ans += res(len-1, pos -1, k);

    //sub
    if (k > 0)
    for (int cnt = 1; cnt <= c[len-1]; cnt++){
        if (cnt > k) break;
        for (int opos = pos; opos<=len-1; ++opos)
        {
            ans += res(len-1, opos, k - cnt) * comb(opos- pos +cnt-1, cnt-1, la, rela);
            ans = ans % mod;
        }
    }
    return dp[len][pos][k] = ans%mod;
}

