using namespace std;

int GCD(int x,int y)
{
	if(x == 0)
	{
		return y;
	}

	if(y == 0)
	{
		return x;
	}

	if(x > y)
	{
		return GCD(x%y,y);
	}

	return GCD(x,y%x);
}

int LCM(int x,int y)
{
	int gcd = GCD(x,y);
	return x*y/gcd;
}

