int main(){
    string str;
    cin >> str;
    int N = str.size();
    vector<int> S(N);
    for(int i=0; i<N; i++) S[i] = str[i] - '0';
    int K;
    cin >> K;
    int One = accumulate(S.begin(), S.end(), 0);
    int Zero = N-One;
    K = min(K, One);

    // 0 で区切った時の各エリアの1の個数
    vector<int> one;
    int len = 0;
    for(int i=0; i<N; i++){
        if(S[i]){
            len++;
        }else{
            one.push_back(len);
            len = 0;
        }
    }
    one.push_back(len);
    // 各エリアより後に1がいくつあるか
    vector<int> aft(Zero+1);
    for(int i=Zero-1; i>=0; i--) aft[i] = aft[i+1] + one[i+1];

    // エリアiまで見て、操作をj回使って、1をk回使った
    static int64_t dp[310][310][310];
    dp[0][0][0] = 1;
    for(int i=0; i<=Zero; i++){
        // 元々あった one[i] 個の1を全部は使わないパターン
        // 0～(one[i]-1) 個使って合計k個になるような遷移元を累積和で処理
        for(int j=0; j<=K; j++){
            int64_t s = 0;
            for(int k=0; k<=One; k++){
                add(s, dp[i][j][k]);
                if(k >= one[i]) add(s, MOD - dp[i][j][k-one[i]]);
                // 残っている1の個数が aft[i] 個以下なら遷移
                if(One-k <= aft[i]) add(dp[i+1][j][k], s);
            }
        }
        // 元々あった one[i] 個の1を全部使って、さらに移動してきた1を0個以上使うパターン
        for(int j=0; j<=K; j++) for(int k=0; k<=One; k++){
            // 移動してきた1を1個使って同じiに遷移
            add(dp[i][j+1][k+1], dp[i][j][k]);
            // one[i] 個の1を使い、残っている1の個数が aft[i] 個以下ならi+1に遷移
            if(One-(k+one[i]) <= aft[i]) add(dp[i+1][j][k+one[i]], dp[i][j][k]);

        }
    }

    int64_t ans = 0;
    for(int j=0; j<=K; j++) add(ans, dp[Zero+1][j][One]);
    cout << ans << endl;
    return 0;
}

