const int N = 301;
const int MOD = 998244353;

int n, k;
string s;
vector<int> v, suf;
int cache[N][N][N];

int dp(int idx, int cur, int tot)
{
	if(tot > k)
		return 0;
	if(idx >= v.size())
		return (cur == 0);
	int &ans = cache[idx][cur][tot];
	if(ans != -1)
		return ans;
	ans = 0;
	for(int len = max(0LL, v[idx] - cur); len <= v[idx] + k - tot; len++)
		ans += dp(idx + 1, cur + len - v[idx], tot + max(0LL, len - v[idx]));
	ans %= MOD;
	return ans; 
}

