#define inCD(v, l, r) ((l) <  (v) && (v) <  (r))
#define inCI(v, l, r) ((l) <  (v) && (v) <= (r))

int main() {
	IN(string, str);
	IN(int, K);
	vector<int> v = { 0 };
	int s = 0;
	RF(c, str) {
		if(c == '1') { v.BA++; s++; } else { v.PB(0); }
	}
	int n = SI(v);

	MI zero = 0;
	auto dp_ = MV<MI>(0, n + 1, s + 1, 2 * s + 1);
	auto dp  = [&](int i, int j, int k) -> auto & {
		zero = 0;
		return (inII(j, 0, s) && inII(k, 0, 2 * s) ? dp_[i][j][k] : zero);
	};
	dp(0, 0, 0) += 1;
	dp(0, 1, 1) -= 1;
	incII(i, 0, n) {
		incII(k, 0, 2 * s) {
		incII(j, 0, s) {
			auto & x = dp(i, j, k);
			dp(i, j - 1, k + 1) += x;
			dp(i, j + 1, k + 1) += x;
			if(inCD(j, 0, s)) { dp(i, j, k + 2) -= x; }
			if(i == n) { continue; }

			dp(i + 1, j, k    ) += x;
			dp(i + 1, j, k + 2) -= x;
			if(j > v[i]) {
				dp(i + 1, j - v[i] - 1, k + v[i] + 1) -= x;
				dp(i + 1, j - v[i]    , k + v[i] + 2) += x;
			}
		}
		}
	}
	MI ans = 0;
	incII(k, 0, 2 * s) {
		if(k <= 2 * K) { ans += dp(n, 0, k); }
	}
	OUT(ans);
}

