        for (int k = 0; k <= K; k++) {
            for (int t = 0; t <= K; t++) {
                dp[i - 1][k][t] += tmp0[k][t] + tmp1[k][t];
                dp[i - 1][k][t] %= MOD;
            }
        }
    }
    Int ans = 0;
    for (int k = 0; k <= K; k++) {
        ans += dp[0][k][0];
    }
    cout << ans % MOD << '\n';
    return 0;
}

