    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    string s;
    cin >> s;
    int ns = s.size();
    lint k;
    cin >> k;
    vector<int> ones;
    int one = 0;
    for (int i = 0; i < ns; ++i) {
        if (s[i] == '0') {
            ones.push_back(one);
            one = 0;
        } else {
