    vector<vector<vector<mint>>> dp(m + 1, vector<vector<mint>>(ns + 1, vector<mint>(ns + 1, 0)));
    dp[0][0][0] = 1;
    for (int i = 1; i <= m - 1; ++i) {
        vector<vector<mint>> temp(400, vector<mint>(400, 0));
        for (int j = 0; j <= ns; ++j) {
            for (int l = 0; l <= ns; ++l) {
                temp[j][l]  = dp[i - 1][j][l];
                dp[i][j][l] = dp[i - 1][j][l];
            }
        }
        for (int j = 0; j <= ns; ++j) {
            for (int l = 0; l <= ns; ++l) {
                for (int x = 1; x <= ones[i - 1]; ++x) { // total  < 300
                    if (k - x < 0 || l - x < 0)
                        break;
                    temp[j][l - x] += temp[j][l];
                }
            }
        }
        for (int j = 0; j <= ns; ++j) {
            for (int l = 0; l <= ns; ++l) {
                temp[j][l] -= dp[i - 1][j][l];
            }
        }

        for (int j = 1; j <= ns; ++j) {
            for (int l = 1; l <= ns; ++l) {
                if (j + l >= ns)
                    break;
                dp[i][j + l - 1][l] += dp[i][j + l - 2][l - 1];
            }
        }
        for (int j = 2; j <= ns; ++j) {
            for (int l = 1; l <= ns; ++l) {
                if (j + l >= ns)
                    break;
                dp[i][l][j + l - 1] += dp[i][l - 1][j + l - 2];
            }
        }

        for (int j = 0; j <= ns; ++j) {
            for (int l = 0; l <= ns; ++l) {
                dp[i][j][l] += temp[j][l];
            }
        }
    }
    int id   = min(k, lint(ns));
    mint ret = 0;
    for (int i = 0; i <= id; ++i) {
        for (int j = 0; j <= ones[m - 1]; ++j) {
            ret += dp[m - 1][i][j];
        }
    }
    cout << ret << endl;
    return 0;
}

