    }

    long long res = 0;
    //res += dp(curNum, i, j+1, K-1);
    res += dp(curNum+1, i, j, K); // not use curNum

    if(A[j] == curNum && (j == 0 || A[j] != A[j-1])){
        // use curNum, decide not to change
        res += dp(curNum, i+1, j+1, K);
    }else{
        // use curNum, decide to change
