                    dp[i][sp][sum] += dp[i - 1][sp - (a[i] - x)][sum - x];
                    if(dp[i][sp][sum] >= MOD)
                        dp[i][sp][sum] -= MOD;
                }
                for(int x = 0; (a[i] + x) <= sp; x++)
                {
                    dp[i][sp][sum] += dp[i - 1][sp - (a[i] + x)][sum];
                    if(dp[i][sp][sum] >= MOD)
                        dp[i][sp][sum] -= MOD;
                }
            }
    int ans = 0;
    for(int i = 0; i <= k; i++)
    {
        ans += dp[n][spa[n]][i];
        if(ans >= MOD)
            ans -= MOD;
    }
    cout << ans << "\n";
    return 0;
}

