template <class T> class MultiArray3
{
    public:
        T** _a2;
        T* _a;
        int _d1;
        int _d2;
        int _d3;
        MultiArray3(int d1, int d2, int d3, bool clr = true)
        {
            _d1 = d1; _d2 = d2; _d3 = d3;
            _a = new T[_d1 * _d2 * _d3];
            _a2 = new T*[_d1 * d2];
            for(int i = 0; i < d1 * d2; i++ ) _a2[i] = _a + (i * _d3);
            if(clr) memzero();
        }

        void memzero()
        {
            memset(_a, 0, _d1 * _d2 * _d3 * sizeof(T));
        }

        ~MultiArray3()
        {
            delete _a;
            delete _a2;
        }

        T** operator[](int i)
        {
            return _a2 + (i * _d2);
        }
};

