    int total1 = onecount[0];
    for(int j = total1; j <= n1; j++)
    {
        dp[0][j][onecount[0]] = 1;
    }

    for(int i = 1; i < n0; i++ )
    {
        total1 += onecount[i];
        for( int u = 0; u <= total1; u++ )
        {
            // i番目にonecount[i]以下しか残さないケース
            for( int j = total1; j <= n1; j++ )
            {
                for(int m = 0; m <= onecount[i] && j - m >= 0 && u - m >= 0; m++)
                {
                    // ここはトータルでn1回しか通らないはず
                    dp[i][j][u] = modadd(dp[i][j][u], dp[i-1][j-m][u-m]);
                }
