    rep(i, n) if(s[i] == '1') one++;
    one = min(one + 1, k + 1);
    mtl dp(one, vl(one)), tmp(one, vl(one));
    dp[0][0] = 1;
    vi nx(n);
    nx[n - 1] = n - 1;
    per(i, n - 1) nx[i] = (s[i] == '0' ? i : nx[i + 1]);
    rep(x, n){
        if(s[x] == '0'){
            rep(i, one - 1){
                rep(j, one){
                    dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD;
                }
            }
            rep(i, one){
                rep(j, one){
                    dp[i][j] = (dp[i][j] + tmp[i][j]) % MOD;
                    tmp[i][j] = 0;
                }
            }
        }else{
            k = nx[x] - x;
            rep(i, one){
                rep(j, one){
                    if(i < k || one <= j + k) continue;
                    tmp[i - k][j + k] = (tmp[i - k][j + k] + dp[i][j]) % MOD;
                }
            }
        }
    }
    ll ans = 0;
    rep(i, one){
        ans = (ans + dp[0][i]) % MOD;
    }
    cout << ans << endl;
    return 0;
}

