ModInt<> solve() {
  ModInt<> res = 0;
  if (cnt[0] == len) return 1;
  dp.assign(n + 1, vector(k + 1, vector<ModInt<>>(k + 1, 0)));
  sum1.assign(n + 1, vector(k + 1, vector<ModInt<>>(k + 1, 0)));
  sum2.assign(n + 1, vector(k + 1, vector<ModInt<>>(k + 1, 0)));
  dp[0][0][0] = sum1[0][0][0] = sum2[0][0][0] = 1;
  for (int i = 0; i < n; ++i) {
    for (int j = 1; j <= k; ++j)
      for (int l = 0; l <= j; ++l) sum1[i][j][l] += sum1[i][j - 1][l];
    for (int j = 0; j <= k; ++j)
      for (int l = 1; l <= j; ++l) sum2[i][j][l] += sum2[i][j][l - 1];
    for (int j = 0; j <= k; ++j)
      for (int l = 0; l <= k; ++l) {
        int now = cnt[i];
        if (i != n - 1) dp[i + 1][j][l] += sum1[i][j][l];
        if (i != 0) {
          dp[i + 1][j][l] += sum2[i][j][l];
          if (l > now) dp[i + 1][j][l] -= sum2[i][j][l - now - 1];
        }
        if (i != 0 && i != n - 1) dp[i + 1][j][l] -= dp[i][j][l];
        if (l > j) dp[i + 1][j][l] = 0;
        sum1[i + 1][j][l] = sum2[i + 1][j][l] = dp[i + 1][j][l];
      }
  }
  for (int i = 0; i <= k; ++i) res += dp[n][i][i];
  return res;
}

