inline int add(int x, int y) {x += y; return x >= MOD ? x - MOD : x;}
inline int sub(int x, int y) {x -= y; return x < 0 ? x + MOD : x;}
inline int mul(int x, int y) {return (int)(1LL * x * y % MOD);}

int pow_mod(int b, int p) {
	int ret = 1;
	for(int i=p;i;i>>=1,b=mul(b,b))
		if( i & 1 ) ret = mul(ret, b);
	return ret;
}

int a[MAXN + 5], s, m, K;
int dp[2][MAXN + 5][MAXN + 5];
int solve() {
	int t = 0; dp[0][0][0] = 1;
	for(int i=m;i>=1;i--) {
		for(int k=0;k<=t;k++)
			for(int j=0;j<=t;j++)
				dp[1][k][j] = dp[0][k][j], dp[0][k][j] = 0;

		for(int k=0;k<=t;k++) {
			dp[0][k][t] = dp[1][k][t];
			for(int j=t-1;j>=0;j--)
				dp[0][k][j] = add(dp[0][k][j + 1], dp[1][k][j]);
		}

		for(int k=0;k<=t;k++)
			for(int j=0;j<=t;j++)
				for(int l=1;l<=a[i];l++)
					dp[0][k+l][j+l] = add(dp[0][k+l][j+l], dp[1][k][j]);

		t += a[i];
	}

	int lim = min(K, s), ans = 0;
	for(int i=0;i<=lim;i++)
		ans = add(ans, dp[0][i][0]);
	return ans;
}

