            }
            else
            {
                ons.push_back(0);
            }
        }

        vector dp(K+2,vector<mint>(n+1));
        dp[0][0]=1;
        for(int x: ons)
        {
            vector tmp(x+1, vector(K+2, vector<mint>(n+1)));
            tmp[0]=dp;

            for(int i=0; i<x; i++)
            {
                for(int j=0; j<=K; j++)
                {
                    mint acc;
                    for(int h=n; h>0; h--)
                    {
                        acc+=tmp[i][j][h];
                        tmp[i+1][j+1][h]+=acc;
                    }
                }
            }

            for(int i=0; i<=K; i++) dp[i].insert(dp[i].begin(),0);
            for(int i=1; i<=x; i++)
            {
                for(int j=0; j<=K; j++)
                {
                    for(int h=0; h<=n; h++)
                    {
                        dp[j][h]+=tmp[i][j][h];
                    }
                }
            }
        }

        mint ans;
        for(int i=0; i<=K; i++)
        {
            for(int j=0; j<=n; j++)
            {
                ans+=dp[i][j];
            }
        }
        cout << ans << "\n";
    }
};
