using VM  = vector<ModInt>;
using VVM = vector<vector<ModInt>>;
int main() {
    /* write here */
    string s;
    int k;
    cin >> s >> k;
    int n = s.size();
    chmin(k, n);

    vector<int> c(1, 0);
    for (int i : range(n)) {
        if (s[i] == '1') {
            c.back()++;
        }
        else {
            c.push_back(0);
        }
    }
    cerr << join(c, ",") << endl;


    // dp[i][m][l] :=
    // i-1番目の'1'のブロックまで見て、m個左に流さなくてはいけない（自身を含む）かつ、既にk個移動させた場合の数

    VVM dp(n + 1, VM(k + 1));
    dp[0][0] = 1;
    for (int i : range(c.size())) {
        VVM nxt1(n + 1, VM(k + 1));
        // 追加する場合
        for (int m : range(n)) {
            for (int l : range(k)) {
                nxt1[m + 1][l + 1] += nxt1[m][l] + dp[m][l];
            }
        }

        VVM nxt2(n + 1, VM(k + 1));
        // 減らす場合
        for (int m : !range(1, n + 1)) {
            for (int l : !range(1, k + 1)) {
                auto ad = nxt2[m][l] + dp[m][l];
                if (m + c[i] <= n) {
                    ad -= dp[m + c[i]][l];
                }
                nxt2[m - 1][l] += ad;
            }
        }
        for (int m : range(n + 1)) {
            for (int l : range(k + 1)) {
                dp[m][l] += nxt1[m][l] + nxt2[m][l];
            }
        }
    }
    ModInt ret = 0;
    for (int i : range(k + 1)) {
        ret += dp[0][i];
    }
    cout << *ret << endl;

    return 0;
}

#include <iostream>
