using namespace std;
typedef long long ll;
const ll MOD = 998244353;

string S;
int K;
vector<int> v;

ll dp[305][305][605];

ll buf0[605][605];
ll buf1[605][605];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> S >> K;
    int cnt = 0;
    int sum = 0;
    for(char c : S){
        if(c == '0'){
            v.push_back(cnt);
            cnt = 0;
        }else{
            cnt++;
            sum++;
        }
    }
    if(cnt != 0) v.push_back(cnt);
    K = min(K, (int)S.size());
    dp[0][0][0] = 1;
    int tmp = 0;
    int sz = v.size();
    for(int i = 0; i < v.size(); i++){
        for(int j = 0; j <= 300; j++){
            for(int k = 0; k <= 600; k++){
                buf0[j][k] = 0;
                buf1[j][k] = 0;
            }
        }
        for(int j = 0; j <= tmp+K; j++){
            for(int k = 0; k <= 2*K; k++){
                if(dp[i][j][k] == 0) continue;
                // [0, v[i]]
                int l = max(tmp+v[i], j);
                buf0[l][k+v[i]+j-l] += dp[i][j][k];
                buf0[j+v[i]+1][k-1] -= dp[i][j][k];
                // [v[i]+1, sum-tmp]
                buf1[j+v[i]+1][k+1] += dp[i][j][k];
                buf1[j+v[i]+sum-tmp+1][k+sum-tmp+1] -= dp[i][j][k];
                // if((i == 2)) {
                //     cout << j << ' ' << k << endl;
                //     cout << j << ',' << k+v[i] << ' ' << j+v[i]+1 << ',' << k-1 << ' ' << dp[i][j][k] << endl;
                //     cout << j+v[i]+1 << ',' << k+1 << ' ' << k+sum-tmp+1 << ',' << j+v[i]+sum-tmp+1 << ' ' << dp[i][j][k] << endl;
                // }
            }
        }
        for(int j = 1; j <= sum; j++){
            for(int k = 1; k <= 2*K; k++){
                buf1[j][k] += buf1[j-1][k-1];
                buf1[j][k] %= MOD;
            }
        }
        for(int j = 1; j <= sum+2*K; j++){
            for(int k = 1; k <= j; k++){
                int l = j-k;
                buf0[k][l] += buf0[k-1][l+1];
                buf0[k][l] %= MOD;
            }
        }

        for(int j = 0; j <= 300; j++){
            for(int k = 0; k <= 600; k++){
                dp[i+1][j][k] = buf0[j][k]+buf1[j][k];
                dp[i+1][j][k] %= MOD;
            }
        }
        tmp += v[i];
    }
    ll ans = 0;

