vector<int> curr;

mint ways(int len,int steps,int extra){
	assert(steps >= 0 && len>=0 && extra >=0);

	if (vis[len][steps][extra]){
		return dp[len][steps][extra];
	}
	if (len == 0){
		if (extra != 0) return 0;
		return 1;
	}
	vis[len][steps][extra] = true;
	mint& ans = dp[len][steps][extra];
	ans = get_sum(len-1,steps,extra);
