                for(int p=max(j,sum[i+1]);p<=min(sum[i+1]+k,o);p++){
                    int cnt = y;
                    int dif = p - j;
                    dif -= sum[i+1] - sum[i];
                    dif = max(0,dif);
                    cnt += dif;
                    if(cnt <= k){
                        dp[i+1][p][cnt] += dp[i][j][y];
                    }
                }
            }
        }
    }
    mint ans = 0;
    for(int i=sum[z];i<=o;i++){
        for(int y=0;y<=min(o,k);y++){
            ans += dp[z][i][y];
        }
    }
    cout << ans << endl;


}

