string S;
vector<int> vec;

int N, K;
int A[1 << 18], B[1 << 18];

// (pos, 合計, 差分)
long long mod = 998244353;
long long dp[309][309][309];
long long ru1[309][309][309];
long long ru2[309][309][309];

void init(int pos) {
	for (int i = 0; i <= 300; i++) {
		for (int j = 0; j <= 300; j++) {
			if (i >= 1) ru1[pos][i][j] = ru1[pos][i - 1][j];
			ru1[pos][i][j] += dp[pos][i][j];
			if (ru1[pos][i][j] >= mod) ru1[pos][i][j] -= mod;
			if (i >= 1 && j >= 1) ru2[pos][i][j] = ru2[pos][i - 1][j - 1];
			ru2[pos][i][j] += dp[pos][i][j];
			if (ru2[pos][i][j] >= mod) ru2[pos][i][j] -= mod;
		}
	}
}

void solve(int pos, int sum, int diff) {
	// 自分の方が少ない場合
	long long b1 = ru1[pos - 1][sum][diff];
	long long b2 = 0; if (sum - A[pos] >= 0) b2 = ru1[pos - 1][sum - A[pos]][diff];
	dp[pos][sum][diff] += (b1 - b2 + mod) % mod;

	// 自分の方が多い場合
	if (sum - A[pos] >= 0) {
		long long c1 = ru2[pos - 1][sum - A[pos]][diff];
		dp[pos][sum][diff] += c1;
	}
	dp[pos][sum][diff] %= mod;
}

int main() {
	// 入力
	cin >> S >> K;
	for (int i = 0; i < S.size(); i++) {
		if (S[i] == '0') vec.push_back(i);
	}
	if (vec.size() == 0) {
		cout << "1" << endl;
		return 0;
	}

	// 前準備
	A[1] = vec[0];
	for (int i = 0; i < (int)vec.size() - 1; i++) {
		A[i + 2] = vec[i + 1] - vec[i] - 1;
	}
	A[vec.size() + 1] = S.size() - 1 - vec[vec.size() - 1];
	N = vec.size() + 1;

	// 累積和
	for (int i = 1; i <= N; i++) B[i] = B[i - 1] + A[i];

	// DP の計算
	dp[0][0][0] = 1; init(0);
	for (int i = 1; i <= N; i++) {
		for (int j = B[i]; j <= B[N]; j++) {
			for (int k = 0; k <= B[N]; k++) {
				solve(i, j, k);
			}
		}
		init(i);
	}

	// 答え
	long long Answer = 0;
	for (int i = 0; i <= min(B[N], K); i++) {
		Answer += dp[N][B[N]][i];
		Answer %= mod;
	}
	cout << Answer << endl;
	return 0;
}

