ll power(ll a, ll b){
	a %= mod;
	if (b == 0) return 1;
	if (b == 1) return a;
	ll half = power(a, b/2);
	half *= half;
	half %= mod;
	if (b % 2 == 1){
		half *= a;
		half %= mod;
	}
	return half;
}

ll f[1005];
ll invf[1005];
void init(){
	f[0] = 1;
	for (ll i = 1; i <= 1004; i++){
		f[i] = f[i - 1]*i;
		f[i] %= mod;
	}
	for (ll i = 0; i <= 1004; i++){
		invf[i] = power(f[i], mod - 2);
	}
}

ll choose(ll n, ll k){
	if (n < k) return 0;
	ll ans = f[n]*invf[k];
	ans %= mod;
	ans *= invf[n - k];
	return ans%mod;
}

