#define int long long

std::string str;
int n, k;

const int ms = 303;
const int MOD = 998244353;

std::vector<int> groups;
int memo[ms][ms][ms][2];

int dp(int on, int ones, int cost, int t) {
	if(cost < 0) return 0;
	if(n == on) {
		return ones == 0 ? 1 : 0;
	}
	int &ans = memo[on][ones][cost][t];
	if(ans != -1) return ans;
	ans = 0;
	if(t == 0) {
		// can use some from future here
		ans = dp(on, ones, cost, 1);
		// or use some from here to back
		for(int i = 1; i <= groups[on] && i <= ones; i++) {
			ans = (ans + dp(on+1, ones - i, cost, 0)) % MOD;
		}
	} else {
		ans = (dp(on, ones+1, cost-1, 1) + dp(on+1, ones, cost, 0)) % MOD;
	}
	//std::cout << "on (" << on << ", " << ones << ", " << cost << ", " << t << ") got " << ans << '\n';
	return ans;
}

main() {
	std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);
	std::cin >> str >> k;
	while((int) str.size() > 0 && str[0] == '1') {
		str = str.substr(1, (int) str.size() - 1);
	}
	//std::cout << "string reduced to " << str << " of size " << str.size() << '\n';
	n = (int) str.size();
	k = std::min(k, ms-1);
	for(int l = 0, r = 0; l < n; l = r) {
		assert(str[l] == '0');
		l++;
		r++;
		if(r == n || str[r] == '0') {
			groups.push_back(0);
			continue;
		}
		while(r < n && str[l] == str[r]) r++;
		assert(l < r);
		groups.push_back(r - l);
	}
	n = (int) groups.size();
	memset(memo, -1, sizeof memo);
	int ans = 0;
	for(int i = 0; i <= k; i++) {
		ans = (ans + dp(0, i, k-i, 0)) % MOD;
	}
	std::cout << ans << '\n';
}

