    string s; ll k; cin >> s >> k;

    vector<ll> a = {0};
    FOREACH(c, s) {
        if (c == '0') {
            a.push_back(0);
        } else {
            a.back()++;
        }
    }

    ll b = accumulate(ALLOF(a), 0LL);
    chmin(k, b);
    ll n = a.size();

    reverse(ALLOF(a));

    constexpr ll pdiv = 119<<23|1;

    // dp[i][j][l] := i個見て保留j個、累積保留l個
    ll m = min(k, b);
    vector dp(m+1, vector(m+1, 0LL));
    dp[0][0] = 1;
    REP(i, n) {
        vector dq = dp;
        REP(j, m+1) {
            RANGE(l, j, m) {
                // source
                RANGE(o, 1, min({a[i], m-j, m-l})) {
                    dq[j+o][l+o] += dp[j][l];
                    if (dq[j+o][l+o] >= pdiv) dq[j+o][l+o] -= pdiv;
                }
                // sink
                RANGE(o, 1, min(j, m)) {
                    dq[j-o][l] += dp[j][l];
                    if (dq[j-o][l] >= pdiv) dq[j-o][l] -= pdiv;
                }
            }
        }
        dp.swap(dq);
    }

    ll ans = 0;
    FOREACH(x, dp[0]) {
        ans += x;
        if (ans >= pdiv) ans -= pdiv;
    }
    say(ans);

}

