    for (int i=0;i<S.size();++i){
        int cnt=0;
        while(S[i]=='1') ++i,++cnt;
        ones.emplace_back(cnt);
    }
    int n=ones.size();
    reverse(ones.begin(),ones.end());
    vector<int> sum(n+1,0);
    for (int i=0;i<n;++i) sum[i+1]=sum[i]+ones[i];
    dp[0][0][0]=1;
    for (int i=0;i<n;++i){
        for (int j=0;j<MAX_N;++j){
            for (int k=0;k<MAX_N;++k){
                imos[j][k]=diag[j][k]=0;
            }
        }
        for (int j=0;j<=sum[i];++j){
            for (int k=0;k<=j;++k){
                imos[j][k]+=dp[i][j][k];
                imos[j+ones[i]][k]-=dp[i][j][k];
                diag[j+ones[i]][k]+=dp[i][j][k];
                diag[sum[i+1]+1][k+sum[i+1]-ones[i]+1]-=dp[i][j][k];
            }
        }
        for (int k=0;k<MAX_N;++k){
            for (int j=0;j<MAX_N-1;++j){
                imos[j+1][k]+=imos[j][k];
            }
        }
        for (int j=0;j<MAX_N-1;++j){
            for (int k=0;k<MAX_N-1;++k){
                diag[j+1][k+1]+=diag[j][k];
            }
        }
        for (int j=0;j<MAX_N;++j){
            for (int k=0;k<MAX_N;++k){
                dp[i+1][j][k]+=imos[j][k]+diag[j][k];
            }
        }
    }
    mint ans=0;
    for (int k=0;k<=min(MAX_N-1,K);++k) ans+=dp[n][sum[n]][k];
    cout << ans << '\n';
