#include <bits/stdc++.h>
using namespace std;

const int mod = 998244353;
const int N = 305;

int dp[N][N][N];
vector<int> ones;
int one_cnt;
int K;

int solve(int var, int op, int pref) {
    if(op > K or op < 0) return 0;
    if(var == ones.size()) return pref == one_cnt;
    if(dp[var][op][pref] != -1) return dp[var][op][pref];
    int ans = 0;
    int kone = ones[var] - (var > 0 ? ones[var-1] : 0);
    for(int x = max(0, ones[var]-pref); x + pref <= one_cnt; x++) {
        int new_op = op+max(0, x-kone);
        ans += solve(var + 1, new_op , x+pref);
        if(ans >= mod) ans -= mod;
    }
    return dp[var][op][pref] = ans;
}


