int n, k;
string s;
int cnt[N];
mint dp[N][N][N];
// dp[i][j][l] come to i'th, take j's 1, l's dif
vector<int> p;

inline void solve() {
  cin >> s >> k;
  while (s.size() && s.back() == '0') s.pop_back();
  s.push_back('0');
  p.emplace_back(0);
  for (int i = 0; i < (int)s.size(); ++i) {
    if (s[i] == '0') {
      p.emplace_back(i+1);
    }
  }
  n = p.size()-1;
  dp[0][0][0] = 1;
  int all_ones = p[n]-n;
  k = min(k, all_ones);
  for (int i = 1; i <= n; ++i) {
    int sum_ones = p[i]-i, pre_ones = p[i]-p[i-1]-1;
    for (int j = sum_ones; j <= all_ones; ++j) {
      for (int jj = 0; jj <= j; ++jj) {
        for (int l = 0; l <= k; ++l) {
          if (jj <= pre_ones) dp[i][j][l] += dp[i-1][j-jj][l];
          else if (l >= jj-pre_ones) dp[i][j][l] += dp[i-1][j-jj][l-(jj-pre_ones)];
        }
      }
    }
  }
  mint res = 0;
  for (int i = 0; i <= k; ++i) {
    res += dp[n][all_ones][i];
  }
  cout << res << endl;
}

