		for(int j = 0; j <= K; j++) for(int k = j; k <= K; k++) cnt[i+1][j][k] %= mod;
	}
	cat ans = 0;
	for(int i = 0; i <= K; i++) ans += cnt[N][0][i];
	ans %= mod;
	cout << ans << "\n";
}

