    k = min(k, ones);
    vector<vector<vector<mint>>> dp(n + 1, vector<vector<mint>>(ones + 1, vector<mint>(k + 1, 0)));
    // dp[fixed][carry][used k]
    dp[0][0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        const li cur_zeros = cnts[i - 1];
        for (int carry = 0; carry <= ones; ++carry) {
            for (int to_k = 0; to_k <= k; ++to_k) {
                for (int new_zeros = 0; new_zeros <= ones; ++new_zeros) {
                    const li consume = new_zeros - cur_zeros;
                    const li prev_carry = carry + consume;
                    if (prev_carry < 0 || prev_carry > ones) {
                        continue;
                    }
                    const li prev_k = to_k - max(0LL, -consume);
                    if (prev_k < 0 || prev_k > k) {
                        continue;
                    }
                    dp[i][carry][to_k] += dp[i - 1][prev_carry][prev_k];
                }
//                cerr << i << " " << carry << " " << to_k << " " << dp[i][carry][to_k].x << endl;
            }
        }
    }

    mint ans = 0;
    for (int i = 0; i < k + 1; ++i) {
        ans += dp[n][0][i];
    }
    cout << ans.x << endl;
    return 0;
}

