int dp[MAXN][MAXN][MAXN];
void update(int &x, int y) {
	x += y;
	if (x >= P) x -= P;
}
int main() {
	scanf("\n%s%d", s + 1, &m);
	int last = 0; l = strlen(s + 1), chkmin(m, l);
	for (int i = 1; i <= l + 1; i++)
		if (s[i] != '1') {
			a[++n] = i - last - 1;
			last = i;
		}
	dp[0][0][0] = 1;
	for (int i = 1; i <= n; i++) {
		static int b[MAXN][MAXN], c[MAXN][MAXN];
		memset(b, 0, sizeof(b));
		memset(c, 0, sizeof(c));
		for (int j = 0; j <= l; j++)
		for (int k = 0; k <= m; k++) {
			int tmp = dp[i - 1][j][k];
			if (tmp == 0) continue;
			update(b[j - min(a[i], j)][k], tmp);
			update(b[j + 1][k], P - tmp);
			update(c[j + 1][k + 1], tmp);
		}
		for (int j = 0; j <= l; j++)
		for (int k = 0; k <= m; k++) {
			if (j != 0) update(b[j][k], b[j - 1][k]);
			update(dp[i][j][k], b[j][k]);
		}
		for (int j = 0; j <= l; j++)
		for (int k = 0; k <= m; k++) {
			if (j != 0 && k != 0) update(c[j][k], c[j - 1][k - 1]);
			update(dp[i][j][k], c[j][k]);
		}
	}
	int ans = 0;
	for (int i = 0; i <= m; i++)
		update(ans, dp[n][0][i]);
	cout << ans << endl;
	return 0;
}

