const int maxn = 305;
const int mod = 998244353;
vector <int> v;
int mem[2][maxn][maxn][maxn];
int N, K;

int dp(int state, int cur, int moves, int need) {
  if(moves > K || moves > N) return 0;
  if(cur == v.size()) {
    return need == 0;
  }
  int &ans = mem[state][cur][moves][need];
  if(ans != -1) return ans;
  ans = dp(0, cur + 1, moves, need);
  if(state == 0) {
    ans += dp(1, cur, moves + 1, need + 1);
    ans %= mod;
    for(int i = 1; i <= v[cur] && i <= need; i++) {
      ans += dp(0, cur + 1, moves, need - i);
      ans %= mod;
    }
  } else {
    ans += dp(1, cur, moves + 1, need + 1);
    ans %= mod;
  }
  return ans;
}
