template<ll MOD> struct mll_{
	ll val;
	mll_(ll v = 0): val(v % MOD){ if (val < 0) val += MOD; }
	mll_ operator - () const { return -val; }
	mll_ operator + (const mll_ &b) const { return val + b.val; }
	mll_ operator - (const mll_ &b) const { return val - b.val; }
	mll_ operator * (const mll_ &b) const { return val * b.val; }
	mll_ operator / (const mll_ &b) const { return mll_(*this) /= b; }
	mll_ operator + (ll b) const { return *this + mll_(b); }
	mll_ operator - (ll b) const { return *this - mll_(b); }
	mll_ operator * (ll b) const { return *this * mll_(b); }
	friend mll_ operator + (ll a, const mll_ &b) { return b + a; }
	friend mll_ operator - (ll a, const mll_ &b) { return -b + a; }
	friend mll_ operator * (ll a, const mll_ &b) { return b * a; }
	friend mll_ operator / (ll a, const mll_ &b) { return mll_(a)/b; }
	mll_ &operator += (const mll_ &b) { val=(val+b.val)%MOD; return *this; }
	mll_ &operator -= (const mll_ &b) { val=(val+MOD-b.val)%MOD; return *this; }
	mll_ &operator *= (const mll_ &b) { val=(val*b.val)%MOD; return *this; }
	mll_ &operator /= (const mll_ &b) {
		ll c=b.val, d=MOD, u=1, v=0;
		while (d){
			ll t = c / d;
			c -= t * d; swap(c, d);
			u -= t * v; swap(u, v);
		}
		val = val * u % MOD;
		if (val < 0) val += MOD;
		return *this;
	}
	mll_ &operator += (ll b) { return *this += mll_(b); }
	mll_ &operator -= (ll b) { return *this -= mll_(b); }
	mll_ &operator *= (ll b) { return *this *= mll_(b); }
	mll_ &operator /= (ll b) { return *this /= mll_(b); }
	bool operator == (const mll_ &b) { return val == b.val; }
	bool operator != (const mll_ &b) { return val != b.val; }
	bool operator == (ll b) { return *this == mll_(b); }
	bool operator != (ll b) { return *this != mll_(b); }
	friend bool operator == (ll a, const mll_ &b) { return mll_(a) == b.val; }
	friend bool operator != (ll a, const mll_ &b) { return mll_(a) != b.val; }
	friend ostream &operator << (ostream &os, const mll_ &a) { return os << a.val; }
	friend istream &operator >> (istream &is, mll_ &a) { return is >> a.val; }
	static mll_ Combination(ll a, ll b){
		chmin(b, a-b);
		if (b<0) return mll_(0);
		mll_ c = 1;
		REP(i, b) c *= a-i;
		REP(i, b) c /= i+1;
		return c;
	}
};
using mll = mll_<998244353LL>; //1000000007LL;// 998244353LL;
using vmll = std::vector<mll>;
using vvmll = std::vector<vmll>;
using vvvmll = std::vector<vvmll>;
using vvvvmll = std::vector<vvvmll>;
using vvvvvmll = std::vector<vvvvmll>;



void solve()
{
	string s_;  cin >> s_;
	ll K;  cin >> K;
	ll len=sz(s_);
	vll s=str2num(s_, len);

	vll P;
	{
		ll cnt=0;
		dep(i, len-1, 0){
			if (s[i]==1) cnt++;
			else{
				P.push_back(cnt);
				cnt=0;
			}
			if (i==0){P.push_back(cnt);}
		}
	}

	ll N=sz(P);
	ll J=Sum(P);
	K=min(K, J);

	vvvmll dp(N, vvmll(J+1, vmll(K+1)));
	auto Dp = [&](ll i, ll j, ll k)->mll&{
		return dp[i][j][k];
	};
	vvvmll dq(N, vvmll(J+1, vmll(K+1)));
	auto Dq = [&](ll i, ll j, ll k)->mll&{
		static mll dmy=0;
		if (j<0 or k<0)return dmy;
		return dq[i][j][k];
	};
	vvvmll dr(N, vvmll(J+1, vmll(K+1)));
	auto Dr = [&](ll i, ll j, ll k)->mll&{
		return dr[i][j][k];
	};

	auto imos = [&](ll i){
		rep(j, 0, J)rep(k, 0, K){
			dq[i][j][k]=dp[i][j][k];
			dr[i][j][k]=dp[i][j][k];
		}
		//dq
		rep(jj, 1, J)rep(kk, 1, K){
			dq[i][jj][kk] += dq[i][jj-1][kk-1];
		}
		//dr
		dep(jj, J-1, 0)rep(kk, 0, K){
			dr[i][jj][kk] += dr[i][jj+1][kk];
		}
	};

	//初期化
	rep(j, 0, min(P[0],K)){
		Dp(0, j, j)=1;
	}
	imos(0);

	//dp本体
	rep(ii, 1, N-1){
		ll i=ii-1;
		rep(jj, 0, J)rep(kk, 0, K){
			Dp(ii, jj, kk)+=Dq(i, jj, kk);
			Dp(ii, jj, kk)-=Dq(i, jj-P[ii]-1, kk-P[ii]-1);
			Dp(ii, jj, kk)+=Dr(i, jj, kk);
			Dp(ii, jj, kk)-=Dp(i, jj, kk);
		}
		imos(ii);
	}

	mll ans=0;
	rep(k, 0, K){
		ans+=Dp(N-1, 0, k);
	}
	cout << ans << '\n';
	//Dump(dp);
	//Dump(dq);
	//Dump(dr);
}

