int main() {
  std::string S;
  std::cin >> S;
  i32 K;
  std::cin >> K;
  S.push_back('0');
  std::reverse(S.begin(), S.end());
  std::vector<i32> one;
  for (auto c: S) {
    if (c == '1') one.back()++;
    else one.push_back(0);
  }
  i32 N = one.size();
  std::vector<i32> pref(N + 1);
  for (i32 i = 0; i < N; ++i) {
    pref[i + 1] = pref[i] + one[i];
  }
  i32 all = pref.back();
  std::vector<std::vector<m32>> dp(all + 1, std::vector<m32>(all + 1));
  dp[0][0] = (m32) 1;
  for (i32 i = 0; i < N; ++i) {
    std::vector<std::vector<m32>> next(all + 1, std::vector<m32>(all + 1));
    for (i32 j = 0; j <= pref[i]; ++j) {
      for (i32 l = 0; l <= pref[i]; ++l) {
        if (dp[j][l].zero()) continue;
        for (i32 k = 1; k <= one[i]; ++k) {
          if (j + k > K) break;
          next[j + k][l + k] += dp[j][l];
        }
        for (i32 k = one[i]; k <= pref[i + 1]; ++k) {
          if (k > l + one[i]) break;
          next[j][l + one[i] - k] += dp[j][l];
        }
      }
    }
    dp = std::move(next);
  }
  m32 ans;
  for (i32 i = 0; i <= std::min(K, all); ++i) {
    ans += dp[i][0];
  }
  std::cout << ans << '\n';
  return 0;
}

