                DP[{exist + have - leave, moves + max(0, exist - leave)}] += e.s;
            }
        }
        swap(dp, DP);
    }

    mn ans = 0;
    trav (e, dp) {
        if (e.f.f == 0 && e.f.s <= K)
            ans += e.s;
    }
    ps(ans);

    // did you check N=1? did you mix up N,M?
    // check your "infinity" and "null" values against the bounds
    return 0;
}

