inline void construct() {
    int sz = 1;
    for(int i = 1; i <= n && s[i] == '1'; ++i)
        a[1] = i;
    for(int i = a[1] + 1; i <= n; ++i) {
        int j = i;
        if(s[i] == '0') {
            while(j + 1 <= n && s[j + 1] == '0') {
                a[++sz] = 0;
                ++j;
            }
        }
        else {
            while(j + 1 <= n && s[j + 1] == '1')
                ++j;
            a[++sz] = j - i + 1;
        }
        i = j;
    }
    n = sz;
}

inline void solve() {
    // dp[i][operation_applied][free_ones]
    dp[n + 1][0][0] = 1;
    int sum = 0;
    for(int i = n; i >= 1; --i) {
        for(int k = 0; k <= n; ++k) {
            for(int t = 0; t <= sum; ++t) {
                for(int j = 0; j <= a[i] && k + j < N; ++j)
                    add_t(dp[i][k + j][j + t], dp[i + 1][k][t]);
                for(int j = 0; j < t; ++j)
                    add_t(dp[i][k][j], dp[i + 1][k][t]);
            }
        }
        sum += a[i];
    }
}

inline void output() {
    int ans = 0;
    for(int i = 0; i < min(N, k + 1); ++i)
        add_t(ans, dp[1][i][0]);
