const int N = 305, P = 998244353;

int n, k, m, f[N][N], s1[N][N], s2[N][N];
char s[N];

void solve() {
	n = readStr(s + 1), read(k);
	std::vector<int> a(1);
	int lst = 0;
	for (int i = 1; i <= n; ++i) {
		if (s[i] == '0') {
			a.push_back(i - lst - 1);
			lst = i;
		}
	}
	a.push_back(n - lst);
	int m = (int)a.size() - 1;
	std::vector<int> sum(m + 1);
	sum[0] = 0;
	for (int i = 1; i <= m; ++i) {
		sum[i] = sum[i - 1] + a[i];
	}
	f[0][0] = 1;
	for (int i = 0; i <= n; ++i) {
		for (int j = 0; j <= n; ++j) {
			s1[i][j] = s2[i][j] = f[i][j];
			if (i) {
				s1[i][j] = (s1[i][j] + s1[i - 1][j]) % P;
				if (j) {
					s2[i][j] = (s2[i][j] + s2[i - 1][j - 1]) % P;
				}
			}
		}
	}
	for (int k = 1; k <= m; ++k) {
		for (int i = 0; i <= n; ++i) {
			for (int j = 0; j <= n; ++j) {
				if (i < sum[k]) {
					f[i][j] = 0;
					continue;
				}
				f[i][j] = s1[i][j];
				if (i >= a[k]) {
					f[i][j] = (f[i][j] + P - s1[i - a[k]][j]) % P;
					f[i][j] = (f[i][j] + s2[i - a[k]][j]) % P;
				}
			}
		}
		for (int i = 0; i <= n; ++i) {
			for (int j = 0; j <= n; ++j) {
				s1[i][j] = s2[i][j] = f[i][j];
				if (i) {
					s1[i][j] = (s1[i][j] + s1[i - 1][j]) % P;
					if (j) {
						s2[i][j] = (s2[i][j] + s2[i - 1][j - 1]) % P;
					}
				}
			}
		}
	}
	int ans = 0;
	for (int j = 0; j <= n && j <= k; ++j) {
		ans = (ans + f[sum[m]][j]) % P;
	}
	print(ans);
}

int main() {
	int T = 1;
	// read(T);
	while (T--) {
		solve();
	}
}

