i64 dp[302][302][302];

signed main() {
	INIT;

	VAR(std::string, s);
	VAR(int, k);

	int one = 0;
	REP(i, s.size()) one += s[i] == '1';
	CHMIN(k, one);

	V<int> a;
	{
		int now = 0;
		REP(i, s.size()) {
			if (s[i] == '0') {
				a.emplace_back(now);
				now = 0;
			}
			else {
				++now;
			}
		}
		a.emplace_back(now);
		std::reverse(ALL(a));
	}

	dp[0][0][0] = 1;
	REP(i, a.size()) REP(j, one + 1) REP(l, k + 1) {
		if (dp[i][j][l] == 0) continue;
		REP(m, a[i] + j + 1) {
			if (m <= a[i]) {
				int t = a[i] - m;
				if (l + t > k) continue;
				(dp[i + 1][j + t][l + t] += dp[i][j][l]) %= MOD;
			}
			else {
				int t = m - a[i];
				(dp[i + 1][j - t][l] += dp[i][j][l]) %= MOD;
			}
		}
	}
	i64 ans = 0;
	REP(l, k + 1) (ans += dp[a.size()][0][l]) %= MOD;
	OUT(ans)BR;

	return 0;
}

