			// 	nx[i+di][j+min(di,num[v])] += dp[i][j];
			// }

			if(i == N){
				nx[i][j] += dp[i][j];
				continue;
			}
			if(a[i] < v) break;
			int n = num[v];
			if(N-i <= n){
				f[i][j] += dp[i][j];
			}else{
				f[i][j] += dp[i][j];
				f[i+n][j+n] -= dp[i][j];
				g[i+n][j+n] += dp[i][j];
			}

		}
		rep(i,N+1) rep(j,N+1){
			nx[i][j] += f[i][j]+g[i][j];
			f[i+1][j+1] += f[i][j];
			g[i+1][j] += g[i][j];
		}
		swap(dp,nx);
	}
	mint res = 0;
	rep(j,N+1) if(j+X >= N) res += dp[N][j];
	return res;
}

