void solve_test() {
  string ss;
  int n, K;
  cin >> ss >> K;
  ss = ss + '0';
  while (ss.size() && ss[0] == '1') {
    ss = ss.substr(1);
  }
  n = ss.size();
  K = min(K, n);
  if (K == 0) {
    cout << 1 << endl;
    return;
  }

  vector<int> s;
  for (int i = 0; i < n; ++i) {
    int tl = i;
    while (tl < n && ss[tl] == '1') {
      ++tl;
    }
    s.emplace_back(tl - i);
    i = tl;
  }
  n = s.size();

  dp[n][0][0] = 1;
  for (int i = n-1; i >= 0; --i) {
    for (int j = 0; j <= K; ++j) {
      for (int k = 0; k <= K; ++k) {
        // giving up non-zero amount of ones. 
        for (int l = max(s[i] - k, 0); l <= s[i]; ++l) {
          dp[i][j][k] += dp[i+1][j][k-s[i]+l]; 
        }
        // taking positive amount of ones.
        for (int l = 1; l <= min(j, K-k); ++l) {
          dp[i][j][k] += dp[i+1][j-l][k+l]; 
        }
      }
    }
  }

  Mod ans = 0; 
  for (int i = 0; i <= K; ++i) {
    ans += dp[0][i][0];
  }
  cout << ans << endl;
}

