const int64_t MOD = 998244353;
void add(int64_t& a, int64_t b){
    a = (a+b) % MOD;
}
void mul(int64_t& a, int64_t b){
    a = a*b % MOD;
}

int main(){
    string str;
    cin >> str;
    int N = str.size();
    vector<int> S(N);
    for(int i=0; i<N; i++) S[i] = str[i] - '0';
    int K;
    cin >> K;
    int N1 = accumulate(S.begin(), S.end(), 0);
    int N0 = N-N1;
    K = min(K, N1);

    // 0 で区切った時の各エリアの1の個数と、その累積和
    vector<int> one, oneS;
    int len = 0;
    for(int i=0; i<N; i++){
        if(S[i]){
            len++;
        }else{
            one.push_back(len);
            len = 0;
        }
    }
    one.push_back(len);
    oneS = one;
    for(int i=1; i<=N0; i++) oneS[i] += oneS[i-1];

    // エリアi-1まで見て、操作をj回使って、1をk回使った
    static int64_t dp[310][310][310];
    dp[0][0][0] = 1;
    for(int i=0; i<=N0; i++){
        // 元々あった one[i] 個の1を全部は使わないパターン
        // 0～(one[i]-1) 個使って合計k個になるような遷移元を累積和で処理
        for(int j=0; j<=K; j++){
            int64_t s = 0;
            for(int k=0; k<=N1; k++){
                add(s, dp[i][j][k]);
                if(k >= one[i]) add(s, MOD - dp[i][j][k-one[i]]);
                // 使った1の個数が oneS[i] 個以上なら遷移
                if(k >= oneS[i]) add(dp[i+1][j][k], s);
            }
        }
        // 元々あった one[i] 個の1を全部使って、さらに移動してきた1を0個以上使うパターン
        for(int j=0; j<=K; j++) for(int k=0; k<=N1; k++){
            // 移動してきた1を1個使って同じiに遷移
            add(dp[i][j+1][k+1], dp[i][j][k]);
            // one[i] 個の1を使い、使った1の個数が oneS[i] 個以上ならi+1遷移
            if(k+one[i] >= oneS[i]) add(dp[i+1][j][k+one[i]], dp[i][j][k]);

        }
    }

    int64_t ans = 0;
    for(int j=0; j<=K; j++) add(ans, dp[N0+1][j][N1]);
    cout << ans << endl;
    return 0;
}

