const int N = 301;
ll dp[N][N][N];
ll suf[N][N];
ll pr[N][N];

void solve(){
	string s;
	cin >> s;
	ll k;
	cin >> k;
	ll n = sz(s);
	v64 vec;
	ll n1=0,n0=0;
	ll c = 0;
	forn(i,n){
		if(s[i]=='0') {
			vec.pb(c),c=0;
			n0++;
		}
		else {
			c++;
			n1++;
		}
	}
	k = min(k,n1);
	vec.pb(c);
	dp[0][0][0]=1;
	suf[0][0]=1;
	forn(j,n1+1) pr[j][0]=1; 
	forn(i,n0+1){
		forn(j,n1+1){
			forsn(l,j,k+1){
				ll v = vec[i];
				ll ju = j+v+1;
				ll jl = j-(n1-v)-1;
				dp[i+1][j][l] = suf[j][l] - (ju>n1 ? 0 : suf[ju][l]) + pr[j][l-j] - (jl<0 ? 0 : pr[jl][l-j]) - dp[i][j][l] + 3*MOD;
				ll c = dp[i+1][j][l]/MOD;
				dp[i+1][j][l]-=c*MOD;
				// if(i==0) cout << v << " " << ju << " " << jl << ln;
				// if(i==0) cout << suf[j][l] << " " << suf[ju][l] << " " << pr[j][l-j] << " " << dp[i][j][l];
				// cout << i << " " << j << " " << l << " " << dp[i+1][j][l] << ln;
			}
		}
		forn(l,k+1){
			ll cur = 0;
			rforn(j,n1){
				cur += dp[i+1][j][l];
				if(cur>=MOD) cur-=MOD;
				suf[j][l] = cur;
			}
		}
		forn(l,k+1){
			ll cur = 0;
			forn(j,n1+1){
				if(j+l > k) break;
				cur += dp[i+1][j][j+l];
				if(cur>=MOD) cur-=MOD;
				pr[j][l] = cur;
			}
		}
	}
	// cout << n0 << ln;
	ll ans = 0;
	forn(i,k+1){
		// cout << n0 << " " << i << " " << dp[n0][0][i] << ln;
		ans += dp[n0+1][0][i];
		ans %= MOD;
	}
	cout << ans << ln;
}

