template<int M>
struct ModInt {
public:
	using value_type = long long;

	ModInt(value_type val = 0) : val(val < 0 ? (M - (-val % M)) % M : val % M) {}

	explicit operator bool() const noexcept { return val; }
	bool operator ==(const ModInt & rhs) const noexcept { return val == rhs.val; }
	bool operator !=(const ModInt & rhs) const noexcept { return !(*this == rhs); }
	ModInt operator +() const noexcept { return ModInt(*this); }
	ModInt operator -() const noexcept { return ModInt(0) -= *this; }
	ModInt operator +(const ModInt & rhs) const noexcept { return ModInt(*this) += rhs; }
	ModInt operator -(const ModInt & rhs) const noexcept { return ModInt(*this) -= rhs; }
	ModInt operator *(const ModInt & rhs) const noexcept { return ModInt(*this) *= rhs; }
	ModInt operator /(const ModInt & rhs) const noexcept { return ModInt(*this) /= rhs; }

	ModInt & operator +=(const ModInt & rhs) noexcept {
		val += rhs.val;
		if (val >= M) val -= M;
		return *this;
	}
	ModInt & operator -=(const ModInt & rhs) noexcept {
		if (val < rhs.val) val += M;
		val -= rhs.val;
		return *this;
	}
	ModInt & operator *=(const ModInt & rhs) noexcept {
		val = val * rhs.val % M;
		return *this;
	}
	ModInt & operator /=(const ModInt & rhs) noexcept {
		*this *= rhs.inverse();
		return *this;
	}

	ModInt pow(value_type n) const {
		ModInt res = 1, x = val;
		if (n < 0) { x = x.inverse(); n = -n; }
		while (n) { if (n & 1) res *= x; x *= x; n >>= 1; }
		return res;
	}

	ModInt inverse() const {
		long long a = val, a1 = 1, a2 = 0, b = M, b1 = 0, b2 = 1;
		while (b > 0) {
			value_type q = a / b, r = a % b;
			value_type nb1 = a1 - q * b1, nb2 = a2 - q * b2;
			a = b; b = r;
			a1 = b1; b1 = nb1;
			a2 = b2; b2 = nb2;
		}
		assert(a == 1);
		return a1;
	}

	const value_type & get() const noexcept { return val; }
	static decltype(M) get_mod() noexcept { return M; }

	friend std::ostream & operator <<(std::ostream & os, const ModInt & rhs) { return os << rhs.val; }
	friend std::istream & operator >>(std::istream & is, ModInt & rhs) {
		value_type x;
		is >> x;
		rhs = ModInt(x);
		return is;
	}
private:
	value_type val;
};
using mint = ModInt<MOD>;

int main() {
	string S;
	int K;
	cin >> S >> K;
	chmin(K, S.size());

	vector<int> A;
	A.emplace_back(0);

	for (int i = 0; i < S.size(); ++i) {
		if (S[i] == '1') continue;
		int p = 1;
		while (i + p < S.size() && S[i + p] == '1') ++p;
		A.emplace_back(p - 1);
		i += p - 1;
	}
	reverse(ALL(A));

	// dp[i][j][k] := i 番目までで合計 j 回 '1' を飛ばして合計 k 回飛ばした '1' を置いた数
	vector<vector<vector<mint>>> dp(A.size() + 1, vector<vector<mint>>(S.size() + 1, vector<mint>(S.size() + 1)));
	dp[0][0][0] = 1;

	vector<vector<vector<mint>>> sumj(A.size() + 1, vector<vector<mint>>(S.size() + 2, vector<mint>(S.size() + 2))), sumk = sumj;

	sumj[0][1][1] = 1;
	sumk[0][1][1] = 1;
	REP(j, S.size() + 2) REP(k, S.size() + 2) {
		if (j < S.size() + 1) sumj[0][j + 1][k] += sumj[0][j][k];
		if (k < S.size() + 1) sumk[0][j][k + 1] += sumk[0][j][k];
	}

	FOR(i, 1, A.size() + 1) {
		REP(j, S.size() + 2) {
			REP(k, S.size() + 2) {
				if (j < S.size() + 1) sumj[i][j + 1][k] += sumj[i][j][k];
				if (k < S.size() + 1) sumk[i][j][k + 1] += sumk[i][j][k];
				if (j == S.size() + 1 || k == S.size() + 1) continue;
				if (j < k) continue;

				// 前回 c 個 '1' を置いた

				// 前回飛ばした
				// 0 \leq c \leq A[i - 1]
				// \sum dp[i - 1][j - (A[i - 1] - c)][k]
				// = \sum dp[i - 1][j - 0..A[i-1]][k]

				// 前回飛ばさなかった
				// A[i - 1] < c
				// \sum dp[i - 1][j][k - (c - A[i - 1])]
				// = \sum dp[i - 1][j][0..k-1]

				dp[i][j][k] = sumj[i - 1][j + 1][k + 1] - sumj[i - 1][max(j - A[i - 1], 0)][k + 1];
				dp[i][j][k] += sumk[i - 1][j + 1][k];

				sumj[i][j + 1][k + 1] += dp[i][j][k];
				sumk[i][j + 1][k + 1] += dp[i][j][k];

				// printf("%d %d %d %lld\n", i, j, k, dp[i][j][k].get());
			}
		}
	}

	// for (int u : A) printf("%d ", u);
	// puts("");

	mint ans = 0;
	REP(i, K + 1) ans += dp[A.size()][i][i];
	cout << ans << endl;
}

