    }
    v my_count(sz(vec));
    for(int i=0;i<sz(vec)-1;i++)
    {
        my_count[i]=vec[i+1]-vec[i]-1;
    }
    my_count[sz(vec)-1]=n-1-vec.back();
    int jmax=n-sz(vec);
