    rep(l, j) dp[i+1][j][k] += dp[i][l][k-j+l];
  }

  chmin(K, n);
  mint ans = 0;
  rep(k, K+1) ans += dp[n][0][k];
  cout << ans << "\n";
  return 0;
}

