tint f(int idx, int balance, int missingOps) {
	if (idx + 1 == (int) pos.size()) return balance == balanced;
	if (memo[idx][balance][missingOps] != -1) return memo[idx][balance][missingOps];

	tint res = f(idx + 1, balance, missingOps);
	if (balance > balanced) {
		forsn(j, 1, min(balance - balanced + 1, pos[idx + 1] - pos[idx])) {
			res += f(idx + 1, balance - j, missingOps);
			res %= MOD;
		}
	}
	forsn(i, 1, missingOps + 1) {
		res += f(idx + 1, balance + i, missingOps - i);
		res %= MOD;
	}

	memo[idx][balance][missingOps] = res;
	return res;
}

