using CostType = bool;
struct Edge {
  int src, dst; CostType cost;
  Edge(int src, int dst, CostType cost = 0) : src(src), dst(dst), cost(cost) {}
  inline bool operator<(const Edge &x) const {
    return cost != x.cost ? cost < x.cost : dst != x.dst ? dst < x.dst : src < x.src;
  }
  inline bool operator<=(const Edge &x) const { return !(x < *this); }
  inline bool operator>(const Edge &x) const { return x < *this; }
  inline bool operator>=(const Edge &x) const { return !(*this < x); }
};

int main() {
  int n, m; cin >> n >> m;
  vector<vector<Edge>> graph(n);
  while (m--) {
    int c, a, b; cin >> c >> a >> b;
    graph[a].emplace_back(a, b, c);
    graph[b].emplace_back(b, a, c);
  }
  vector type_b(n, INF);
  type_b[0] = 0;
  deque<int> deq;
  deq.emplace_back(0);
  while (!deq.empty()) {
    int ver = deq.front();
    deq.pop_front();
    for (const Edge &e : graph[ver]) {
      if (e.cost) {
        if (type_b[e.dst] > type_b[ver] + 1) {
          type_b[e.dst] = type_b[ver] + 1;
          deq.emplace_back(e.dst);
        }
      } else {
        if (type_b[e.dst] > type_b[ver]) {
          type_b[e.dst] = type_b[ver];
          deq.emplace_front(e.dst);
        }
      }
    }
  }
  // REP(i, n) cout << type_b[i] << " \n"[i + 1 == n];
  vector<unordered_map<int, ll>> dist(n);
  dist[0][0] = 0;
  using P = pair<ll, pair<int, int>>;
  priority_queue<P, vector<P>, greater<P>> que;
  que.emplace(0, make_pair(0, 0));
  while (!que.empty()) {
    ll cost = que.top().first;
    auto [i, j] = que.top().second;
    que.pop();
    if (cost > dist[i][j]) continue;
    for (const Edge &e : graph[i]) {
      ll nx = cost + 1;
      if (e.cost) {
        if (1LL * (j + 1) * (j + 2) / 2 - 1LL * type_b[e.dst] * (type_b[e.dst] + 1) / 2 <= n - 1) {
          nx += j;
          if (dist[e.dst].count(j + 1) == 0) dist[e.dst][j + 1] = LINF;
          if (nx < dist[e.dst][j + 1]) {
            dist[e.dst][j + 1] = nx;
            que.emplace(nx, make_pair(e.dst, j + 1));
          }
        }
      } else {
        if (1LL * j * (j + 1) / 2 - 1LL * type_b[e.dst] * (type_b[e.dst] + 1) / 2 <= n - 1) {
          if (dist[e.dst].count(j) == 0) dist[e.dst][j] = LINF;
          if (nx < dist[e.dst][j]) {
            dist[e.dst][j] = nx;
            que.emplace(nx, make_pair(e.dst, j));
          }
        }
      }
    }
  }
  REP(i, n) {
    ll ans = LINF;
    for (auto [ignore, cost] : dist[i]) chmin(ans, cost);
    cout << ans << '\n';
  }
  return 0;
}

