                ones.emplace_back(cnt);
                cnt = 0;
            }
        }
    }
    for(auto one : ones) cerr << one << " ";
    cerr << endl;

    int M = ones.size(), ones_sum = 0;
    dp[0][0][0] = mint(1);
    for(int t=0; t<M; t++) {
        mint tmp[310][310];
        fill(tmp[0], tmp[305], mint(0));

        for(int i=0; i<=ones_sum; i++) {
            for(int k=0; k<=K; k++) {
                // (j-i-ones[t] <= 0) -> (j <= i+ones[t])
                // i から i+ones[t] まではノーコストで遷移可能
                // i+ones[t]+1 から ones_sum+ones[t] までは 1 ずつ増えてく

                // ノーコスト遷移
                {
                    dp[t+1][i][k] += dp[t][i][k];
                    dp[t+1][i+ones[t]][k] -= dp[t][i][k];
                }
                // 1 ずつ増える遷移
                int c = min(K-k, ones_sum-i);
                {
                    tmp[i+ones[t]][k] += dp[t][i][k];
                    tmp[i+ones[t]+c+1][k+c+1] -= dp[t][i][k];
                }                
            }
        }
        for(int j=0; j<=N; j++) {
            for(int k=0; k<=K; k++) {
                tmp[j+1][k+1] += tmp[j][k];
            }
        }
        for(int j=0; j<=N; j++) {
            for(int k=0; k<=K; k++) {
                if(j > 0) dp[t+1][j][k] += dp[t+1][j-1][k];
            }
        }
        for(int j=0; j<=N; j++) {
            for(int k=0; k<=K; k++) {
                dp[t+1][j][k] += tmp[j][k];
            }
        }
        ones_sum += ones[t];
    }

    mint ans(0);
    for(int i=0; i<=K; i++) ans += dp[M][ones_sum][i];
    cout << ans << endl;
    return 0;
}

