				dp[i][k][d - 1][0] = dp[i][k][0][1];
				for (UL n = d - 2; n != (UL)-1; n--)
					dp[i][k][n][0] = 0;

				for (UL n = N; n != (UL)-1; n--) dp[i][k][n][1] = 0;
			}
		}
		for (UL k = 0; k <= mK; k++) {
			for (UL n = N; n != (UL)-1; n--) {
				dp[i][k][n][0] %= M;
				dp[i][k][n][1] %= M;
				if (k != mK) if(i != I) if(n != 0) dp[i + 1][k + 1][n][1] += dp[i][k][n][0] + dp[i][k][n][1];
				if (i != I) dp[i + 1][k][n][0] += dp[i][k][n][0];
			}
		}
	}
	ULL ans = 0;
	for (UL k = 0; k <= mK; k++) {
		for (UL n = 0; n <= N; n++) {
			ans += dp[I][k][n][0] + dp[I][k][n][1];
		}
	}
	ans %= M;
	return ans;
}

