ll solve(ll idx, ll carry, ll left) {
	if(carry < 0 || left < 0) {
		return 0;
	}
	if(idx == -1) {
		return carry == 0;
	}
	if(dp[idx][carry][left] != -1) {
		return dp[idx][carry][left];
	}
	ll ans = 0;
	for(ll i = 0; i <= zeros[idx] + carry; i++) {
		ll now = zeros[idx] + carry - i;
		ll used = max((ll)0, zeros[idx] - i);
		ans = (ans + solve(idx - 1, now, left - used)) % MOD;
	}
	return dp[idx][carry][left] = ans;
}

