ll dp(int id, int rem, int ex, int f){
	if (id == 0) return (ex == 0);
	if (mem[id][rem][ex][f] != -1) return mem[id][rem][ex][f];
	ll res = 0;
	if (s[id-1] == '1'){
		if (rem >= 1) res += dp(id-1,rem-1,ex+1,0);
		if (f == 0) res += dp(l[id],rem,ex,0);
	}
	else if (id == 1 || s[id-2] == '0'){
		res += dp(id-1,rem,ex,0);
		if (ex >= 1) res += dp(id,rem,ex-1,0);
	}
	else {
	    if (f == 0){
            res += dp(id-1,rem,ex,1);
	    }
		if (ex >= 1) res += dp(id,rem,ex-1,1);
		res += dp(l[id],rem,ex,0);
	}
	res %= mod;
	//printf("%d %d %d %lld\n",id,rem,ex,res);
	return mem[id][rem][ex][f] = res;
}
