unordered_map<ll, int> dp;
ll state_to_num(int i, int j, int k) {
  return 1LL*i*1E10 + 1LL*j*1E6 + k;
}

int combinations(int i, int j, int k) {
  if(i < 0) return 1;
  if(dp.count(state_to_num(i, j, k)) == 1) {
    return dp[state_to_num(i, j, k)];
  }

  int id = i;
  while(id >= 0 && s[id] == '1') id--;
  if(id == -1) return 1;
  int ans = 0;
  for(int ps = 0;ps <= (i-id+j);ps++) {
    if(ps <= j) {
      ans += combinations(id-1, ps, k);
    } else if(ps-j <= k) {
      ans += combinations(id-1, ps, k-ps+j);
    }
    ans %= mod;
  }
  return dp[state_to_num(i, j, k)] = ans;
}

