struct solver
{
    using mint=modint<998244353>;

    solver()
    {
        string s; int K; cin>>s>>K;
        int n=s.size();

        vector<int> ons{0};
        for(char c:s)
        {
            if(c-'0')
            {
                ons.back()++;
            }
            else
            {
                ons.push_back(0);
            }
        }

        n++;
        if(K>n) K=n;

        vector dp(K+2,vector<mint>(n+1));
        dp[0][0]=1;
        for(int x: ons)
        {
            auto tmp(dp);
            for(auto &v: dp) v.insert(begin(v),0);

            for(int i=0; i<x; i++)
            {
                for(int j=K; j>=0; j--)
                {
                    mint acc=0;
                    for(int h=n; h>0; h--)
                    {
                        if(j) acc+=tmp[j-1][h];
                        tmp[j][h]=acc;
                        dp[j][h]+=acc;
                    }
                }
            }
        }

        mint ans;
        for(int i=0; i<=K; i++)
        {
            for(int j=0; j<=n; j++)
            {
                ans+=dp[i][j];
            }
        }
        cout << ans << "\n";
    }
};
