int dp (int i, int ant, int k);

int s1 (int i, int ant, int k) {
	if (v[i - 1] + ant >= n) return 0;

	int &res = sm1[i][ant][k];
	if (res != -1) return res;

	res = dp(i, ant, k) + s1(i, ant + 1, k);
	if (res >= mod) res -= mod;

	return res;
}

int s2 (int i, int ant, int k) {
	if (ant < 0 || k < 0) return 0;

	int &res = sm2[i][ant][k];
	if (res != -1) return res;

	res = dp(i, ant, k) + s2(i, ant - 1, k - 1);
	if (res >= mod) res -= mod;

	return res;
}

int dp (int i, int ant, int k) {
	if (k < 0) return 0;
	if (i && v[i - 1] + ant >= n) return 0;
	if (i == v.size()) return ant <= k;

	int &res = mem[i][ant][k];
	if (res != -1) return res;
	res = 0;

	res = s1(i + 1, ant, k);
	res += s2(i + 1, ant - 1, k - 1);
	if (res >= mod) res -= mod;

	if (i && v[i - 1] + ant >= v[i]) {
		int nex = v[i - 1] + ant - v[i];
		res -= s2(i + 1, nex, k - (ant - nex));
		if (res < 0) res += mod;
	}

	return res;
}

