template<uint_fast64_t Modulus = MOD>
struct Modint {
  using u64 = uint_fast64_t;
  u64 a;

  constexpr Modint(const u64 x = 0) noexcept : a(x % Modulus) {}

  constexpr Modint operator+(const Modint rhs) const noexcept {
    return Modint(*this) += rhs;
  }
  constexpr Modint operator-(const Modint rhs) const noexcept {
    return Modint(*this) -= rhs;
  }
  constexpr Modint operator*(const Modint rhs) const noexcept {
    return Modint(*this) *= rhs;
  }
  constexpr Modint operator/(const Modint rhs) const noexcept {
    return Modint(*this) /= rhs;
  }

  constexpr Modint &operator+=(const Modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) a -= Modulus;
    return *this;
  }
  constexpr Modint &operator-=(const Modint rhs) noexcept {
    if (a < rhs.a) a += Modulus;
    a -= rhs.a;
    return *this;
  }
  constexpr Modint &operator*=(const Modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr Modint &operator/=(Modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp & 1) *this *= rhs;
      rhs *= rhs;
      exp >>= 1;
    }
    return *this;
  }

  explicit operator bool() const {
    return a;
  }

  friend ostream &operator<<(ostream &os, const Modint &m) {
    return os << m.a;
  }
};

using mint = Modint<MOD2>;

template<typename T>
struct ModCombination {
  vector<T> fac, finv, inv;

  ModCombination(int MAX) : fac(MAX + 1), finv(MAX + 1), inv(MAX + 1) {
    fac[0] = finv[MAX] = inv[0] = 1;
    for (int i=1; i<=MAX; ++i) fac[i] = fac[i-1] * i;
    finv[MAX] /= fac[MAX];
    for (int i=MAX-1; i>=0; --i) finv[i] = finv[i+1] * (i+1);
    for (int i=1; i<=MAX; ++i) inv[i] = finv[i] * fac[i-1];
  }

  T P(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[n-r];
  }

  T C(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[r] * finv[n-r];
  }

  T H(int n, int r) const {
    if (n < 0 || r < 0) return 0;
    return C(n + r - 1, r);
  }
};

void solve() {
  string s; int k; cin >> s >> k;

  Graph<int> g(1, vi(2, 0));
  g[0][s[0]-'0']++;
  int n = s.size();

  rep1(i,n) {
    if (s[i] == '0') {
      if (s[i-1] == '1') {
        g.emplace_back(vi{1, 0});
      } else {
        g.back()[0]++;
      }
    } else {
      g.back()[1]++;
    }
  }

  ModCombination<mint> comb(n);
  int sz = g.size();

  Spacial<mint> dp(sz+1, Graph<mint>(n+1, vector<mint>(n+1)));
  dp[sz][0][0] = 1;

  Graph<mint> skip(n+1, vector<mint>(n+1));

  rrep(i,sz) {
    Graph<mint> tmp(n+1, vector<mint>(n+1));

    repeq(x,n) {
      repeq(y,x) if (dp[i+1][x][y]) {
        tmp[x][y] += dp[i+1][x][y];
        rep1eq(z,g[i][1]) {
          tmp[x+z][y] += dp[i+1][x][y] - skip[x][y];
        }
      }
    }

    for (auto &v : skip) for (auto &a : v) a = 0;

    repeq(x,n) {
      repeq(y,x) if (tmp[x][y]) {
        repeq(z,x-y) {
          dp[i][x][y+z] += tmp[x][y] * comb.H(g[i][0], z);
          if (z) skip[x][y+z] += tmp[x][y] * (comb.H(g[i][0], z) - comb.H(g[i][0] - 1, z));
        }
      }
    }
  }

  mint ans = 0;
  int MAX = min(n, k);
  repeq(i,MAX) ans += dp[s[0] - '0'][i][i];
  cout << ans << endl;
}


