using namespace std;

int main() {
  string S;
  int K;
  int64_t Q=998244353;
  cin>>S>>K;
  vector<int> p;
  int a=0,A=0,V=S.size();
  for(int i=0;i<V;i++){
    if(S.at(i)=='1'){
      a++;
      A++;
    }
    else{
      p.push_back(a);
      a=0;
    }
  }
  int N=p.size();
  K=min(K,A);
  vector<vector<vector<int64_t>>> dp(K+1,vector<vector<int64_t>>(K+1,vector<int64_t>(N+1)));
  vector<vector<vector<int64_t>>> yr(K+1,vector<vector<int64_t>>(K+1,vector<int64_t>(N+1)));
  vector<vector<vector<int64_t>>> tr(K+1,vector<vector<int64_t>>(K+1,vector<int64_t>(N+1)));
  dp[0][0][0]=1;
  for(int i=0;i<N;i++){
    for(int j=0;j<=K;j++){
      yr[j][j][i]=dp[j][j][i];
      tr[K-j][0][i]=dp[K-j][0][i];
      for(int k=j;k<K;k++){
        yr[k+1][j][i]=(yr[k][j][i]+dp[k+1][j][i])%Q;
        tr[K-j][k+1-j][i]=(tr[K-j][k-j][i]+dp[K-j][k+1-j][i])%Q;
      }
    }
    int B=p[i];
    for(int j=0;j<=K;j++){
      for(int k=0;k<=j;k++){
        int64_t X=0,Y=0;
        if(k-B-1>=0){
          X=tr[j][k-B-1][i];
        }
        if(j-A+B-1>=0){
          Y=yr[j-A+B-1][k][i];
        }
        dp[j][k][i+1]=(tr[j][k][i]+yr[j][k][i]-dp[j][k][i]-X-Y+3*Q)%Q;
      }
    }
  }
  int64_t Z=0;
  for(int j=0;j<=K;j++){
    for(int i=j;i<=min(K,j+a);i++){
      Z+=dp[i][j][N];
      Z%=Q;
    }
  }
  cout<<Z<<endl;
}

