const int maxN = 305;
int dp[maxN][maxN][maxN];
int add_delta[maxN][maxN][maxN];
string s;
int K;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
//    freopen("input.txt", "r", stdin);
    cin >> s >> K;
    K = min(K, (int)s.size() + 1);
    vector < int > sizes;
    vector < int > zeros;
    zeros.emplace_back(-1);
    for (int i = 0; i < s.size(); i++) {
        if (s[i] == '0') zeros.emplace_back(i);
    }
    int ones = s.size() - zeros.size() + 1;
    zeros.emplace_back(s.size());
    for (int i = 0; i + 1 < zeros.size(); i++) {
        sizes.emplace_back(zeros[i + 1] - zeros[i] - 1);
    }
    dp[0][0][0] = 1;
    int n = sizes.size();
    vector < int > suf(n);
    suf[n - 1] = sizes[n - 1];
    for (int i = n - 2; i >= 0; i--) {
        suf[i] = suf[i + 1] + sizes[i];
    }
    for (int pos = 0; pos < n; pos++) {
        for (int val = 0; val <= K; val++) {
            int cur_d = 0;
            for (int need = 0; need <= ones; need++) {
                cur_d = sum(cur_d, add_delta[pos][need][val]);
                dp[pos][need][val] = sum(dp[pos][need][val], cur_d);
                if (dp[pos][need][val] == 0) continue;
                int c = sizes[pos];
                for (int will = max(c - need, 0); will <= c; will++) {
                    dp[pos + 1][need - (c - will)][val + c - will] = sum(
                        dp[pos + 1][need - (c - will)][val + c - will], dp[pos][need][val]);
                }
                add_delta[pos + 1][need + 1][val] = sum(add_delta[pos + 1][need + 1][val], dp[pos][need][val]);
            }
        }
    }
    int ans = 0;
    for (int i = 0; i <= K; i++) {
        ans = sum(ans, dp[n][0][i]);
    }
    cout << ans;
    return 0;
}

