signed main()
{
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    string s;
    cin >> s >> k;
    n = s.size();
    int len = 0;
    dp[0][0] = 1;
    for (int i = n - 1; i >= 0; i--)
    {
        if (s[i] == '1')
        {
            len++;
            continue;
        }
        for (int e = 0; e <= n; e++)
            for (int j = n; j >= 0; j--)
                dp1[e][j] = (dp1[e][j + 1] + dp[e][j]) % mod;
        for (int e = 0; e <= 2 * n; e++)
            for (int j = 0; j <= n; j++)
        {
                dp2[e][j] = ((j ? dp2[e][j - 1] : 0) + dp[e + j][j]) % mod;
                if (j - len - 1 >= 0)
                    dp2[e][j] = (dp2[e][j] - dp[e + (j - len - 1)][j - len - 1] + mod) % mod;
        }
        for (int e = 0; e <= n; e++)
            for (int j = 0; j <= n; j++)
        {
            dp[e][j] = (dp1[e][j] + dp2[e - j][j] - dp[e][j] + mod) % mod;
