const int mod = 998244353;
int add(int a, int b) {
    if (a + b >= mod)
        return a + b - mod;
    return a + b;
}

void incr(int& a, int b) {
    a = add(a, b);
}

int main() {
    std::iostream::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    // code here
    string s;
    cin >> s;
    int lim = input<int>();
    int n = SZ(s);

    dp[0][0][0][0] = 1;

    for (int i = 0; i < n; ++i) for (int act = 0; act <= n; ++act) for (int rent = 0; rent <= n; ++rent)
        for (int kekflag = 0; kekflag < 2; ++kekflag) {
            if (s[i] == '0') {
                incr(dp[i + 1][act][rent][0], dp[i][act][rent][kekflag]); // write 0
                if (kekflag == 0)
                    incr(dp[i][act + 1][rent + 1][0], dp[i][act][rent][kekflag]); // write 1^+ 0
            } else {
                if (kekflag == 0)
                    incr(dp[i + 1][act][rent][0], dp[i][act][rent][kekflag]); // write 1

                if (rent)
                    incr(dp[i + 1][act][rent - 1][1], dp[i][act][rent][kekflag]); // don't write (planing to write "0" next, then)
            }
        }

    int ans = 0;
    for (int i = 0; i <= min(max_n - 1, lim); ++i)
        for (int t = 0; t < 2; ++t)
            ans = add(ans, dp[SZ(s)][i][0][t]);

    cout << ans << "\n";

    return 0;
}

