            dp[(i + 1) & 1][j][k + 1][0] += cur;
            if (k + m - (used + a[i]) + 1 <= m) dp[(i + 1) & 1][j][k + m - (used + a[i]) + 1][0] -= cur;
          }
        }
        if (j + max(used + a[i] - m, 0) <= k) {
          dp[(i + 1) & 1][j + max(used + a[i] - m, 0)][k][1] += cur;
          if (j + a[i] + 1 <= k) dp[(i + 1) & 1][j + a[i] + 1][k][1] -= cur;
        }
      }
      // REP(j, m + 1) REP(k, m + 1) cout << dp[i & 1][j][k][0] + dp[i & 1][j][k][1] << " \n"[k == m];
      // cout << '\n';
      REP(j, m + 1) REP(k, m + 1) {
        dp[i & 1][j][k][0] = dp[i & 1][j][k][1] = 0;
      }
      prev += a[i];
    }
  }
  ModInt ans = 0;
  for (int j = 0; j <= K && j <= m; ++j) {
    ans += dp[n & 1][j][j][0] + dp[n & 1][j][j][1];
  }
  cout << ans << '\n';
  return 0;
}

