template<int MOD>
struct Modular {
  int value;
  Modular(const Modular& k) : value(k.value) {}

  template<typename V>
  Modular(const V& v) : value(v % MOD) {
    if (value < 0) {
      value += MOD;
    }
  }

  Modular() : Modular(0) {}

  Modular& operator+=(Modular const& b) { value += b.value; if (value >= MOD) value -= MOD; return *this; } 
  Modular& operator-=(Modular const& b) { value -= b.value; if (value < 0) value += MOD; return *this; }
  Modular& operator*=(Modular const& b) { value = (long long)value * b.value % MOD; return *this; }
  Modular& operator++() { return *this += 1; }
  Modular& operator--() { return *this -= 1; }
  Modular operator++(int) { return *this += 1; }
  Modular operator--(int) { return *this -= 1; }

  friend Modular inverse(Modular a) { return mexp(a, MOD - 2); }
  Modular& operator/=(Modular const& b) { return *this *= inverse(b); }
  friend Modular operator+(Modular a, Modular const b) { return a += b; }
  friend Modular operator-(Modular a, Modular const b) { return a -= b; }
  friend Modular operator-(Modular const a) { return 0 - a; }
  friend Modular operator*(Modular a, Modular const b) { return a *= b; }
  friend Modular operator/(Modular a, Modular const b) { return a /= b; }
  friend std::ostream& operator<<(std::ostream& os, Modular const& a) { return os << a.value; }
  friend bool operator==(Modular const& a, Modular const& b) { return a.value == b.value; }
  friend bool operator!=(Modular const& a, Modular const& b) { return a.value != b.value; }
};

using Mint = Modular<998244353>;

Mint dp[N][N][N][2];

template <int T, typename V>
Modular<T> mexp(Modular<T> a, V e) {
  if (a == 0) return e == 0 ? 1 : 0; 
  Modular<T> res = 1; 
  while (e) { 
    if (e & 1) 
      res *= a; 
    a *= a; 
    e >>= 1; 
  }
  return res;
}

void Run() {
  string s;
  int k;
  cin >> s >> k;
  const int n = s.size();
  k = min(k, n);
  vector<int> buckets;
  int nz = n;
  for (int i = n - 1; i >= 0; --i) {
    if (s[i] == '0') {
      buckets.push_back(nz - i - 1);
      nz = i;
    }
  }
  buckets.push_back(nz);
  reverse(buckets.begin(), buckets.end());
  const int b = buckets.size();
  for (int i = k; i >= 0; --i)
    dp[b][i][i][0] = dp[b][i][i][1] = 1;
  for (int i = b - 1; i >= 0; --i) {
    for (int moves = k; moves >= 0; --moves) {
      for (int rep = k; rep >= 0; --rep) {
        for (int take = 1; take <= min(buckets[i], moves - rep); ++take)
          dp[i][moves][rep][0] += dp[i + 1][moves][rep + take][0]; // replacement.
        dp[i][moves][rep][0] += dp[i][moves + 1][rep][1]; // make move
        dp[i][moves][rep][0] += dp[i + 1][moves][rep][0]; // dont make move
        dp[i][moves][rep][1] += dp[i][moves + 1][rep][1]; // make another move
        dp[i][moves][rep][1] += dp[i + 1][moves][rep][0]; // done making moves
      }
    }
  }
  cout << dp[0][0][0][0] << '\n';
}

int main() {
  srand(time(0));
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  Run();
  return 0;
}

