vector<pair<char, ll>> run_length_encoding(const string &s) {
    vector<pair<char, ll>> ans;
    ll num = 1;
    rep(i, s.length()-1) {
        if (s[i] == s[i + 1]) {
            num++;
        }
        else {
            ans.emplace_back(mp(s[i], num));
            num = 1;
        }
    }
    ans.emplace_back(mp(s.back(), num));
    return ans;
}


