		vector<vector<ll>> pref(k + 1);
		for (int j = 0; j <= k; j++) {
			pref[j].push_back(0);
			for (int t = 0; t <= k; t++) pref[j].push_back(pref[j].back() + dp[ind - 1][j][t]);
