const int MAX = 305;

int N, K;
vector<int> A;
vector<int> suffix_sum;
mod_int dp[MAX][MAX][MAX];

mod_int recurse(int index, int borrow, int cost) {
    if (borrow < 0 || borrow > suffix_sum[index] || cost > K)
        return 0;

    if (index == N)
        return borrow == 0 ? 1 : 0;

    mod_int &ans = dp[index][borrow][cost];

    if (ans.val >= 0)
        return ans;

    ans = 0;

    for (int end = 0; end <= suffix_sum[index]; end++)
        if (end < A[index]) {
            int take = A[index] - end;
            ans += recurse(index + 1, borrow - take, cost);
        } else {
            int extra = end - A[index];
            ans += recurse(index + 1, borrow + extra, cost + extra);
        }

    return ans;
}

mod_int solve() {
    N = int(A.size());
    suffix_sum.assign(N + 1, 0);

    for (int i = N - 1; i >= 0; i--)
        suffix_sum[i] = suffix_sum[i + 1] + A[i];

    memset(dp, -1, sizeof(dp));
    return recurse(0, 0, 0);
}

