int solve() {
	std::string s; ll K;
	std::cin >> s >> K;

	K = min(K, ll(s.size()));
	vector<ll> a;
	REPD (i, 0, s.length()) if (s[i] == '0') a.emplace_back(i);
	a.emplace_back(s.length());

	ll n = a.size() - 1;
	auto dp = make_multiple_vector<2, rll>(K + 1, K + 1);
	dp[0][0] = 1;
	for (ll i = n-1; i >= 0; i--) {
		auto swp = make_multiple_vector<2, rll>(K + 1, K + 1);
		for (ll j = 0; j <= K; j++) for (ll k=0; k<=K; k++) {
			for (ll nj = 0; nj <= j + a[i+1] - a[i] - 1; nj++) {
				ll nk = k + std::max(ll{0}, nj - j);
				if (nj<=K && nk<=K) swp.at(nj).at(nk) += dp.at(j).at(k);
			}
		}
		swp.swap(dp);
	}

	rll ans = 0;
	for (auto&& v: dp) for (rll& x: v) ans += x;
	RET(ans);

	return 0;
}

