void chemthan() {
    string s; cin >> s;
    int k; cin >> k;
    int n = sz(s);
    chkmin(k, n + 5);
    int cnt = 0;
    vi vals;
    FOR(i, 0, n) {
        if (s[i] == '0') {
            vals.pb(cnt);
            cnt = 0;
        }
        else {
            cnt++;
        }
    }
    vals.pb(cnt);
    auto a = vals;
    FOR(i, 1, sz(vals)) vals[i] += vals[i - 1];
    int d = sz(vals);
    vector<vector<vi>> dp(d + 1, vector<vi>(n + 1, vi(k + k + 1)));
    dp[0][0][0] = 1;
    FOR(i, 0, d) {
        FOR(s, 0, n + 1) FOR(t, 0, k + k + 1) if (dp[i][s][t]) {
            FOR(l, max(0, vals[i] - s), n + 1) {
                if (n < s + l) break;
                if (k + k < t + abs(l - a[i])) break;
                addmod(dp[i + 1][s + l][t + abs(l - a[i])], dp[i][s][t]);
            }
        }
    }
    int res = 0;
    FOR(i, 0, k + k + 1) {
        addmod(res, dp[d][vals.back()][i]);
    }
    cout << res << "\n";
}

