int main() {
	string S;
	long long K;
	cin >> S >> K;
	vector<int> V = { 0 };
	for (int i = 0; i < S.size(); i++) {
		if (S[i] == '0') V.push_back(0);
		else V[V.size() - 1]++;
	}
	int A = V.size(), B = S.size() - A + 1, N = S.size();
	vector<vector<vector<long long> > > DP(A + 1, vector<vector<long long> >(B + 1, vector<long long>(B + 1, 0)));
	DP[0][0][0] = 1;
	for (int i = 0; i < A; i++) {
		for (int j = 0; j <= B; j++) {
			long long NOW = 0;
			for (int k = 0; k <= B - j; k++) {
				NOW += DP[i][j + k][k];
				NOW %= MOD;
				DP[i + 1][j + k][k] = NOW;
			}
			NOW = 0;
			for (int k = 0; k <= B - j; k++) {
				NOW += DP[i][k][j + k];
				NOW %= MOD;
				DP[i + 1][k][j + k];
			}
		}
		for (int j = 0; j <= B; j++) {
			vector<long long> Cur(B + 2, 0);
			for (int k = B; k >= 0; k--) {
				Cur[k] = (Cur[k + 1] + DP[i][j][k]) % MOD;
				DP[i + 1][j][k] += (Cur[k + 1] - (Cur[min(B + 1, k + 1 + V[i])] % MOD) + MOD) % MOD;
				DP[i + 1][j][k] %= MOD;
			}
		}
		/*
		for (int j = 0; j <= B; j++) {
			for (int k = 0; k <= B; k++) {
