			}
			cout << endl;
		}
		cout << endl;
		*/
	}
	long long ANS = 0;
	for (int i = 0; i <= K && i <= B; i++) {
		ANS += DP[A][i][0];
		ANS %= MOD;
	}
	cout << ANS << endl;
}

