const int mod = 998244353;
const int MAXN = 303;
vector<int> dp[MAXN][MAXN];
vector<int> cnt;
int k, n;
LL get(int i, int pre, int rem) {
  if (dp[i][pre].empty()) {
    dp[i][pre] = vector<int>(k+1, -1);
  }
  if (dp[i][pre][rem] != -1) {
    return dp[i][pre][rem];
  }
  int tmp = min(cnt[i], pre);
  if (i == n-1) {
    int tmp2 = max(cnt[i] - (cnt[i-1] - pre) - rem, 0);
    dp[i][pre][rem] = tmp - tmp2 + 1;
    return dp[i][pre][rem];
  }
  int used = cnt[i-1] - pre;
  used -= cnt[i] - tmp;
  int u = rem;
  dp[i][pre][rem] = 0;
  for (; tmp >= 0 && u >= 0; tmp--) {
    dp[i][pre][rem] = (dp[i][pre][rem] + get(i+1, tmp, u)) % mod;
    if (used > 0) used--;
    else u--;
  }
  return dp[i][pre][rem];
}




