  mint(long long x = 0) noexcept : x((x + MOD) % MOD) {}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= MOD) x -= MOD;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x -= a.x) < 0) x += MOD;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= MOD;
    return *this;
  }
  mint operator+(const mint a) const { return mint(*this) += a; }
  mint operator-(const mint a) const { return mint(*this) -= a; }
  mint operator*(const mint a) const { return mint(*this) *= a; }
  mint pow(long long t) const {
    if (t == 0) return 1;
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(MOD - 2); }
  mint& operator/=(const mint a) { return (*this) *= a.inv(); }
  mint operator/(const mint a) const { return mint(*this) /= a; }
};

int main(){
  string S; cin >> S;
  int N = S.size();
  int K; cin >> K;
  vector<int> vec(N, 0);
  vector<int> mx;
  int cnt = 0;
  int num1 = 0;
  rep(i, N) {
    if (S[i] == '0') cnt++;
    else {
      vec[cnt]++;
      mx.push_back(cnt);
      num1++;
    }
  }
  K = min(K, num1);
  reverse(mx.begin(), mx.end());

  map<long long, mint> mp;
  mp[enc(0, mx[0] + 1, 0, 1)] = 1;

  auto it = mp.begin();
  while (it != mp.end()) {
    long long nown = (*it).first;
    vector<long long> nvec = dec(nown);
    long long n = nvec[3], c = nvec[2], u = nvec[1], k = nvec[0];
    mint now = mp[nown];
    rep(i, c + 1) {
      if (mx[n] < i) break;
      if (i == c) {
        if (vec[c] > k) mp[enc(n + 1, c, u, k + 1)] += now;
        else if (K > u) mp[enc(n + 1, c, u + 1, k)] += now;
      } else {
        if (vec[i] > 0) mp[enc(n + 1, i, u, 1)] += now;
        else if (K > u) mp[enc(n + 1, i, u + 1, 1)] += now;
      }
    }
    it = mp.find(nown);
    it++;
  }

  mint ans = 0;
  rep(c, N) rep(u, K + 1) rep1(k, N) {
    if (mp.count(enc(num1,c,u,k)) > 0) ans += mp[enc(num1,c,u,k)];
  }

  cout << ans.x << endl;
}

