class Solver {
 public:
  string s;
  int ub, l;
  Solver(string s, LL k) : s(s), ub(k), l(s.length()){};

  void solve() {
    vector<int> seq(1);
    int c0 = 0, c1 = 0;
    for (int i = 0; i < l; ++i) {
      if (s[i] == '0') {
        c0++;
        seq.push_back(0);
      } else {
        c1++;
        seq.back()++;
      }
    }
    vector<vector<Modint<>>> dp(400, vector<Modint<>>(400));
    ub = min(350, ub);
    dp[0][0] = Modint<>(1);
    int sum = 0;
    for (int i = 0; i < (int)seq.size(); ++i) {
      sum += seq[i];
      vector<vector<Modint<>>> dp2(400, vector<Modint<>>(400));
      vector<vector<Modint<>>> dp3(400, vector<Modint<>>(400));
      vector<vector<Modint<>>> dp4(400, vector<Modint<>>(400));
      for (int j = 0; j <= c1; ++j) {
        for (int k = 0; k <= ub; ++k) {
          int U = min(l - j, seq[i] + ub - k);
          int L = max(0, sum - j);
          if (L < seq[i]) {
            if (seq[i] < U) {
              dp2[j + L][k] += dp[j][k];
              dp2[j + seq[i]][k] -= dp[j][k];
              dp3[j + seq[i]][k] += dp[j][k];
              dp3[j + U + 1][k + U + 1 - seq[i]] -= dp[j][k];
            } else {
              dp2[j + L][k] += dp[j][k];
              dp2[j + U + 1][k] -= dp[j][k];
            }
          } else {
            dp3[j + L][k + L - seq[i]] += dp[j][k];
            dp3[j + U + 1][k + U + 1 - seq[i]] -= dp[j][k];
          }
        }
      }
      for (int j = 0; j <= c1; ++j) {
        for (int k = 0; k <= ub; ++k) {
          if (j > 0) dp2[j][k] += dp2[j - 1][k];
          if (j > 0 && k > 0) dp3[j][k] += dp3[j - 1][k - 1];
        }
      }
      for (int j = 0; j <= c1; ++j) {
        for (int k = 0; k <= ub; ++k) {
          dp4[j][k] = dp2[j][k] + dp3[j][k];
        }
      }
      swap(dp, dp4);
    }
    Modint<> ans(0);
    for (int k = 0; k <= ub; ++k) {
      ans += dp[c1][k];
    }
    cout << ans << endl;
  }
};  // namespace Problem

