typedef Field<998244353> anstype;

const int MAXN = 303;

string s;

VI a;
anstype dp[MAXN][MAXN][MAXN];
bool was[MAXN][MAXN][MAXN];

int k;

anstype solve(int pos, int used, int picked) {
    if (used > k)
        return 0;

    if (pos < 0) {
        if (picked == 0)
            return 1;
        return 0;
    }

    auto &cdp = dp[pos][used][picked];
    if (was[pos][used][picked])
        return cdp;

    was[pos][used][picked] = true;

    // pick
    for(int i = 1; i<=a[pos];++i) {
        cdp += solve(pos-1, used+i, picked+i);
    }

    // put
    for(int i = 0; i<=picked; ++i) {
        cdp += solve(pos-1, used, picked-i);
    }

    return cdp;
}

class CShift {
public:
    void solve(std::istream& in, std::ostream& out) {
        // fastIO();
        in >> s >> k;
        s += '0';
        int cur = 0;
        a.clear();
        FILL(dp, 0);
        FILL(was, false);

        for(auto v: s) {
            if (v == '0') {
                a.pb(cur);
                cur = 0;
            } else {
                ++cur;
            }
        }

        out << ::solve(a.size()-1, 0, 0) << endl;
    }
};


