template <int mod>
struct ModInt {
    int x;

    ModInt() : x(0) {}

    ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

    ModInt &operator+=(const ModInt &p) {
        if((x += p.x) >= mod)
            x -= mod;
        return *this;
    }

    ModInt &operator-=(const ModInt &p) {
        if((x += mod - p.x) >= mod)
            x -= mod;
        return *this;
    }

    ModInt &operator*=(const ModInt &p) {
        x = (int)(1LL * x * p.x % mod);
        return *this;
    }

    ModInt &operator/=(const ModInt &p) {
        *this *= p.inverse();
        return *this;
    }

    ModInt operator-() const { return ModInt(-x); }

    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

    bool operator==(const ModInt &p) const { return x == p.x; }

    bool operator!=(const ModInt &p) const { return x != p.x; }

    ModInt inverse() const {
        int a = x, b = mod, u = 1, v = 0, t;
        while(b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }

    ModInt pow(int64_t n) const {
        ModInt ret(1), mul(x);
        while(n > 0) {
            if(n & 1)
                ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }

    friend ostream &operator<<(ostream &os, const ModInt &p) {
        return os << p.x;
    }

    friend istream &operator>>(istream &is, ModInt &a) {
        int64_t t;
        is >> t;
        a = ModInt<mod>(t);
        return (is);
    }

    static int get_mod() { return mod; }
};

using mint = ModInt<MOD>;

mint dp[310][310][310]; //dp[i][j][k]:後ろからi番目の区間までに、j回操作して、k個増やすのにつかえる場合の数

void solve() {
    string s;
    ll k;
    cin >> s >> k;

    Array a;
    ll n = s.size();
    int con = 0;
    int sum = 0;
    REP(i, n) {
        if(s[i] == '1') {
            con++;
            sum++;
        } else {
            a.push_back(con);
            con = 0;
        }
    }

    if(con > 0) {
        a.push_back(con);
    }
    reverse(all(a));

    ll m = a.size();

    dp[0][0][0] = 1;

    REP(i, m) {
        REP(j, 310) {
            REP(l, 310) {
                if(dp[i][j][l] == 0)
                    continue;
                REP(r, 310) {
                    //r個になるように操作した場合
                    if(l + a[i] - r < 0)
                        break;
                    dp[i + 1][j + max(0LL, a[i] - r)][l + a[i] - r] += dp[i][j][l]; //減らす分だけ操作回数を増やす
                }
            }
        }
    }

    mint ans = 0;
    REP(i, min(k + 1, 310LL)) {
        ans += dp[m][i][0];
    }
    cout << ans << en;
}

