    vector<int>b;
    int m = a.size();
    b.resize(m);
    for(int i=0;i<m;i++){
        b[i] += a[i];
        if(i!=0)b[i] += b[i-1];
    }
    int sm = b[m-1];
    dp[0][0] = 1;
    rep(i,m){
        int pa = 0;
        if(i!=0)pa = b[i-1];
        for(int j = pa;j<=sm;j++){// imamade sum : j
            for(int k = j-pa;k<=j;k++){// diff sum : k
                for(int x = max(0,b[i]-j);x<=sm-j;x++){// x add
                    int nxt1 = j + x;
                    int diff = max(0,x-a[i]);
                    if(k+diff>K||k+diff>=301)break;
                    dp2[nxt1][k+diff] += dp[j][k];
                }
            }
        }
        for(int j=b[i];j<=sm;j++){
            for(int k=j-b[i];k<=j;k++){
                dp[j][k] = dp2[j][k];
                dp2[j][k] = 0;
            }
        }
    }
    mod res = 0;
    for(int k=0;k<=K;k++){
        res += dp[sm][k];
    }
    cout << res << "\n";
    return 0;
}

