const int N = 301;

int n, k, dp[N][N][N], mod = 998244353;
string s;

int solve(int idx, int i, int skipped, int t){
    if(t > k) return 0;
    if(idx == n) return skipped == 0;
    int &ret = dp[idx][skipped][t];
    if(ret != -1) return ret;
    ret = 0;
    // 0
    int j = i;
    while(j >= 0 && s[j] != '0') j--;
    if(j != -1){
        int sp = i - j;
        ret += solve(idx + 1, j - 1, skipped + sp, t + sp);
        if(ret >= mod) ret -= mod;
    }
    // 1
    if(s[i] == '1') ret += solve(idx + 1, i - 1, skipped, t);
    else if(skipped > 0) ret += solve(idx + 1, i, skipped - 1, t);
    if(ret >= mod) ret -= mod;
    return ret;
}
