const ll mod = 998244353;

string s;
ll K, dp[305][605][305]; // groups, moves, carry
ll N, sz[305];

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cin >> s >> K;

	int gn = 1, gz = 0;
	N = s.size();
	K = min(K,N);
	reverse(s.begin(),s.end());

	for (int i = 0; i < s.size(); ++i){
		if (s[i] == '0'){
			sz[gn] = gz;
			gz = 0;
			gn++;
		}
		else gz++;
	}
	sz[gn] = gz;
	/*
	for (int i = 1; i <= gn; ++i){
		cout << sz[i] << ' ';
	}
	cout << '\n';
	*/
	dp[0][0][0] = 1;
	for (ll i = 1; i <= gn; ++i){
		for (ll k = 0; k <= K; ++k){
			for (ll c = 0; c <= k; ++c){
				for (ll l = 0; (c+l) <= N; ++l){
					dp[i][k][c] += dp[i-1][k][c+l];
					dp[i][k][c] %= mod;
				}
				for (ll l = 1; l <= min(sz[i],k); ++l){
					dp[i][k][c] += dp[i-1][k-l][c-l];
					dp[i][k][c] %= mod;
				}
				//cout << i << ' ' << k << ' ' << c << ' ' << dp[i][k][c] << '\n';
			}
		}
	}
	ll ans = 0;
	for (int i = 0; i <= K; ++i){
		ans += dp[gn][i][0];
		ans %= mod;
	}
	cout << ans << '\n';

}

