const int maxn = 305;
char tmp[maxn];
int n, k;
string s;

bool read() {
  if (scanf("%s%d", tmp, &k) < 2) {
    return false;
  }
  s = tmp;
  return true;
}

int bal[maxn];
int a[maxn];
int nxt[maxn];
int dp[maxn][maxn][maxn];

void solve() {
  {
    n = 0;
    int cur = 0;
    for (int i = 0; i < sz(s); i++) {
      bal[i] = cur;
      if (s[i] == '0') {
        cur++;
      } else {
        a[n++] = cur;
      }
    }
  }
  nxt[sz(s) - 1] = sz(s);
  for (int i = sz(s) - 2; i >= 0; i--) {
    if (s[i + 1] == '0') {
      nxt[i] = i + 1;
    } else {
      nxt[i] = nxt[i + 1];
    }
  }
  memset(dp, 0, sizeof(dp));
  dp[0][0][0] = 1;
  for (int i = 0; i <= n; i++) {
    for (int j = 0; j < sz(s); j++) {
      for (int k = 0; k <= i; k++) {
        auto cur = dp[i][j][k];
        if (!cur) {
          continue;
        }
        if (s[j] == '0') {
          add(dp[i][j + 1][k], cur);
          if (bal[j] <= a[i]) {
            add(dp[i + 1][j][k + 1], cur);
          }
        } else {
          add(dp[i][min(nxt[j] + 1, sz(s))][k], cur);
          if (bal[j] <= a[i]) {
            add(dp[i + 1][j + 1][k], cur);
          }
        }
      }
    }
  }
  int res = 0;
  for (int i = 0; i <= min(n, k); i++) {
    add(res, dp[n][sz(s)][i]);
  }
  printf("%d\n", res);
}

