const ll maxn = 310;

ll n, m, K, A[maxn];
string S;
ll dp[maxn][maxn][maxn];

/*
    partition string by zeros and start from end
    dp[i][j][k] first i parts, use k operations and remove j ones for next parts
    dp update in both directions
    dp[i][j][k] -> dp[i + 1][j + t][k + t] (remove t ones from i+1 's part) 1 < t < A[i + 1]
    dp[i][j][k] <- dp[i - 1][j + t][k] (add some ones from prev parts) 0 <= t <= inf
   */

int main() {
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);

    cin >> S >> K;
    n = S.size();
    reverse(all(S));
    ll i = 0;
    while (i < n) {
        ll j = i;
        while (j < n && S[j] == '1') ++j;
        A[m++] = j - i;
        i = j + 1;
    }
    if (S.back() == '0') A[m++];

    smin(K, n);

    dp[0][0][0] = 1;
    forifrom (i, 1, m + 1) {
        fori (k, K + 1) {
            forir (j, n + 1) {
                dp[i][k][j] = (dp[i][k][j + 1] + dp[i - 1][k][j]) % MOD;
            }
        }
        forifrom (t, 1, A[i - 1] + 1) {
            fori (k, K - t + 1) {
                fori (j, n - t + 1) {
                    Add(dp[i][k + t][j + t], dp[i - 1][k][j]);
                }
            }
        }
    }

    ll ans = 0;
    fori (i, K + 1) Add(ans, dp[m][i][0]);
    cout << ans << '\n';

}

