int dp[305][305][305][2];
vector<int> vp;
int solve(int idx, int cnt, int lft, bool take){
  if(idx == vp.size())
    return (cnt == 0);
  int &ret = dp[idx][cnt][lft][take];
  if(~ret)
    return ret;
  ///take
  ret = 0;
  if(!take){
    for(int j = 1; j <= vp[idx] && j <= lft; j++){
        ret += solve(idx + 1, cnt + j, lft - j, 0);
        if(ret >= MOD)
          ret -= MOD;
    }
  }
  ret += solve(idx + 1, cnt, lft, 0);
  if(ret >= MOD)ret -= MOD;
  if(cnt)
    ret += solve(idx, cnt - 1, lft, 1);
  if(ret >= MOD)ret -= MOD;

  return ret;
}
