				for(int k = 0; k <= K; k++)
					if(k >= j)
						dp[i][j][k] = 1;
			rem_balance += cnt1[i];
			continue;
		}
		if(cnt1[i] == 0){
			for(int j = 0; j <= rem_balance; j++){
				for(int k = 0; k <= K; k++){
					if(k < j) continue;
					int take = min(rem_balance, K - k);
					for(int l = 0; l <= take; l++)
						dp[i][j][k] = add(dp[i][j][k], dp[i + 1][j + l][k + l]);
				}
			}
			continue;
		}
		for(int j = 0; j <= cnt1[i] + rem_balance; j++){
			for(int k = 0; k <= K; k++){
				if(k < j) continue;
				int take = min(rem_balance, K - k);
				for(int l = 0; l <= take; l++)
					dp[i][j][k] = add(dp[i][j][k], dp[i + 1][j + l][k + l]);
				int give = min(j, cnt1[i]);
				for(int l = 0; l <= give; l++)
					dp[i][j][k] = add(dp[i][j][k], dp[i + 1][j - l][k]);
				dp[i][j][k] = sub(dp[i][j][k], dp[i + 1][j][k]);
			}
		}
		rem_balance += cnt1[i];
	}
	int ans = 0;
	if(n <= 1)
		ans = 1;
	else
		ans = dp[0][0][0];
	cout << ans << endl;
}

