int f(int x, int use, int sum) {
  if (use > k) return 0;
  if (x < 0) return sum == 0;
  if (~dp[x][use][sum]) return dp[x][use][sum];

  int ret = f(x-1, use, sum);
  for (int i = 1; i <= ones[x]; ++i) {
    ret = (ret + f(x-1, use + i, sum + i)) % MOD;
