#include <bits/stdc++.h>


using namespace std;


const int MOD = 998244353;
const int N = 303;

int dp[N][N][N];


int solve(int n, string &s, int k) {
    int lastZero = -1;

    for (int moves = 0; moves <= k; moves++) {
        for (int ones = 0; ones <= n; ones++) {
            dp[0][moves][ones] = 1;
        }
    }

    for (int pref = 1; pref <= n; pref++) {
        for (int moves = 0; moves <= k; moves++) {
            for (int ones = 0; ones <= n; ones++) {
                long long dpHere = 0;

                int last = s[pref - 1] - '0';

                for (int target = 0; target <= 1; target++) {
                    if (last == target) {
                        dpHere += dp[pref-1][moves][ones];
                    } else if (last == 0) {
                        if (ones >= 1) {
                            dpHere += dp[pref][moves][ones-1];
                        }
                    } else {
                        if (lastZero != -1) {
                            int needMoves = pref - lastZero - 1;

                            if (moves >= needMoves) {
                                dpHere += dp[lastZero][moves-needMoves][ones+needMoves];
                            }
                        }
                    }
                }

                dp[pref][moves][ones] = dpHere % MOD;
            }
        }

        if (s[pref - 1] == '0') {
            lastZero = pref - 1;
        }
    }

    return dp[n][k][0];
}

