	cin >> S >> K;

	chmin(K, S.size());

	reverse(ALL(S));

	vector<int> ppos[2], sum[2];
	REP(i, 2) {
		ppos[i] = vector<int>(S.size(), INF); // 0-indexed
		sum[i] = vector<int>(S.size() + 1, INF); // 1-indexed
	}

	REP(i, S.size()) ppos[S[i] == '1'][i] = i;
	REP(j, 2) for(int i = S.size() - 2; i >= 0; --i) chmin(ppos[j][i], ppos[j][i + 1]);

	REP(i, S.size()) sum[S[i] == '1'][i + 1]++;
	REP(j, 2) REP(i, S.size()) sum[j][i + 1] += sum[j][i];

	vector<vector<vector<mint>>> dp(S.size() + 1, vector<vector<mint>>(S.size() + 1, vector<mint>(S.size() + 1))); // [i][j][k] := 長さ i で j 回使える, 合計 k 回飛ばしたときのユニーク数

	dp[0][0][0] = 1;
	REP(i, S.size()) REP(j, S.size()) REP(k, K + 1) {
		int p = i + j;
		if (p >= S.size()) continue;
		if (dp[i][j][k] == 0) continue;

		int pos = ppos[0][p];


		if (pos < INF) {
			int plus = sum[1][pos + 1] - sum[1][p] - 1;
			if (k + plus <= K) dp[i + 1][j + plus][k] += dp[i][j][k];
		}

		pos = ppos[1][p];
		if (pos < INF) {
			if (pos == p) dp[i + 1][j][k] += dp[i][j][k];
			else if (j > 0) dp[i + 1][j - 1][k] += dp[i][j][k];
		}
	}

	mint ans = 0;
	REP(i, K + 1) ans += dp[S.size()][0][i];
	cout << ans << endl;
	return 0;
}

