                    (dp[i][j][l] += dp[i + 1][j - r][l - r]) %= mod;
                }
            }
        }
    }
    ll ans = 0;
    for(i=0;i<=min(300,k);i++){
        (ans += dp[0][0][i]) %= mod;
    }
