        for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
    }
    mint operator()(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n]*ifact[k]*ifact[n-k];
    }
};

int solve(){
    string s;
    ll k;
    cin>>s>>k;
    vector<pair<char, ll>> rl = run_length_encoding(s);
    ll n = s.length();
    k = min(n+1,k);
    dbg(rl);
    Vec v(n);
    ll id = 0;
    Each(p, rl){
        if(p.fi=='0'){
            id += p.se;
        } else{
            v[id] = p.se;
        }
    }

    reverse(ALL(v));
    dbg(v);

    vector<vector<Vmint>> dp (n+1,vector<Vmint>(n+1, Vmint(n+1,0)));
    dp[0][0][0] = 1;
    //i番目まででsub個引いてadd足した場合。
    rep(i,n){
        rep(sub,n+1){
            rep(add,n+1){
                //sub
                rep(cnt,v[i]+1){
                    if(sub+cnt>k)continue;
                    dp[i+1][sub+cnt][add] += dp[i][sub][add];
                }
                //add
                if(sub<add)continue;
                REP(cnt,1,n+1){
                    if(add+cnt>k)continue;
                    if(add+cnt>sub)continue;
                    dp[i+1][sub][add+cnt] += dp[i][sub][add];
                }
            }
        }
    }
    mint ans = 0;
   // dbg(dp);
    rep(i,k+1){
        ans += dp[n][i][i];
    }
    out(ans);
    return  0;
}

