using namespace std;
constexpr int64_t mod = 998244353;
template <uint32_t mod>
class modint{
    uint64_t value;
public:
    constexpr modint(const int64_t x=0) noexcept: value(x % mod + (x < 0 ? mod : 0)){ }
    constexpr explicit operator uint64_t() const noexcept{ return value; }
    constexpr modint inverse() const noexcept{ return pow(*this, mod-2); }
    constexpr bool operator==(const modint &rhs) const noexcept{ return value == rhs.value; }
    constexpr bool operator!=(const modint &rhs) const noexcept{ return value != rhs.value; }
    constexpr modint operator+() const noexcept{ return modint(*this); }
    constexpr modint operator-() const noexcept{ return modint(mod - value); }
    constexpr modint operator+(const modint &rhs) const noexcept{ return modint(*this) += rhs; }
    constexpr modint operator-(const modint &rhs) const noexcept{ return modint(*this) -= rhs; }
    constexpr modint operator*(const modint &rhs) const noexcept{ return modint(*this) *= rhs; }
    constexpr modint operator/(const modint &rhs) const noexcept{ return modint(*this) /= rhs; }
    constexpr modint &operator+=(const modint &rhs) noexcept{
        if((value += rhs.value) >= mod) value -= mod;
        return *this;
    }
    constexpr modint &operator-=(const modint &rhs) noexcept{ return *this += mod - rhs.value; }
    constexpr modint &operator*=(const modint &rhs) noexcept{
        if((value *= rhs.value) >= mod) value %= mod;
        return *this;
    }
    constexpr modint &operator/=(const modint &rhs) noexcept{ return *this *= rhs.inverse(); }
    constexpr modint operator++(int) noexcept{
        modint ret(*this);
        if((++value) >= mod) value -= mod;
        return ret;
    }
    constexpr modint operator--(int) noexcept{
        modint ret(*this);
        if((value += mod - 1) >= mod) value -= mod;
        return ret;
    }
    constexpr modint &operator++() noexcept{ return *this += 1; }
    constexpr modint &operator--() noexcept{ return *this -= 1; }
    friend std::ostream &operator<<(std::ostream &os, const modint<mod> &x){ return os << x.value; }
    friend std::istream &operator>>(std::istream &is, modint<mod> &x){
        int64_t i;
        is >> i;
        x = modint<mod>(i);
        return is;
    }
    friend constexpr modint<mod> pow(const modint<mod> &x, uint64_t y){
        modint<mod> ret{1}, m{x};
        while(y > 0){
            if(y & 1) ret *= m;
            m *= m;
            y >>= 1;
        }
        return ret;
    }
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    static modint<mod> fact[1001],finv[1001];
    fact[0] = 1;
    for(int i=1;i<=1000;++i) fact[i] = fact[i-1] * i;
    finv[1000] = fact[1000].inverse();
    for(int i=1000;i>0;--i) finv[i-1] = finv[i] * i;
    auto comb = [&](int n, int r)->modint<mod>{ return fact[n]*finv[r]*finv[n-r]; };

    string s;
    int kk;
    cin >> s >> kk;
    int cnt = 0, sum = 0;
    vector<int> x;
    for(char c:s){
        if(c == '0'){ x.push_back(cnt); cnt = 0; }
        else if(c == '1'){ ++cnt; ++sum; }
    }
    x.push_back(cnt);
    int n = x.size();

    static modint<mod> dp[301][301][301];
    dp[0][1][0] = 1;

    for(int i=1;i<n;++i){
        for(int j=1;j<=i+1;++j){
            for(int k=0;k<=sum;++k){
                dp[i][j][k] = dp[i-1][j-1][k];
                int aa = min(x[i], k);
                for(int a=1;a<=aa;++a){
                    dp[i][j][k] += dp[i-1][j][k-a] * comb(a+j-1, a);
                }
            }
        }
    }

    modint<mod> ans = 0;
    for(int j=1;j<=n;++j){
        for(int k=0;k<=min(kk,sum);++k){
            ans += dp[n-1][j][k];
        }
    }
    cout << ans << endl;    

    return 0;
}

