char s[305];
int len, n, K, a[305], f[305][305][305];
int main() {
	scanf("%s %d", s + 1, &K);
	len = strlen(s + 1);
	n = 0;
	for (int i = 1, lst = 0; i <= len + 1; i++) {
		if (i == len + 1 || s[i] == '0') {
			a[++n] = i - lst - 1;
			lst = i;
		}
	}
	reverse(a + 1, a + 1 + n);
