		for (int j = 0; j <= ps; j++) {
			for (int k = 0; k <= ps; k++) if (f[i - 1][j][k]) {
				for (int l = 0; l <= a[i]; l++) {
					Add(f[i][j + a[i] - l][k + a[i] - l], f[i - 1][j][k]);
