    K = min(K, n);
    long long dp[2][n+1][K+1];
    memset(dp, 0, sizeof dp);
    int cur = 0, prev = 1;
    for (int j = 0; j <= K; j++) {
        if (j <= K) dp[prev][j][j] = 1;
    }

    int i0 = 0;
    for (;;) {
        int i = i0+1;
        while (i < n && s[i] == '1') i++;
        if (i == n) break;
        for (int j = i; j <= n; j++) {
            for (int k = 0; k <= K; k++) {
                long long sum = 0;
                for (int j1 = max(i0, j - (i - i0) - k); j1 < j; j1++) {
                    int k1 = j - j1 - (i - i0);
                    assert (k >= max(0, k1));
                    sum += dp[prev][j1][k - max(0, k1)];
                }
                dp[cur][j][k] = (sum % M + M) % M;
            }
        }
        i0 = i;
        swap(prev, cur);
    }
    long long ans = accumulate(dp[prev][i0], dp[prev][n], 0LL);
    cout << (ans % M + M) % M << endl;
}

