			ll cnt = 0;
			for (int j = 0; j <= k; j++) {  // j + t -
				if (j < t) continue;

				dp[ind][j][t] += cnt + pref[j][t + 1] - pref[j][max(0ll, t - vec[i].first)];
				cnt += dp[ind - 1][j][t];
				cnt %= MOD;
				dp[ind][j][t] %= MOD;
				if (i == vec.size() - 1 && j == t && j <= k) sm += dp[ind][j][t];
				sm %= MOD;
				//cout << dp[ind][j][t] << " ";
			}
			//cout << "\n";
		}

		ind++;
		//cout << "-\n";
	}

	cout << sm;
	return 0;
}

