    else one++, sum++;
  }
  if (one > 0) d.push_back(one);
  n = d.size();
  for (ll i = 0; i <= n; i++) for (ll j = 0; j <= sum; j++) for (ll r = 0; r <= sum; r++) {
    memo1[i][j][r] = memo2[i][j][r] = -1;
  }
  dp[0][0][0] = 1;
  k = min(k, sum);
  for (ll i = 0; i < n; i++) {
    for (ll j = 0; j <= k; j++) {
      for (ll r = 0; r <= j; r++) {
        dp[i+1][j][r] = get1(i, j-1, r) + get2(i, j, r) - get2(i, j, max(0LL, r - d[i])-1) + mod;
        while (dp[i+1][j][r] >= mod) dp[i+1][j][r] -= mod;
        //printf("%lld (%lld %lld %lld) ", dp[i+1][j][r], get1(i, j-1, r) , get2(i, j, r) , get2(i, j, max(0LL, r - d[i])-1));
