int solve(int pos, int rem, int acc) {
  if (pos == n) {
    return acc == 0;
  }
  int& ret = dp[pos][rem][acc];
  if (ret >= 0) return ret;
  ret = 0;
  for (int k = 0; k <= a[pos] && k <= rem; ++k) {
    ret += solve(pos + 1, rem - k, acc + k);
    ret %= MOD;
  }
  for (int k = 1; k <= acc; ++k) {
    ret += solve(pos + 1, rem, acc - k);
    ret %= MOD;
  }
  return ret;
}

