                            dp[i+1][j+1][a][0] += accumulate(ALL(dp[i][j][b]), Int{0});
                        }
                    }
                }
            }
        }
    }

    Int ans = 0;

    for (int k = 0; k <= min(s, K); ++k) {
        for (int a = 0; a <= maxA; ++a) {
            ans += accumulate(ALL(dp[s][k][a]), Int{0});
        }
    }

    cout << ans << endl;

    return 0;
}

