  for (int i = 0; i <= k; i++)
    for (int j = 0; j <= k; j++)
      dp[0][i][j] = 0;
  dp[0][0][0] = 1;
  int dpi = 0;
  for (int i = n-1; i >= 0; i--) {
    ++dpi;
    auto& nxt = dp[dpi%2];
    auto& pdp = dp[dpi%2^1];
    memcpy(&nxt, &pdp, sizeof(mint)*(k+1)*(k+1));
    // push
    for (int j = 1; j <= k; j++) {
      mint rsum = 0;
      for (int l = 0; l <= j; l++) {
