vi clean(string& s) {
  vi ret;
  int idx = 0;
  int n = s.size();
  rep (i, n) {
    if (s.at(i) == '0') {
      ret.push_back(i - idx);
      idx = i + 1;
    }
  }
  if (idx < n) {
    ret.push_back(idx - n);
  }
  return ret;
}

int mod = 998244353;
void solve() {
  string s;
  scan(s);
  int k;
  scan(k);
  auto cleaned = clean(s);
  debug(s);
  debug(cleaned);
  vvll dp(k+1, vll(k+1, 0));
  dp[0][0] = 1;
  int sz = cleaned.size();
  if (cleaned.back() < 0) {
    sz -= 1;
  }
  rep (ic, sz) {
    vvll ndp = dp;
    rep (i, k+1) {
      rep (j, k+1) {
        if (i + j > k) {
          break;
        }
        if (i > 0) {
          FOR (moved, 1, cleaned.at(ic) + 1) {
            if (i < moved) {
              break;
            }
            ndp.at(i - moved).at(j + moved) = (ndp.at(i - moved).at(j + moved) + dp.at(i).at(j)) % mod;
          }
        }
        FOR (total, i+j+1, k+1) {
          int should_moved = total - i - j;
          ndp.at(i + should_moved).at(j) = (ndp.at(i + should_moved).at(j) + dp.at(i).at(j)) % mod;
        }
      }
    }
    swap(dp, ndp);
    //debug2(ic, dp);
  }
  if (cleaned.back() < 0) {
    vvll ndp = dp;
    int caic = -cleaned.back();
    rep (i, k+1) {
      rep (j, k+1) {
        if (i + j > k) {
          break;
        }
        if (i > 0) {
          FOR (moved, 1, caic + 1) {
            if (i < moved) {
              break;
            }
            ndp.at(i - moved).at(j + moved) = (ndp.at(i - moved).at(j + moved) + dp.at(i).at(j)) % mod;
          }
        }
      }
    }
    swap(dp, ndp);
    //debug2(caic, dp);
  }
  ll ans = 0;
  rep (i, k+1) {
    ans = (ans + dp.at(0).at(i)) % mod;
  }
  print(ans);
}

