        }
      }

      rep(j, N+1) {
        rep(k, K+1) {
          int d = min(k, rem);
          if (d == 0) continue;
          naname[dst][j+1][k-1] += dp[src][j][k];
          if (k-d-1 >= 0 && j+d+1 <= N) {
            naname[dst][j+d+1][k-d-1] -= dp[src][j][k];
          }
        }
      }

      rep(j, N+1) {
        rep(k, K+1) {
          tate[dst][j+1][k] += tate[dst][j][k];
        }
      }

      rep(tot, N+K+1) {
        rep(j, tot+1) {
          int k = tot - j;
          if (k >= 1) naname[dst][j+1][k-1] += naname[dst][j][k];
        }
      }

      rep(j, N+1) {
        rep(k, K+1) {
          dp[src][j][k] = tate[dst][j][k] + naname[dst][j][k];
        }
      }

      //rep(j, N+1) {
      //  rep(k, K+1) {
      //    cout << "dp[" << j << "][" << k << "]: " << dp[src][j][k].a << endl;
      //  }
      //}

      rem = 0;
    } else assert(0);
  }

  mint ans = 0;
  rep(k, K+1) {
    ans += dp[src][0][k];
    //cout << k << ": " << dp[src][0][k].a << endl;
  }
  cout << ans.a << endl;
}

