				dp_suff[zi][i][j] %= p;
			}
		}
	}

	ll ans=0LL;

	for(int i=0; i<=k; i++)
	{
		ans += dp_real[zi][i][0];
		ans %= p;
	}

	cout << ans << endl;
}

