int dp[N][N][N];

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	string s;
	int k;
	cin >> s >> k;
	int cnt_1 = 0;
	for (int i = (int)s.size() - 1; i >= 0; i--) {
		if (s[i] == '0') {
			break;
		} else {
			cnt_1++;
		}
	}
	s.push_back('0');
	int n = (int)s.size();
	k = min(k, n);
	for (int i = 0; i <= cnt_1; i++) {
		dp[n - 1][i][i] = 1;
	}
	//dp[i][cnt][fly]
	int last = -1;
	for (int i = n - 1; i >= 0; i--) {
		if (s[i] == '1') continue;
		int p = -1;
		for (int j = i - 1; j >= 0; j--) {
			if (s[j] == '0') {
				p = j;
				break;
			}
		}
		int block = 0;
		for (int j = p - 1; j >= 0; j--) {
			if (s[j] == '0') {
				break;
			} else {
				block++;
			}
		}
		if (p == -1) {
			last = i;
			break;
		}
		for (int cnt = 0; cnt <= 2 * n; cnt++) {
			for (int fly = 0; fly <= n; fly++) {
				if (!dp[i][cnt][fly]) continue;
				if (cnt == 0) assert(fly == 0); 
				for (int nblock = 0; nblock <= n; nblock++) {
					if (fly + block - nblock < 0) continue;
					dp[p][cnt + abs(block - nblock)][fly + (block - nblock)] = add(dp[p][cnt + abs(block - nblock)][fly + (block - nblock)], dp[i][cnt][fly]);

				}
			}
		}
	}
	int ans= 0;
	for (int mv = 0; mv <= 2 * k; mv++) {
		ans = add(ans, dp[last][mv][0]);
	}	
	cout << ans << endl;
}

