    {
        int cnt = count(s.begin(), s.end(), '0');
        if(cnt == 0 or cnt == s.size()) {
            puts("1");
            return 0;
        }
    }

    reverse(s.begin(), s.end()); s += "0";
    int N = s.size(); K = min(K, N);
    vector<int> ones;
    {
        int cnt = 0;
        for(int i=0; i<N; i++) {
            if(s[i] == '1') cnt++;
            if(s[i] == '0') {
                ones.emplace_back(cnt);
                cnt = 0;
            }
        }
    }
    for(auto one : ones) cerr << one << " ";
    cerr << endl;

    int M = ones.size(), ones_sum = 0;
    dp[0][0][0] = mint(1);
    for(int t=0; t<M; t++) {
        for(int i=0; i<=ones_sum; i++) {
            for(int j=i; j<=ones_sum+ones[t]; j++) {
                int c = max(0, j-i-ones[t]);
                for(int k=0; k+c<=K; k++) {
                    dp[t+1][j][k+c] += dp[t][i][k];
                }
            }
        }
        ones_sum += ones[t];
    }

    mint ans(0);
    for(int i=0; i<=K; i++) ans += dp[M][ones_sum][i];
    cout << ans << endl;
    return 0;
