int main() {
#ifdef iq
  freopen("a.in", "r", stdin);
#endif
  ios::sync_with_stdio(0);
  cin.tie(0);
  string s;
  cin >> s;
  int k;
  cin >> k;
  int n = (int) s.size();
  reverse(s.begin(), s.end());
  for (int i = n; i >= 0; i--) {
    first_zero[i] = -1;
    if (i < n) {
      first_zero[i] = first_zero[i + 1];
      if (s[i] == '0') first_zero[i] = i;
    }
  }
  k = min(k, n);
  dp[0][0][0] = 1;
  for (int i = 0; i < n; i++) {
    for (int j = i; j <= n; j++) {
      for (int its = 0; its <= k; its++) {
        if (!dp[i][j][its]) continue;
        int gap = j - i;
        for (int t = 0; t < 2; t++) {
          if (t == 1) {
            if (j != n && s[j] == '1') {
              add(dp[i + 1][j + 1][its], dp[i][j][its]);
            } else {
              if (gap) {
                add(dp[i + 1][j][its], dp[i][j][its]);
              }
            }
          } else {
            int x = first_zero[j];
            if (x != -1) {
              add(dp[i + 1][x + 1][its + (x - j)], dp[i][j][its]);
            }
          }
        }
      }
    }
  }
  int ret = 0;
  for (int j = 0; j <= k; j++) {
    add(ret, dp[n][n][j]);
  }
  cout << ret << endl;
}

