    IN(string, S);
    IN(ll, K);
    vi A;
    ll N = S.size();
    ll m = 0;
    ll s = 0;
    REP(i, N)
    {
        if (S[i] == '1')
        {
            ++m;
            ++s;
        }
        else
        {
            A.push_back(m);
            m = 0;
        }
    }
    ll M = A.size();
    K = min(K, s);
    // dp[i箱目][j回操作した][供託にk個]
    vector<vector<vm>> dp(M + 1, vector<vm>(K + 1, vm(K + 1, 0)));
    REP(j, min(m, K) + 1)
    {
        dp[M][j][j] = 1;
    }
    for (ll i = M - 1; i >= 0; --i)
    {
        // 払い出す場合
        REP(j, K + 1)
        {
            for (ll k = K; k >= 0; --k)
            {
                // acc += dp[i + 1][j][k];
                // dp[i][j][k] = acc;
                if (j == 0 or k == 0)
                {
                    dp[i][j][k] = dp[i + 1][j][k];
                }
                else if (j > A[i] and k > A[i])
                {
                    dp[i][j][k] = dp[i + 1][j][k] + dp[i][j - 1][k - 1] - dp[i + 1][j - A[i] - 1][k - A[i] - 1];
                }
                else
                {
                    dp[i][j][k] = dp[i + 1][j][k] + dp[i][j - 1][k - 1];
                }
                // dp[i][j][k] = dp[i + 1][j - 1][k - 1] + dp[i + 1][j - 2][k - 2] + ...
                // dp[i][j - 1][k - 1] = dp[i + 1][j - 2][k - 2] + ...
            }
        }
        // もらう場合
        REP(j, K + 1)
        {
            mint acc = 0;
            for (ll k = K; k >= 0; --k)
            {
                dp[i][j][k] += acc;
                acc += dp[i + 1][j][k];
            }
        }
    }
    mint ans = 0;
    REP(j, K + 1)
    {
        ans += dp[0][j][0];
    }
    OUT(ans);
}

