		if(s[i] == '0') pos0.pb(i);
	}

	pos0.pb(n);

	dp[0][0][0] = 1;

	int m = SZ(pos0) - 1, z = n + 1 - m;
	for(int i = 1; i <= m; i++) {
		int actual_cnt_1 = pos0[i] - pos0[i - 1] - 1;
		for(int q = 0; q <= k; q++) {
			for(int bal = 0; bal <= z; bal++) {
				if(dp[i - 1][bal][q]) {
					for(int c = 0; c <= z; c++) {
						int delta = c - actual_cnt_1;
						int new_q = q + max(delta, 0);
						if(new_q <= k && delta + bal >= 0) {
							add(dp[i][delta + bal][new_q], 
							    dp[i - 1][bal][q]);
						}
					}
				}
			}
		}
	}

	int ans = 0;
	for(int i = 0; i <= k; i++) {
		add(ans, dp[m][0][i]);
	}

	cout << ans << endl;
}

