    ll cou0=0;
    vector<ll> count(301,0);
    for(auto p: S){
        if(p=='0')cou0++;
        else {count[cou0]++;}
    }
    vector<ll> igi(301,0);
    for(ll i=1;i<301;++i){
        igi[i]=igi[i-1];
        if(!count[i-1])igi[i]++;
    }
    //dp[i][j]は最終変化iで通算j個変化した奴
    vector<vector<ll>> dp(N, vector<ll>(K+1, 0));
    for(ll i=1;i<N;++i){
            //iからk個変化させたとき
            for(ll k=1;k<=count[i];++k){
                    //それまでの最終変化l,総個数jからの遷移について
                    for(ll l=1;l<=i-1;++l){
                        for(ll j=1;j<=K;++j){
                        if(j+k<=K&&j+k>=0){
                            dp[i][j+k]+=dp[l][j]*comb(igi[i]-1+k,k)%MOD;
                            dp[i][j+k]%=MOD;
                        }}
                    }
                    //無変化からの遷移
                    if(k<=K&&k>=0){
                    dp[i][k]+=comb(i+k-1,k)%MOD;
                    dp[i][k]%=MOD;}
            }
    }
    ll ans=1;//無変化
    for(ll i=0;i<N;++i){
        for(ll j=1;j<=K;++j){ans+=dp[i][j];ans%=MOD;}
    }
