		a[++cnt] = n - last;
	f[cnt + 1][0][0] = 1;
	for(int i = cnt; i; i--)
		for(int j = 0; j <= m; j++)
			for(int k = 0; k <= j; k++) {
				f[i][j][k] = f[i + 1][j][k];
				for(int p = 1; p <= a[i] && p <= j; p++)
					f[i][j][k] = (f[i][j][k] + f[i + 1][j - p][k - p])%mod;
				for(int p = 1; p <= j - k; p++)
					f[i][j][k] = (f[i][j][k] + f[i + 1][j][k + p])%mod;
			}
	for(int i = 0; i <= m; i++)
		ans = (ans + f[1][i][0])%mod;
	cout<<ans<<endl;
	return 0;
}

