const int MOD=998244353;

string s;
int k;

vector<int> nums;

ll fix(ll i){
	i%=MOD;
	if (i<0) i+=MOD;
	return i;
}

ll memo[305][305][305];
ll dp(int i,int used,int left){
	if (i==sz(nums)) return used==0;
	if (memo[i][used][left]!=-1) return memo[i][used][left];

	int res=0;
	rep(x,1,305){
		if (305<=used+x || left-x<0) break;
		res=fix(res+dp(i+1,used+x,left-x));
	}
	rep(x,0,nums[i]+1){
		if (used-x<0) break;
		res=fix(res+dp(i+1,used-x,left));
	}

	//cout<<i<<" "<<used<<" "<<left<<" "<<res<<endl;
	return memo[i][used][left]=res;
}

