vector<int> rlc(string& S){
    int n = S.size();
    int cnt = 0;
    vector<int> res;
    rep(i, 0, n){
        if(S[i] == '0'){
            res.emplace_back(cnt);
            cnt = 0;
        }else{
            cnt++;
        }
    }
    res.emplace_back(cnt);
    return res;
}

