void preWork(int p,int n,int m){
    for(int i = 0; i <= n; i++){
        preSum[i][0] = f[p][i][0];
        for(int j = 1; j <= m; j++){
            preSum[i][j] = preSum[i][j-1]+f[p][i][j];
            if(preSum[i][j]>=mod) preSum[i][j] -= mod;
        }
    }
    for(int i = -m; i <= n; i++){
        int pos = i+offset;
        if(i>=0) diaSum[pos][0] = f[p][i][0];
        else diaSum[pos][0] = 0;
        for(int j = 1; j <= m; j++){
            diaSum[pos][j] = diaSum[pos][j-1];
            int last = i+j;
            if(last<=n && last>=0) diaSum[pos][j] += f[p][last][j];
            if(diaSum[pos][j]>=mod) diaSum[pos][j] -= mod;
        }
    }
}

long long getPreSum(int i,int j,int n,int m){
    if(i>n) return 0;
    else{
        if(j>m) j = m;
        return preSum[i][j];
    }
}

