// mod付きコンビネーション
const int MAX = 1100000;
// const int MOD = 1000000007;
const int MOD = mod;

Int fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
Int COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
    COMinit();
    string s;
    Int k;
    cin >> s >> k;
    vector<Int> a;
    Int z = 0;
    Int cnt = 0;
    for (Int i = 0; i < (Int)s.size(); i++) {
        if (s[i] == '0') {
            a.push_back(cnt);
            cnt = 0;
            z++;
        } else {
            cnt++;
        }
    }
    Int mi = INF;
    Int sum = 0;
    for (Int i = 0; i < (Int)a.size(); i++) {
        sum += a[i];
        mi = min(mi, a[i]);
    }
    if (k >= sum - mi + cnt) {
        Int x = COM(z + sum - 1, sum);
        Int res = x;
        for (Int i = 0; i < (Int)cnt; i++) {
            res += x * z % mod;
        }
        print(res);
    } else {
        assert(false);
    }
    return 0;
}

