  FOR(i,0,s.size()){
    For(k,K+1){
      vector<Modulo<MOD>> tmp(K+1);
      For(j,K+1){
        if(j+1<K+1)tmp[j+1]+=dp[i][j][k];
        if(K-k+1<K+1)tmp[K-k+1]-=dp[i][j][k];
      }
      partial_sum(tmp.begin(),tmp.end(),tmp.begin());
      For(j,K+1){
        dp[i+1][j][k]+=tmp[j];
      }
    }
    For(j,K+1){
