      }
      partial_sum(tmp.begin(),tmp.end(),tmp.begin());
      For(k,K+1){
        dp[i+1][j][k]+=tmp[k];
      }
    }
  }
  Modulo<MOD> ans(0);
  For(j,K+1){
    ans+=dp[s.size()][j][K-j];
  }
  cout<<ans<<endl;
}

