    int sz = v.size();
    for(int i = 0; i < v.size(); i++){
        for(int j = 0; j <= 300; j++){
            for(int k = 0; k <= 600; k++){
                buf0[j][k] = 0;
                buf1[j][k] = 0;
            }
        }
        for(int j = 0; j <= tmp+K; j++){
            for(int k = 0; k <= 2*K; k++){
                if(dp[i][j][k] == 0) continue;
                // [0, v[i]]
                int l = max(tmp+v[i], j);
                buf0[l][k+v[i]+j-l] += dp[i][j][k];
                buf0[j+v[i]+1][k-1] -= dp[i][j][k];
                buf0[j+v[i]+1][k-1] %= MOD;
                buf0[l][k+v[i]+j-l] %= MOD;
                // [v[i]+1, sum-tmp]
                buf1[j+v[i]+1][k+1] += dp[i][j][k];
                buf1[j+v[i]+sum-tmp+1][k+sum-tmp+1] -= dp[i][j][k];
                buf1[j+v[i]+1][k+1] %= MOD;
                buf1[j+v[i]+sum-tmp+1][k+sum-tmp+1] %= MOD;
            }
        }
        for(int j = 1; j <= sum; j++){
            for(int k = 1; k <= 2*K; k++){
                buf1[j][k] += buf1[j-1][k-1];
                buf1[j][k] %= MOD;
            }
        }
        for(int j = 1; j <= sum+2*K; j++){
            for(int k = 1; k <= j; k++){
                int l = j-k;
                buf0[k][l] += buf0[k-1][l+1];
                buf0[k][l] %= MOD;
            }
        }

        for(int j = 0; j <= 300; j++){
            for(int k = 0; k <= 600; k++){
                dp[i+1][j][k] = buf0[j][k]+buf1[j][k];
                dp[i+1][j][k] %= MOD;
            }
        }
        tmp += v[i];
    }
    ll ans = 0;

    for(int i = 0; i <= 2*K; i+=2){
        ans += dp[sz][sum][i];
        ans %= MOD;
    }
    cout << (ans+MOD)%MOD << endl;
}

