                for (int s = 0; s <= 1; ++s) for (int t = 0; t <= 1; ++t) dp[i][bal][del][s][t] %= mod;
            }
        }
    }
    int ans = 0;
    for (int d = 0; d <= k; ++d) ans += dp[n][0][d][0][0] + dp[n][0][d][0][1] + dp[n][0][d][1][1];
    cout << ans % mod << '\n';
    return 0;
}

