    if(dp1[x][y][move]!=-1)return dp1[x][y][move];
    // freebies
    for(int i=0;i<cnt[x];++i){
      ans += ask(x+1,y+i,move,1); 
      ans%=MOD;
    }
    // not free
    ans += ask(x,y+cnt[x],move,0);
    ans%=MOD;
    dp1[x][y][move]  = ans;
  }else{
    if(dp2[x][y][move]!=-1)return dp2[x][y][move];
    ans += ask(x+1,y,move,1);
    ans += ask(x,y+1,move+1,0);
    ans%=MOD;
    dp2[x][y][move] = ans;
  }
  // cout<<"Asking "<<x<<' '<<y<<' '<<move<<' '<<elig<<' '<<ans<<'\n';
