                int x = min(max(j+v[i]+1, k+v[i]+1), n+1);
                if(x != n+1) dp1[i+1][j+v[i]+1][k+v[i]+1] -= dp1[i][j][k];
                dp2[i+1][0][k] += dp1[i][j][k];
