const int MAXLEN = 300;
const int MOD = 998244353;
void inc(int& a, int b) { if ((a += b) >= MOD) a -= MOD; }
void dec(int& a, int b) { inc(a, MOD - b); }

char s[MAXLEN + 1]; int slen;
int lim;

vector<int> groups;
int dp[MAXLEN + 1][MAXLEN + 1];
int dpsum[MAXLEN + 1][MAXLEN + 1];
int dpsum2[MAXLEN + 1][MAXLEN + 1];
int ndp[MAXLEN + 1][MAXLEN + 1];

int solve() {
	{ groups.clear(); int groupsz = 0; REP(i, slen) if (s[i] == '1') ++groupsz; else groups.PB(groupsz), groupsz = 0; groups.PB(groupsz); }
	int sum = 0; REPSZ(i, groups) sum += groups[i];
	REPE(rem, sum) REPE(need, sum - rem) dp[rem][need] = need == 0 ? 1 : 0;

	for (int i = SZ(groups) - 1; i >= 0; --i) {
		REPE(rem, sum) REPE(need, sum - rem) { dpsum[rem][need] = dp[rem][need]; if (need - 1 >= 0) inc(dpsum[rem][need], dpsum[rem][need - 1]); }
		for (int rem = sum; rem >= 0; --rem) REPE(need, sum - rem) { dpsum2[rem + need][need] = dp[rem][need]; if (need - 1 >= 0) inc(dpsum2[rem + need][need], dpsum2[rem + need][need - 1]); }
		REPE(rem, sum) REPE(need, sum - rem) {
			ndp[rem][need] = 0;
			// remove at least one of them
			{ int lo = need - min(need, groups[i]), hi = need - 1; if (lo <= hi) { inc(ndp[rem][need], dpsum[rem][hi]); if (lo - 1 >= 0) dec(ndp[rem][need], dpsum[rem][lo - 1]); } }
			//FORE(j, 1, min(need, groups[i])) inc(ndp[rem][need], dp[rem][need - j]);
			// keep same or add some
			{ int lo = need, hi = need + min(rem, sum - need); if (lo <= hi) { inc(ndp[rem][need], dpsum2[rem + need][hi]); if (lo - 1 >= 0) dec(ndp[rem][need], dpsum2[rem + need][lo - 1]); } }
			//REPE(j, min(rem, sum - need)) inc(ndp[rem][need], dp[rem - j][need + j]);
		}
		REPE(rem, sum) REPE(need, sum - rem) dp[rem][need] = ndp[rem][need];
	}
	return dp[min(lim, sum)][0];
}


void run() {
	scanf("%s", s); slen = strlen(s);
	scanf("%d", &lim);
	printf("%d\n", solve());
}

