  vector<int> data(300);
  int count=0;
  int N=0;
  for (int i=0; i<int(S.length());i++ ){
    if(S.at(i) == '1'){
      count += 1;
    }else{
      data[N] = count;
      count = 0;
      N += 1;
    }
  }
  data[N] = count;
  vector<vector<vector<ll>>> dp(N+1, vector<vector<ll>>(K+1, vector<ll>(K+1)));
  for (int i=0; i<N+1;i++ ){
    dp[i][0][0] = 1;
  }
  for (int k=0; k<min(data[N]+1,K+1);k++){
    dp[0][k][k] = 1;
  }
  for (int i=1; i<N+1; i++){
    for (int k=0; k<K+1; k++){
      for (int j=K; j>=0; j--){
        if (j==K){
          dp[i][k][j] = dp[i-1][k][j];
          dp[i][k][j] %= MOD;
        }else{
          dp[i][k][j] = dp[i-1][k][j] + dp[i][k][j+1];
          dp[i][k][j] %= MOD;
        }
      }
    }
    int a = data[N-i];
    if (a!=0){
      for (int k=0; k<K+1; k++){
        queue<ll> q;
        clear(q);
        q.push(dp[i-1][k][0]);
        ll temp = dp[i-1][k][0];
        for (int j=1; j<K+1; j++){
          if (k+j>K) break;
          dp[i][k+j][j] += temp;
          dp[i][k+j][j] %= MOD;
          q.push(dp[i-1][k+j][j]);
          temp += dp[i-1][k+j][j];
          if (int(q.size())>a){
            temp -= q.front();
            q.pop();
          }
          temp %= MOD;
        }
      }
    }
  }
  ll ans = 0;
  for (int k=0; k<K+1; k++){
    ans += dp[N][k][0];
    ans %= MOD;
  }
  cout << ans <<endl;
}

