  for (int i = n - 1; i >= 0; --i) {
    if (s[i] == '0') {
      next0[i] = i;
    } else {
      next0[i] = next0[i + 1];
    }
  }
  vector dp(n + 2, vector<mod_int<>>(k + 2));
  dp[0][0] = 1;
  for (int i = 0; i < n; ++i) {
    vector next_dp(n + 2, vector<mod_int<>>(k + 2));
    for (int j = 0; j <= i; ++j) {
      for (int l = 0; l <= k; ++l) {
        // Add a 0.
        next_dp[next0[j] + 1][l] += dp[j][l];
        // Add a 1.
        if (s[j] == '0') {
          next_dp[j][l + 1] += dp[j][l];
        } else {
          next_dp[j + 1][l] += dp[j][l];
        }
      }
    }
    dp = move(next_dp);
  }
  mod_int<> ans = 0;
