    if (s[i] == '0') {
      last0 = i;
      break;
    }
  }
  for (int j = last0 + 1; j <= n; ++j) {
    for (int l = 0; l <= k; ++l) {
      ans += dp[j][l];
    }
  }
  cout << ans << '\n';
  return 0;
}

