int main(int argc, char* argv[])
{
	//ios::sync_with_stdio(false); cin.tie(0);
    // rng = mt19937(chrono::steady_clock::now().time_since_epoch().count());

    string s;
    cin >> s;
    int k;
    cin >> k;
    if (k > SZ(s))
        k = SZ(s);

    reverse(ALL(s));

    dp[0][0][0] = 1;

    nx[SZ(s)] = SZ(s);

    RFOR(i,SZ(s), 0) {
        if (s[i] == '0')
            nx[i] = i;
        else
            nx[i] = nx[i + 1];
    }

    FOR(i,0,SZ(s) + 1) {
        RFOR(j,i + 1,0) {
            FOR(k,0,i + 1) {
                if (dp[i][j][k] == 0)
                    continue;
                if ((i == SZ(s) || s[i] == '0') && j > 0) {
                    dp[i][j - 1][k] += dp[i][j][k];
                    dp[i][j - 1][k] %= MOD;
                }
                if (i == SZ(s))
                    continue;
                dp[i + 1][j][k] += dp[i][j][k];
                dp[i + 1][j][k] %= MOD;
                if (s[i] == '1' && nx[i] != SZ(s)) {
                    int cnt = nx[i] - i;
                    dp[nx[i] + 1][j + cnt][k + cnt] += dp[i][j][k];
                    dp[nx[i] + 1][j + cnt][k + cnt] %= MOD;
                }
            }
        }
    }

    Int res = 0;
    FOR(i, 0, k + 1) {
        // cout << i << ' ' << dp[SZ(s)][0][i] << endl;
        res += dp[SZ(s)][0][i];
        res %= MOD;
    }

    cout << res << endl;


    cerr << 1.0 * clock() / CLOCKS_PER_SEC << endl;
	return 0;
}

