const int P = 998244353;
int main(){
	scanf("%s%d",s+1,&K);
	N = strlen(s+1);
	cnt = 1;
	int sum = 0;
	for (int i=1; i<=N; i++){
		if (s[i] == '1') a[cnt]++;
		else cnt++,sum += a[cnt-1];
	}
	if (!a[cnt]) cnt--;
//	printf("%d\n",cnt);
//	for (int i=1; i<=cnt; i++) printf("%d ",a[i]); puts("");
	K = min(K,N)<<1;
	f[0][0][0] = 1;
	for (int i=0; i<=cnt; i++){
		for (int j=0; j<=K; j++){
			for (int k=0; k<=N; k++){
				if (!f[i][j][k]) continue;
//				printf("debug %d %d %d %d\n",i,j,k,f[i][j][k]);
				f[i+1][j][k] += f[i][j][k];
				f[i+1][j][k] %= P;
				for (int l=1; j+l<=K; l++)
					f[i+1][j+l][k+l] += f[i][j][k], f[i+1][j+l][k+l] %= P;
				for (int l=1; l<=min(a[i+1],k) && j+l<=K; l++)
					f[i+1][j+l][k-l] += f[i][j][k], f[i+1][j+l][k-l] %= P; 
			}
		}	
	}
	int ans = 0;
	for (int i=0; i<=K; i++) ans += f[cnt][i][0], ans %= P;
