int main(void) {
    string S;
    int K;
    cin >> S >> K;
    vi A;
    int num = 0;
    int count = 0;
    rep(i, S.size()) {
        if (S[i] == '0') {
            A.push_back(num);
            num = 0;
        } else {
            num++;
            count++;
        }
    }
    chmin(K, count);
    A.push_back(num);
    dump(A, count, K);

    int N = A.size();
    // dp[i][j][k] = i番目まで決めて、累積和の値が j で、必要移動回数が k 回
    vvvll dp(N + 1, vvll(count + 1, vll(K + 1, 0)));
    vvvll dp2(N + 1, vvll(count + 2, vll(K + 1, 0)));
    vvvll dp3(N + 1, vvll(count + 2, vll(K + 2, 0)));
    dp[0][0][0] = 1;
    repr(j, 1, count + 2) {
        dp2[0][j][0] = 1;
    }
    dp3[0][1][0] = 1;

    ll cumsum = 0;
    repr(i, 1, N + 1) {
        cumsum += A[i - 1];
        repr(j, cumsum, count + 1) {
            rep(k, K + 1) {
                int lmin = max(0, A[i - 1] - k);
                int lmax = min(j, count);
                if (j - lmin >= 0) {
                    // (j-lmin, k-A[i-1]+lmin)
                    dp[i][j][k] += dp3[i - 1][j - lmin + 1][k - A[i - 1] + lmin];

                    // (j-lth-1, k-A[i-1]+lth+1)
                    if (j - A[i - 1] - 1 >= 0 && k + 1 <= K) {
                        dp[i][j][k] += MOD - dp3[i - 1][j - A[i - 1]][k + 1];
                    }
                    // (j-A[i-1]-1, k)
                    if (j - A[i - 1] > 0) {
                        dp[i][j][k] += dp2[i - 1][j - A[i - 1]][k];
                    }

                    dp[i][j][k] %= MOD;
                }

                dp2[i][j + 1][k] = dp2[i][j][k] + dp[i][j][k];
                dp2[i][j + 1][k] %= MOD;
                dp3[i][j + 1][k] = dp3[i][j][k + 1] + dp[i][j][k];
                dp3[i][j + 1][k] %= MOD;
            }
        }
    }

    ll ans = 0;
    rep(k, K + 1) {
        ans += dp[N][count][k];
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

