				int v=dp[i][j][k];
				//cerr<<i<<' '<<j<<' '<<k<<": "<<max(0,pref[i]-j)<<' '<<ones-j<<'\n';
				for(int l=ones-j;l>=max(0,pref[i]-j);l--)
				{
					radd(dp[i+1][j+l][k+min(a[i],l)],v);
					//cerr<<"NEW "<<i+1<<' '<<j+l<<' '<<k+min(a[i],l)<<'\n';
				}
			}
		}
	}
	for(int i=ones-m;i<=ones;i++)
	{
		cerr<<n+1<<' '<<ones<<' '<<i<<' '<<dp[n+1][ones][i]<<'\n';
		radd(ans,dp[n+1][ones][i]);
	}
	cout<<ans<<'\n';
}

