                    next[w][c] += prev[j][b];
                    if (next[w][c] >= M) {
                        next[w][c] -= M;
                    }
                }
            }
        }
    }

    int64_t ans = 0;
    for (auto i : irange(0L, k + 1)) {
        ans += dp[h][i][a.back()];
        if (ans >= M) {
            ans -= M;
        }
    }

