   dp[i][j][k] = sum of dp[i+1][x][k] for x>=j
    and dp[i+1][p[i+1]+x][k-x] for p[i+1]+x >= j && x < j-p[i]
    so j-p[i+1] <= x < j-p[i]

    p[i+1]+j-p[i] >>> max(p[i],p[i+1]+j-p[i]-k)
    sum[i][j][k] = dp[i][j][k]+dp[i][j+1][k-1]+dp[i][j+2][k-2]+...

    So dp[i+1][p[i+1]+x][k-x] for j-p[i+1] <= x <= min(k, j-p[i])
    let mi = j-p[i+1], mx = min(k, j-p[i])+1
    = sum[i+1][p[i+1]+mi][k-mi] - sum[i+1][p[i+1]+ma][k-ma];
*/

