const int mod = 998244353;
const int N = 310;
inline void add(int &x, int y) { x += y; if (x >= mod) x -= mod; }

char s[N];
int k, n, seq[N], tot, pre[N];

int dp[N][N], S;

void do_dp(int minsum, int cur)
{
	static int pre1[N][N], pre2[N][N];
	for (int i = 0; i <= S; i++) for (int j = 0; j <= S; j++) pre1[i][j] = pre2[i][j] = 0;

	// puts("dp");
	for (int i = 0; i <= S; i++) for (int j = 0; j <= S; j++) if (dp[i][j])
			{
				// 0 <= a[i] < cur
				add(pre1[i][j], dp[i][j]);
				add(pre1[i + cur][j], mod - dp[i][j]);

				// a[i] >= cur
				add(pre2[i + cur][j], dp[i][j]);
			}

	memset(dp, 0, sizeof(dp));
	for (int i = 0; i <= S; i++) for (int j = 0; j <= S; j++)
		{
			if (i) add(pre1[i][j], pre1[i - 1][j]);
			if (i && j) add(pre2[i][j], pre2[i - 1][j - 1]);
			if (i >= minsum)
			{
				dp[i][j] = pre1[i][j] + pre2[i][j];
				if (dp[i][j] >= mod) dp[i][j] -= mod;
			}
		}
}

