		{
			seq[++tot] = i - last - 1;
			last = i;
		}
	seq[++tot] = n - last;
	for (int i = 1; i <= tot; i++) pre[i] = pre[i - 1] + seq[i];
	S = pre[tot];

	dp[0][0] = 1;
	for (int i = 1; i <= tot; i++) do_dp(pre[i], seq[i]);

	int ans = 0;
	for (int i = 0; i <= S && i <= k; i++) add(ans, dp[S][i]);
	cout << ans;

	return 0;
}

