    int sum = 0;
    for(int i = 0; i < n; ){
        int cnt = 0; while(i + cnt < n and S[i + cnt] == '1') ++cnt;
        A.push_back(cnt); i += cnt + 1; sum += cnt;
    }

    std::reverse(A.begin(), A.end());
    const int m = A.size();
