                    const int nxt_k = ((0 < move) ? move : 0) + k;
                    if(nxt_k > K) continue;
                    (EP[chokin + move][nxt_k] += DP[chokin][k]) %= mod;
                }
            }
        }
        std::swap(DP, EP);
