const long long MOD = 998244353;

using namespace std;

char str[305];

ll dp[305][305][305];

void solve()
{
    int K;
    scanf("%s%d", str, &K);
    int n = strlen(str);
    int i, j, k;
    vector<int> a;
    int cnt = 0;
    for (i = 0; i < n; i++) {
        if (str[i] == '1') {
            cnt++;
        }
        else {
            a.push_back(cnt);
            cnt = 0;
        }
    }
    a.push_back(cnt);
    int siz = (int)a.size();
    int sum = 0;
    for (i = 0; i < siz; i++) {
        sum += a[i];
    }
    if (K > sum) {
        K = sum;
    }

    dp[0][0][0] = 1;
    for (i = 0; i < siz; i++) {
        for (j = 0; j <= K; j++) {
            for (k = 0; k <= j; k++) {
                if (dp[i][j][k] == 0) continue;

                int lim0 = MAX(0, a[i] - k);
                int lim1 = a[i] + (K - j);
                int p;
                for (p = lim0; p <= lim1; p++) {
                    int j2 = j, k2 = k;
                    if (p < a[i]) {
                        int diff = a[i] - p;
                        k2 = k - diff;
                    }
                    if (p > a[i]) {
                        int diff = p - a[i];
                        j2 += diff;
                        k2 += diff;
                    }
                    dp[i + 1][j2][k2] = (dp[i + 1][j2][k2] + dp[i][j][k]) % MOD;
                }
            }
        }
    }

    ll ans = 0;
    for (i = 0; i <= K; i++) {
        ans = (ans + dp[siz][i][0]) % MOD;
    }
    printf("%lld\n", ans);

    return;
}


