	for (l = 1, k = 0; S[l] != 0; l++) {
		if (S[l] == S[l-1] || S[l] == '1') count[k][S[l] - '0']++;
		else count[++k][0]++;			
	}

	long long dp[301][301][301] = {};
	if (count[0][0] == 0) i = 1;
	else i = 0;
