int search(int pos, int hold, int left) {
	int answer = 0;
	int i;
	if (pos < 0) return hold == 0;
	if (memo[pos][hold][left]) return ~memo[pos][hold][left];

	for (i = -hold; i <= suretu[pos] && i <= left; i++) {
		answer = add(answer, search(pos - 1, hold + i, i < 0 ? left : left - i));
	}

	return ~(memo[pos][hold][left] = ~answer);
