    val numCases = 1//readInt()
    case@ for(case in 1..numCases) {
//        print("Case #$case: ")

        val s = read()
        var k = readInt()

        val A = intListOf(0)
        for(c in s) {
            if(c == '1') A[A.lastIndex]++
            else A.add(0)
        }

        k = min(k, A.sum())
        val n = A.size

        var D = Array(k+1) { ModIntArray(it+1) }
        D[0][0] = ModInt(1)

        for(i in n-1 downTo 0) {
            val Di = Array(k+1) { ModIntArray(it+1) }

            val q = A[i]
            for(b in 0..k) {
                var sum = ModInt(0)
                for(a in b..k) {
                    sum += D[a][b]
                    if(a-q > b) sum -= D[a-q-1][b]
                    Di[a][b] = sum
                }
            }

            for(a in 0..k) {
                var sum = ModInt(0)
                for(b in 0..a) {
                    Di[a][b] += sum
                    sum += D[a][b]
                }
            }

            D = Di
