public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		char[] s = ns().toCharArray();
		int K = ni();
		int n = s.length;
		int[] b = new int[n+1];
		int p = 0;
		int one = 0;
		int ao = 0;
		for(int i = 0;i < n;i++){
			if(s[i] == '1'){
				one++;
				ao++;
			}else{
				b[p++] = one;
				one = 0;
			}
		}
		b[p++] = one;
		b = Arrays.copyOf(b, p);
		K = Math.min(ao, K);

		long[][] dp = new long[K+1][ao+1]; // #trans, balance
		dp[0][0] = 1;
		int mod = 998244353;
		// p+ao<=300
		for(int i = 0;i < p;i++){
			long[][] ndp = new long[K+1][ao+1]; // #trans, balance
			for(int j = 0;j <= K;j++){
				for(int k = 0;k <= ao;k++){
					if(dp[j][k] != 0){
						// k+l-b[i] >= 0
						// l >= b[i]-k
						// k+l-b[i] <= ao
						// l <= ao + b[i]-K
						// j+l-b[i]<=K
						// l<=K+b[i]-j
						int sup = Math.min(K+b[i]-j, Math.min(ao, ao+b[i]-k));
						for(int l = Math.max(0, b[i]-k);l <= sup;l++){
							int nk = k + l - b[i];
							if(l-b[i] > 0){
								ndp[j+l-b[i]][nk] += dp[j][k];
								if(ndp[j+l-b[i]][nk] >= mod)ndp[j+l-b[i]][nk] -= mod;
							}else{
								ndp[j][nk] += dp[j][k];
								if(ndp[j][nk] >= mod)ndp[j][nk] -= mod;
							}
						}
					}
				}
			}
			dp = ndp;
		}

		long ans = 0;
		for(int i = 0;i <= K;i++){
			ans += dp[i][0];
		}
		out.println(ans % mod);
	}

