    for (int i = 1; i <= m; i++) {
      long[] sum1 = new long[k * 2 + 1];

      for (int j = 0; j <= k; j++) {

        long sum2 = 0;

        for (int t = 0; t <= k; t++) {
          sum1[j - t + k] += dp[i - 1][j][t];
