        for (int t = 0; t <= k; t++) {
          dp[i][j][t] += sum1[j - t + k];
        }

        for (int t = k, cnt = 0; t >= 0; t--, cnt++) {
          sum2 += dp[i - 1][j][t];
          if (cnt > a[i - 1]) {
            sum2 += mod - dp[i - 1][j][t + a[i - 1] + 1];
