          // dp[i][j][t] += dp[i - 1][j][t + q];
          // }
          dp[i][j][t] %= mod;
        }
      }
      // System.err.println(Arrays.deepToString(dp[i]) + " " + Arrays.toString(sum1));

    }

    long ret = 0;
    for (int i = 0; i <= k; i++) {
      ret += dp[m][i][0];
