        var size = Min(s.Length, K) + 1;

        //dp[動かした数(最小)][j個の場所に置ける]
        ModInt[][] dp = Enumerable.Repeat(0, size).Select(_ => new ModInt[s.Length + 3]).ToArray();
        dp[0][0] = 1;

        int cur1Streak = 0;

        void resolve()
        {
            ModInt[][] newdp = Enumerable.Repeat(0, size).Select(_ => new ModInt[s.Length + 3]).ToArray();
            //動かさない
            for (int i = 0; i < dp.Length; i++)
            {
                for (int j = 1; j < dp[i].Length; j++)
                {
                    newdp[i][j] = dp[i][j - 1];
                }
            }
            //動かす
            for (int nextMove = 1; nextMove <= cur1Streak; nextMove++)
            {
                for (int totalMove = nextMove; totalMove < dp.Length; totalMove++)
                {
                    //move個動かす→move個動かせるところが必要?そうでもない
                    for (int remainPlace = 1; remainPlace < dp[totalMove].Length; remainPlace++)
                    {
                        newdp[totalMove][remainPlace] += dp[totalMove - nextMove][remainPlace] * Combination(remainPlace - 1 + nextMove, nextMove);
                    }
                }
            }
            dp = newdp;
        }

        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '1')
            {
                cur1Streak++;
                continue;
            }
            resolve();
            cur1Streak = 0;
        }
        resolve();

        Console.WriteLine(dp.Aggregate(new ModInt(0), (x, y) => y.Aggregate((x, y) => x + y) + x));
    }

    /// <summary>
    /// nCm
    /// </summary>
    static ModInt Combination(int n, int m) => Factorial[n] * InvFactorial[n - m] * InvFactorial[m];

    static List<ModInt> Factorial = new List<ModInt>() { 1 };
    static ModInt _f(int x)
    {
        for (int i = Factorial.Count; i <= x; i++) Factorial.Add(Factorial.Last() * i);
        return Factorial[x];
    }

    static List<ModInt> InvFactorial = new List<ModInt>();

    static ModInt Power(ModInt n, long m)
    {
        ModInt pow = n;
        ModInt res = 1;
        while (m > 0)
        {
            if ((m & 1) == 1) res *= pow;
            pow *= pow;
            m >>= 1;
        }
        return res;
    }
}


struct ModInt
{
    public const int Mod = 998244353;
    const long POSITIVIZER = ((long)Mod) << 31;
    long Data;
    public ModInt(long data) { if ((Data = data % Mod) < 0) Data += Mod; }
    public static implicit operator long(ModInt modInt) => modInt.Data;
    public static implicit operator ModInt(long val) => new ModInt(val);
    public static ModInt operator +(ModInt a, int b) => new ModInt() { Data = (a.Data + b + POSITIVIZER) % Mod };
    public static ModInt operator +(ModInt a, long b) => new ModInt(a.Data + b);
    public static ModInt operator +(ModInt a, ModInt b) { long res = a.Data + b.Data; return new ModInt() { Data = res >= Mod ? res - Mod : res }; }
    public static ModInt operator -(ModInt a, int b) => new ModInt() { Data = (a.Data - b + POSITIVIZER) % Mod };
    public static ModInt operator -(ModInt a, long b) => new ModInt(a.Data - b);
    public static ModInt operator -(ModInt a, ModInt b) { long res = a.Data - b.Data; return new ModInt() { Data = res < 0 ? res + Mod : res }; }
    public static ModInt operator *(ModInt a, int b) => new ModInt(a.Data * b);
    public static ModInt operator *(ModInt a, long b) => a * new ModInt(b);
    public static ModInt operator *(ModInt a, ModInt b) => new ModInt() { Data = a.Data * b.Data % Mod };
    public static ModInt operator /(ModInt a, ModInt b) => new ModInt() { Data = a.Data * GetInverse(b) % Mod };
    public static bool operator ==(ModInt a, ModInt b) => a.Data == b.Data;
    public static bool operator !=(ModInt a, ModInt b) => a.Data != b.Data;
    public override string ToString() => Data.ToString();
    public override bool Equals(object obj) => (ModInt)obj == this;
    public override int GetHashCode() => (int)Data;
    static long GetInverse(long a)
    {
        long div, p = Mod, x1 = 1, y1 = 0, x2 = 0, y2 = 1;
        while (true)
        {
            if (p == 1) return x2 + Mod; div = a / p; x1 -= x2 * div; y1 -= y2 * div; a %= p;
            if (a == 1) return x1 + Mod; div = p / a; x2 -= x1 * div; y2 -= y1 * div; p %= a;
        }
    }
}

