using System;
using System.Collections.Generic;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N;
    private string S;
    private int K;

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        N = S.Length;
        K = sc.NextInt();

        int cnt = 0;
        List<int> ls = new List<int>();
        for (int i = N - 1; i >= 0; i--)
        {
            if (S[i] == '0')
            {
                ls.Add(cnt);
                cnt = 0;
            }
            else
            {
                cnt++;
            }
        }

        // i個目の0、保留した1の個数、操作回数
        var dp = new ModInt[(ls.Count + 1) * 301 * 301];
        dp[C(0, 0, 0)] = 1;
        int one = 0;
        for (int i = 0; i < ls.Count; i++)
        {
            for (int j = 0; j <= one; j++)
            {
                for (int k = 0; k <= one; k++)
                {
                    // ここに置く1の個数
                    for (int l = 0; l <= j + ls[i]; l++)
                    {
                        int nk = k + Math.Max(0, ls[i] - l);
                        int nj = j + ls[i] - l;
                        dp[C(i + 1, nj, nk)] += dp[C(i, j, k)];
                    }
                }
            }

            one += ls[i];
        }

        ModInt ans = 0;
        for (int i = 0; i <= 300; i++)
        {
            for (int j = 0; j <= K && j <= 300; j++)
            {
                ans += dp[C(ls.Count, i, j)];
            }
        }

        Console.WriteLine(ans);
    }

    int C(int i, int j, int k)
    {
        return i * 301 * 301 + j * 301 + k;
    }

    public static void Main(string[] args) => new Program().Solve();
}

