internal partial class Solver {

    List<int> Split(string s) {
        var res = new List<int>();
        int count = 0;
        foreach (var c in s) {
            if (c == '0') {
                res.Add(count);
                count = 0;
            } else {
                count++;
            }
        }
        res.Add(count);
        return res;
    }

    public void Run() {
        var s = ns();
        var k = ni();

        var a = Split(s);
        //a.Dump();
        var mod = ModInt.SetModValue(998244353);

        var maxK = Math.Min(k, a.Sum()) + 10;
        var memo = new ModInt?[a.Count + 1, maxK + 1, maxK + 1];
        var memo2 = new ModInt?[a.Count + 1, maxK + 1, maxK + 1];
        var memo3 = new ModInt?[a.Count + 1, maxK + 1, maxK + 1];

        var sumA = a.Append(0).ToArray();
        for (int i = sumA.Length - 2; i >= 0; i--) {
            sumA[i] += sumA[i + 1];
        }

        ModInt dfsDown(int pos = 0, int up = 0, int down = 0) {
            if (up < 0) return 0;
            if (up > maxK) return 0;
            if (down > k || down > maxK) return 0;
            ref var ret = ref memo2[pos, up, down];
            if (!ret.HasValue) {
                ModInt val = 0;
                val += dfs(pos + 1, up, down);
                if (up - 1 >= 0) {
                    val += dfsDown(pos, up - 1, down + 1);
                }

                ret = val;
            }
            return ret.Value;
        }

        ModInt dfsUp(int pos = 0, int up = 0, int down = 0) {
            if (up < 0) return 0;
            if (up > maxK) return 0;
            if (down > k || down > maxK) return 0;
            ref var ret = ref memo3[pos, up, down];
            if (!ret.HasValue) {
                ModInt val = 0;
                val += dfs(pos + 1, up, down);
                if (up + 1 < maxK) {
                    val += dfsUp(pos, up + 1, down);
                }
                ret = val;
            }
            return ret.Value;
        }

        ModInt dfs(int pos = 0, int up = 0, int down = 0) {
            if (up < 0) return 0;
            if (up > maxK) return 0;
            if (down > k || down > maxK) return 0;

            if (!memo[pos, up, down].HasValue) {
                ModInt val = 0;
                if (pos == a.Count) {
                    if (up == 0) {
                        val = 1;
                    }
                } else {
                    var v = a[pos];
                    val += dfsDown(pos, up, down) - dfsDown(pos, up - (v + 1), down + (v + 1));
                    val += dfsUp(pos, up + 1, down);
                }

                memo[pos, up, down] = val;
            }
            return memo[pos, up, down].Value;
        }

        cout.WriteLine(dfs());
    }
