class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;
    long mod = 998244353;

    void calc()
    {
        string S = cin.next();
        int K = cin.nextInt();
        //string S = new string('0', 150) + new string('1', 150);
        //int K = 10000;

        List<int> numL = new List<int>();
        int now = 0;
        int one = 0;
        foreach (var item in S)
        {
            if (item == '0')
            {
                numL.Add(now);
                now = 0;
            }
            else { now++; one++; }
        }
        numL.Add(now);

        int[] num = numL.ToArray();
        int N = num.Length;
        K = Math.Min(K, one);
        long[,] dp = new long[K + 1, K + 1];
        dp[0, 0] = 1;

        for (int t = 0; t < num.Length; t++)
        {
            long[,] nextdp = new long[K + 1, K + 1];
            for (int i = 0; i < K + 1; i++)
            {
                for (int j = i; j < K + 1; j++)
                {
                    if (dp[i, j] == 0) continue;
                    int minK = Math.Max(0, num[t] - i);
                    for (int k = minK; k < num[t]; k++)
                    {
                        nextdp[i - (num[t] - k), j] += dp[i, j];
                        if (nextdp[i - (num[t] - k), j] >= mod) nextdp[i - (num[t] - k), j] -= mod;
                    }

                    for (int add = 0; add <= (K - j); add++)
                    {
                        nextdp[i + add, j + add] += dp[i, j];
                        if (nextdp[i + add, j + add] >= mod) nextdp[i + add, j + add] -= mod;
                    }

                }
            }
            dp = nextdp;
        }

        long ans = 0;
        for (int i = 0; i <= K; i++)
        {
            ans += dp[0, i];
        }
        ans %= mod;

        Console.WriteLine(ans);
    }

}


