    public static string Result(bool b) => b ? "Yes" : "No";
    private object Calc()
    {
        S = cr;
        K = cr;
        oneCount = S.Count(c => c == '1');
        K.UpdateMin(oneCount);
        {
            var cl = new List<int>();
            var cnt = 0;
            foreach (var c in S)
            {
                if (c == '1')
                    cnt++;
                else
                {
                    cl.Add(cnt);
                    cnt = 0;
                }
            }
            cl.Add(cnt);
            cnts = cl.ToArray();
        }
        Mod[][] dp = NewArray(K + 1, K + 1, new Mod());
        dp[0][0] = 1;
        for (int i = cnts.Length - 1; i >= 0; i--)
        {
            Mod[][] nx = NewArray(K + 1, K + 1, new Mod());
            for (int j = 1; j <= K; j++)
                for (int x = 1; x <= K; x++)
                {
                    nx[j][x] = nx[j - 1][x - 1] + dp[j - 1][x - 1];
                    if (j - 1 - cnts[i] >= 0 && x - 1 - cnts[i] >= 0)
                        nx[j][x] -= dp[j - 1 - cnts[i]][x - 1 - cnts[i]];
                }

            for (int j = K; j >= 0; j--)
            {
                Mod sum = 0;
                for (int x = j; x >= 0; x--)
                {
                    sum += dp[j][x];
                    nx[j][x] += sum;
                }
            }
            dp = nx;
        }
        return dp.Select(ddp => ddp[0]).Sum();
    }
    int[] cnts;
    string S;
    int K;
    int oneCount;
}

