    public void Run() {
        var s = ns();
        var K = ni();

        var a = Split(s);
        a.Reverse();
        var mod = ModInt.SetModValue(998244353);

        var maxK = Math.Min(K, a.Sum()) + 10;
        var dp = new ModInt[maxK + 1, maxK + 1]; // pos, downNum, k

        var sum = a.Prepend(0).ToArray();
        for (int i = 0; i + 1 < sum.Length; i++) {
            sum[i + 1] += sum[i] + a[i];
        }
        dp[0, 0] = 1;
        for (int i = 0; i < a.Count; i++) {
            var next = new ModInt[maxK + 1, maxK + 1];
            var add1 = new ModInt[maxK + 1, maxK + 1];
            var add12 = new ModInt[maxK + 1, maxK + 1];
            var v = a[i];
            for (int j = 0; j <= maxK; j++) {
                for (int k = 0; k <= maxK; k++) {
                    // down
                    /*for (int q = 0; q <= v && j + q <= maxK && k + q <= maxK; q++) {
