                    //}
                    add1[0, k] += dp[j, k];
                    add1[j, k] -= dp[j, k];
                }
            }

            for (int j = 0; j <= maxK; j++) {
                for (int k = 0; k <= maxK; k++) {
                    if (j - 1 >= 0) add1[j, k] += add1[j - 1, k];
                    if (j - 1 >= 0 && k - 1 >= 0) add12[j, k] += add12[j - 1, k - 1];
                    next[j, k] = add1[j, k] + add12[j, k];
                }
            }

            dp = next;
        }
