public class Scanner {
    private readonly TextReader Reader;
    private readonly CultureInfo ci = CultureInfo.InvariantCulture;

    private readonly char[] buffer = new char[2 * 1024];
    private int cursor = 0, length = 0;
    private string Token;
    private readonly StringBuilder sb = new StringBuilder(1024);

    public Scanner()
        : this(Console.In) {
    }

    public Scanner(TextReader reader) {
        Reader = reader;
    }

    public int NextInt() { return checked((int)NextLong()); }
    public long NextLong() {
        var s = Next();
        long r = 0;
        int i = 0;
        bool negative = false;
        if (s[i] == '-') {
            negative = true;
            i++;
        }
        for (; i < s.Length; i++) {
            r = r * 10 + (s[i] - '0');
#if DEBUG
            if (!char.IsDigit(s[i])) throw new FormatException();
#endif
        }
        return negative ? -r : r;
    }
    public double NextDouble() { return double.Parse(Next(), ci); }
    public string[] NextArray(int size) {
        string[] array = new string[size];
        for (int i = 0; i < size; i++) {
            array[i] = Next();
        }

        return array;
    }
    public int[] NextIntArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextInt();
        }

        return array;
    }

    public long[] NextLongArray(int size) {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextLong();
        }

        return array;
    }

    public double[] NextDoubleArray(int size) {
        double[] array = new double[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextDouble();
        }

        return array;
    }

    public string Next() {
        if (Token == null) {
            if (!StockToken()) {
                throw new Exception();
            }
        }
        var token = Token;
        Token = null;
        return token;
    }

    public bool HasNext() {
        if (Token != null) {
            return true;
        }

        return StockToken();
    }

    private bool StockToken() {
        while (true) {
            sb.Clear();
            while (true) {
                if (cursor >= length) {
                    cursor = 0;
                    if ((length = Reader.Read(buffer, 0, buffer.Length)) <= 0) {
                        break;
                    }
                }
                var c = buffer[cursor++];
                if (33 <= c && c <= 126) {
                    sb.Append(c);
                } else {
                    if (sb.Length > 0) break;
                }
            }

            if (sb.Length > 0) {
                Token = sb.ToString();
                return true;
            }

            return false;
        }
    }
}

using System;
using System.Collections.Generic;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N;
    private string S;
    private int K;

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        N = S.Length;
        K = sc.NextInt();

        int cnt = 0;
        List<int> ls = new List<int>();
        for (int i = N - 1; i >= 0; i--)
        {
            if (S[i] == '0')
            {
                ls.Add(cnt);
                cnt = 0;
            }
            else
            {
                cnt++;
            }
        }

        // i個目の0、いままで置いた個数、操作回数
        var dp = new ModInt[(ls.Count + 1) * 301 * 301];
        dp[C(0, 0, 0)] = 1;
        int one = 0;
        for (int i = 0; i < ls.Count; i++)
        {
            for (int j = 0; j <= one; j++)
            {
                for (int k = 0; k <= one; k++)
                {
                    // ここに置く1の個数
                    for (int l = 0; l <= ls[i] + one - j; l++)
                    {
                        int nk = k + Math.Max(0, ls[i] - l);
                        int nj = j + l;
                        dp[C(i + 1, nj, nk)] += dp[C(i, j, k)];
                    }
                }
            }

            one += ls[i];
        }

        ModInt ans = 0;
        for (int i = 0; i <= 300; i++)
        {
            for (int j = 0; j <= K && j <= 300; j++)
            {
                ans += dp[C(ls.Count, i, j)];
            }
        }

        Console.WriteLine(ans);
    }

    int C(int i, int j, int k)
    {
        return i * 301 * 301 + j * 301 + k;
    }

    public static void Main(string[] args) => new Program().Solve();
}

