                else { len++; }
                if (i == N - 1) num.Add(len);
            }
            num.Reverse();

            int L = num.Count();
            int S = num.Sum();
            K = Min(K, S);
            var dp = new ModInt[K + 1][];
            var D1 = new ModInt[K + 1][];//斜め
            var D2 = new ModInt[K + 1][];//直線
            for (var i = 0; i <= K; i++)
            {
                dp[i] = new ModInt[S + 1];
                D1[i] = new ModInt[S + 1];
                D2[i] = new ModInt[S + 1];
