            {
                for (var j = 0; j <= K; j++) for (var k = 0; k <= S; k++)
                        dp[j][k] = 0;
                //imos,斜め
                for(var z = 0; z <= K + S; z++)
                {
                    for(var y = 0; y <= z; y++)
                    {
                        //idx: z-y,y
                        if (z - y < K && 0 < y && y <= S) D1[z - y][y] += D1[z - y + 1][y - 1];
                    }
                }
                //imos,直線
                for(var j = 0; j <= K; j++)
                {
                    for(var k = 1; k <= S; k++)
                    {
                        D2[j][k] += D2[j][k - 1];
                    }
                }
                for (var j = 0; j <= K; j++) for (var k = 0; k <= S; k++)
                        dp[j][k] = D1[j][k] + D2[j][k];
                for(var j=0;j<=K;j++)for(var k = 0; k <= S; k++)
                    {
                        D1[j][k] = D2[j][k] = 0;
                    }
                if (i == 0) dp[0][0] = 1;
                //OutL($"i={i}");
                /*for (var j = 0; j <= K; j++)
                {
                    for(var k = 0; k <= S; k++)
                    {
                        Out_One(dp[j][k].value);
                    }
                    Endl();
                }*/
                if (i == L) break;
                int a = num[i];
                sum += a;
                //遷移
                for(var j = 0; j <= K; j++)
                {
                    for(var k = 0; k <= S; k++)
                    {
                        if (dp[j][k].value == 0) continue;

                        //斜め
                        int mn = Min(j + a, K);
                        D1[mn][j + k + a - mn] += dp[j][k];
                        if (j > 0 && k + a + 1 <= S) D1[j - 1][k + a + 1] -= dp[j][k];

                        //直線
                        if (k + a + 1 <= S) D2[j][k + a + 1] += dp[j][k];
                        if (sum + 1 <= S) D2[j][sum + 1] -= dp[j][k];
                    }
                }
            }
            ModInt ans = 0;
            for (var i = 0; i <= K; i++) ans += dp[i][S];
            OutL(ans.value);

