  var cum int
  for i := M - 1; 0 <= i; i-- {
    for j := 0; j <= K; j++ {
      cum = 0
      for k := 0; k <= j; k++ {
        DP[i][j][k] += DP[i + 1][j][k] + cum
        DP[i][j][k] %= p
        cum += DP[i + 1][j][k]
      }
