const mod = 998244353

func solve(s string, m int) (ans int) {
	count := countOnes(s)
	n := len(count)
	dp := make([][][]int, n+1)
	for i := range dp {
		dp[i] = make([][]int, m+1)
		for j := range dp[i] {
			dp[i][j] = make([]int, m+1)
		}
	}
	dp[0][0][0] = 1
	for i := 0; i < n; i++ {
		for j := 0; j <= m; j++ {
			for k := 0; k <= m; k++ {
				// do nothing
				dp[i+1][j][k] += dp[i][j][k]
				dp[i+1][j][k] %= mod
				// move from stock
				for l := 1; l <= k; l++ {
					dp[i+1][j][k-l] += dp[i][j][k]
					dp[i+1][j][k-l] %= mod
				}
				// move to stock
				for l := 1; l <= count[n-1-i] && j+l <= m && k+l <= m; l++ {
					dp[i+1][j+l][k+l] += dp[i][j][k]
					dp[i+1][j+l][k+l] %= mod
				}
			}
		}
	}

	for j := range dp[n] {
		ans += dp[n][j][0]
		ans %= mod
	}
	return ans
}

