// 先頭の1, 末尾の0を削除した文字列でOK
// 同じ1を2回以上操作するのは1回にまとめられるのでk <= |S| としてよい
//
// [操作回数][保持する1]　だと重複が発生する
// 直前に操作したかも持っておく

#[fastout]
fn run() {
    input! {
        s: Chars,
        k: usize,
    }
    let n = s.len();
    let k = std::cmp::min(k, n - 1);
    let mut a = vec![];
    for c in s {
        match c {
            '0' => a.push((c, 1)),
            '1' => {
                if a.last().map_or(false, |a| a.0 == '1') {
                    a.last_mut().unwrap().1 += 1;
                } else {
                    a.push((c, 1));
                }
            }
            _ => (),
        }
    }
    // [操作回数][保持してる1][直前に挿入したなら1]
    let mut dp = vec![vec![vec![ModInt::zero(); 2]; n + 1]; n + 1];
    dp[0][0][0] = ModInt::one();
    for (d, c) in a.into_iter().rev() {
        let mut next = vec![vec![vec![ModInt::zero(); 2]; n + 1]; n + 1];
        if d == '1' {
            for i in 0..=n {
                for j in 0..=i {
                    for k in 0..2 {
                        let v = dp[i][j][k];
                        if v.0 == 0 {
                            continue;
                        }
                        if k == 1 {
                            next[i][j][0] += v;
                            next[i + 1][j + 1][0] -= v;
                        } else {
                            next[i][j][0] += v;
                            let r = min(n - 1, i + c);
                            next[r + 1][j + r + 1 - i][0] -= v;
                        }
                        /*
                        if k == 1 {
                            next[i][j][0] += v;
                        } else {
                            for x in i..=min(n, i + c) {
                                next[x][j + x - i][0] += v;
                            }
                        }
                        */
                    }
                }
            }
            for i in 1..=n {
                for j in 1..=n {
                    for k in 0..2 {
                        next[i][j][k] = next[i][j][k] + next[i - 1][j - 1][k];
                    }
                }
            }
        } else {
            for i in 0..=n {
                for j in 0..=i {
                    for k in 0..2 {
                        let v = dp[i][j][k];
                        if v.0 == 0 {
                            continue;
                        }
                        next[i][0][1] += v;
                        next[i][j][1] -= v;
                        next[i][j][0] += v;
                        next[i][j + 1][0] -= v;
                        /*
                        for x in 0..=j {
                            let y = if x == j {0} else {1};
                            next[i][x][y] += v;
                        }
                        */
                    }
                }
            }
            for i in 0..=n {
                for j in 1..=n {
                    for k in 0..2 {
                        next[i][j][k] = next[i][j][k] + next[i][j - 1][k];
                    }
                }
            }
        }
        dp = next;
    }
    let mut ans = ModInt::zero();
    for i in 0..=k {
        ans += dp[i][0][0] + dp[i][0][1];
    }
    println!("{}", ans);
}

fn main() {
    run();
}

