const MOD: u64 = 998244353;
const MAX_K: usize = 310;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let mut s = vec![];
    let t = sc.chars();
    let k: usize = min(sc.read(), MAX_K);
    let mut count = 0;
    for c in t.into_iter() {
        if c == '0' {
            s.push(count);
            count = 0;
        } else {
            count += 1;
        }
    }
    s.push(count);

    let total_ones = s.iter().sum::<usize>();
    let n = s.len() - 1;
    let mut dp = vec![vec![m(0); k + 1]; total_ones + 1];
    dp[0][0] = m(1);

    let mut cur_sum = 0;
    for i in 0..n {
        let s = s[i];
        let mut next = vec![vec![m(0); k + 1]; total_ones + 1];
        for before_ones in cur_sum..=total_ones {
            for before_k in 0..=k {
                for next_ones in before_ones..=total_ones {
                    let seg_ones = next_ones - before_ones;
                    if seg_ones < s && before_ones + seg_ones < cur_sum + s {
                        continue;
                    }
                    let cost = if seg_ones < s { 0 } else { seg_ones - s };
                    let next_k = before_k + cost;
                    if next_k > k {
                        continue;
                    }
                    next[next_ones][next_k] += dp[before_ones][before_k];
                }
            }
        }
        cur_sum += s;
        dp = next;
    }

    let mut ans = m(0);
    for k in 0..=k {
        for one in cur_sum..=total_ones {
            ans += dp[one][k];
        }
    }

    println!("{}", ans.v);
}

