#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: tt),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, u1) => {
        $it.next().unwrap().parse::<usize>().unwrap() -1
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let mut v = it.next().unwrap().bytes().fold(vec![0usize], |mut v, x| {
        if x == b'0' {
            v.push(0);
        } else {
            *v.last_mut().unwrap() += 1;
        }
        v
    });
    parse!(it, K: usize);
    let K = min(K, v.iter().sum());
    v.reverse();
    let n = v.len();
    let mut dp = vec![vec![vec![Mint(0); K + 1]; K + 1]; n];
    dp[0][K][0] = Mint(1);
    for i in 0..n - 1 {
        for j in 0..=K {
            for k in 0..=K {
                let rest = k + v[i];
                let tmp = dp[i][j][k];
                for l in 0..=rest {
                    if l >= v[i] {
                        dp[i + 1][j][l - v[i]] += tmp;
                    } else {
                        if v[i] - l <= j && rest - l <= K {
                            dp[i + 1][j - (v[i] - l)][rest - l] += tmp;
                        }
                    }
                }
            }
        }
    }

    let mut ret = Mint(0);
    for i in 0..=K {
        for j in 0..=K {
            ret += dp[n - 1][i][j]
        }
    }
    println!("{}", ret);
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

