fn run() {
    proconio::input! {
        mut s: proconio::marker::Chars,
        k: usize,
    }
    for c in "01".chars() {
        while s.last().map_or(false, |p| *p == c) {
            s.pop();
        }
        s.reverse();
    }
    if s.is_empty() {
        println!("1");
        return;
    }
    let mut a = vec![];
    for c in s {
        if c == '0' {
            a.push(0);
        } else {
            *a.last_mut().unwrap() += 1;
        }
    }
    let k = std::cmp::min(k, a.iter().sum());
    // [取り出した回数][挿入した回数]
    let mut dp = vec![vec![ModInt::zero(); k + 1]; k + 1];
    dp[0][0] = ModInt::one();
    for a in a.into_iter().rev() {
        let mut next = vec![vec![ModInt::zero(); k + 1]; k + 1];
        // 挿入
        for (i, dp) in dp.iter().enumerate() {
            for (j, &v) in dp.iter().enumerate().filter(|p| !p.1.is_zero()) {
                for p in j..=i {
                    next[i][p] += v;
                }
            }
        }
        // 取り出す
        for (i, dp) in dp.iter().enumerate() {
            for (j, &v) in dp.iter().enumerate().filter(|p| !p.1.is_zero()) {
                for p in (i + 1)..=std::cmp::min(k, i + a) {
                    next[p][j] += v;
                }
            }
        }
        dp = next;
    }
    let mut ans = ModInt::zero();
    for dp in dp {
        for a in dp {
            ans += a;
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

