fn run() {
    proconio::input! {
        mut s: proconio::marker::Chars,
        k: usize,
    }
    for c in "01".chars() {
        while s.last().map_or(false, |p| *p == c) {
            s.pop();
        }
        s.reverse();
    }
    if s.is_empty() {
        println!("1");
        return;
    }
    let mut a = vec![];
    for c in s {
        if c == '0' {
            a.push(0);
        } else {
            *a.last_mut().unwrap() += 1;
        }
    }
    let k = std::cmp::min(k, a.iter().sum());
    // [取り出した回数][挿入した回数]
    const MOD: u64 = 998_244_353;
    let mut dp = vec![vec![1u64]];
    for a in a.into_iter().rev() {
        let len = std::cmp::min(k + 1, dp.len() + a);
        let mut next = vec![vec![0; len]; len];
        // 挿入
        for (i, (next, dp)) in next.iter_mut().zip(dp.iter()).enumerate() {
            for (j, &v) in dp.iter().enumerate().filter(|p| *p.1 != 0) {
                next[j] += v;
                if let Some(p) = next.get_mut(i + 1) {
                    *p -= v;
                }
            }
            let mut s = 0;
            for p in next.iter_mut() {
                *p += s;
                s = *p;
            }
        }
        // 取り出す
        for (i, dp) in dp.iter().enumerate() {
            for (j, &v) in dp.iter().enumerate().filter(|p| *p.1 != 0) {
                for next in next.iter_mut().skip(i + 1).take(a) {
                    next[j] += v;
                }
            }
        }
        dp = next;
        dp.iter_mut().for_each(|dp| dp.iter_mut().for_each(|v| *v %= MOD));
    }
    let ans = dp.into_iter().map(|dp| dp.into_iter().sum::<u64>()).sum::<u64>() % MOD;
    println!("{}", ans);
}

fn main() {
    run();
}

