fn main() {
    let v = read_vec::<String>();
    let k = v[1].parse::<i64>().unwrap();
    let mut s = v[0].chars().collect::<Vec<_>>();
    s.push('0');

    let mut ones = vec![];
    let mut cur = 0;
    for &ch in s.iter() {
        match ch {
            '1' => cur += 1,
            _ => {
                ones.push(cur);
                cur = 0;
            }
        }
    }

    let k = min(k, s.len() as i64) as usize;
    let one_sum = ones.iter().sum::<usize>();
    let mut dp = vec![vec![Modulo(0); k + 1]; one_sum + 1];
    dp[0][0] = Modulo(1);
    for one in ones.iter().rev() {
        let mut next = dp.clone();
        for ki in 0..k + 1 {
            for prev_oi in 0..one_sum + 1 {
                // send
                for oi in 1..one + 1 {
                    if oi + prev_oi > one_sum || ki + oi > k {
                        break;
                    }
                    next[prev_oi + oi][ki + oi] += dp[prev_oi][ki];
                }

                // receive
                for oi in 1..prev_oi + 1 {
                    next[prev_oi - oi][ki] += dp[prev_oi][ki];
                }
            }
        }
        dp = next;
    }
    let ans = dp[0].iter().sum::<Modulo>();
    println!("{}", ans);
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

#[derive(Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd)]
struct Modulo(i64);
static mut MODULUS: i64 = 998244353;
impl Modulo {
    fn set_modulus(m: i64) {
        unsafe {
            MODULUS = m;
        }
    }
    fn get_modulus() -> i64 {
        unsafe { MODULUS }
    }
    fn new(x: i64) -> Modulo {
        let m = Modulo::get_modulus();
        if x < 0 {
            Modulo(x % m + m)
        } else if x < m {
            Modulo(x)
        } else {
            Modulo(x % m)
        }
    }
    fn pow(self, p: i64) -> Modulo {
        if p == 0 {
            Modulo(1)
        } else {
            let mut t = self.pow(p / 2);
            t *= t;
            if p & 1 == 1 {
                t *= self;
            }
            t
        }
    }
    fn inv(self) -> Modulo {
        self.pow(Modulo::get_modulus() - 2)
    }
}
impl std::fmt::Display for Modulo {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        self.0.fmt(f)
    }
}
impl std::ops::AddAssign for Modulo {
    fn add_assign(&mut self, other: Modulo) {
        let m = Modulo::get_modulus();
        self.0 += other.0;
        if self.0 >= m {
            self.0 -= m;
        }
    }
}
impl std::ops::MulAssign for Modulo {
    fn mul_assign(&mut self, other: Modulo) {
        let m = Modulo::get_modulus();
        self.0 *= other.0;
        self.0 %= m;
    }
}
impl std::ops::SubAssign for Modulo {
    fn sub_assign(&mut self, other: Modulo) {
        let m = Modulo::get_modulus();
        self.0 += m - other.0;
        if self.0 >= m {
            self.0 -= m;
        }
    }
}
