fn run() {
    proconio::input! {
        mut s: proconio::marker::Chars,
        k: usize,
    }
    for c in "01".chars() {
        while s.last().map_or(false, |p| *p == c) {
            s.pop();
        }
        s.reverse();
    }
    if s.is_empty() {
        println!("1");
        return;
    }
    let mut a = vec![];
    for c in s {
        if c == '0' {
            a.push(0);
        } else {
            *a.last_mut().unwrap() += 1;
        }
    }
    let k = std::cmp::min(k, a.iter().sum());
    // [取り出した回数][挿入した回数]
    let mut dp = vec![vec![ModInt::zero()]];
    dp[0][0] = ModInt::one();
    for a in a.into_iter().rev() {
        let len = std::cmp::min(k + 1, dp.len() + a);
        let mut next = vec![vec![ModInt::zero(); len]; len];
        // 挿入
        for (i, dp) in dp.iter().enumerate() {
            let next = &mut next[i];
            for (j, &v) in dp.iter().enumerate().filter(|p| !p.1.is_zero()) {
                next[j] += v;
                if let Some(p) = next.get_mut(i + 1) {
                    *p -= v;
                }
            }
            for j in 1..next.len() {
                next[j] = next[j] + next[j - 1];
            }
        }
        // 取り出す
        for (i, dp) in dp.iter().enumerate() {
            for (j, &v) in dp.iter().enumerate().filter(|p| !p.1.is_zero()) {
                for p in (i + 1)..=std::cmp::min(k, i + a) {
                    next[p][j] += v;
                }
            }
        }
        dp = next;
    }
    let mut ans = ModInt::zero();
    for dp in dp {
        for a in dp {
            ans += a;
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

use proconio::{fastout, input};

use proconio::marker::Chars;
use std::cmp::{max, min};

#[fastout]
fn main() {
    const M: usize = 998244353;
    input! {
        s: Chars, k: usize,
    }
    let n = s.len();
    let k = min(k, s.len());
    let mut a = vec![0];
    for c in s {
        if c == '0' {
            a.push(0);
        }
        if c == '1' {
            if let Some(last) = a.last_mut() {
                *last += 1;
            }
        }
    }
    let mut h = vec![vec![vec![None; k + 1]; n]; a.len() + 1];
    fn f(
        i: usize,
        j: usize,
        k: usize,
        a: &Vec<usize>,
        h: &mut Vec<Vec<Vec<Option<usize>>>>,
    ) -> usize {
        if i == 0 {
            return 1;
        }
        if let Some(v) = h[i][j][k] {
            return v;
        }
        let mut s = 0;
        for l in 0..=min(k, a[i]) {
            s += f(i - 1, j + l, k - l, a, h);
            s %= M;
        }
        for l in 1..=j {
            s += f(i - 1, j - l, k, a, h);
            s %= M;
        }
        h[i][j][k] = Some(s);
        s
    }
    let ans = f(a.len() - 1, 0, k, &a, &mut h);
    println!("{}", ans);
}

