pub struct Comb {
    fact: Vec<ModInt<Num>>,
    factinv: Vec<ModInt<Num>>,
}

impl Comb {
    /// Create a object that provides effiecint computation of combinations
    /// for input smaller than `n`.
    ///
    /// This requires `O(n)` time.
    pub fn new(n: usize) -> Comb {
        let mut fact: Vec<ModInt<Num>> = vec![ModInt(0); n + 1];
        let mut factinv: Vec<ModInt<Num>> = vec![ModInt(0); n + 1];
        fact[0] = ModInt(1);
        for i in 0..n {
            fact[i + 1] = fact[i] * (i + 1);
        }
        factinv[n] = fact[n].pow(MOD-2);
        for i in (0..n).rev() {
            factinv[i] = factinv[i + 1] * (i + 1);
        }
        Comb {
            fact: fact,
            factinv: factinv,
        }
    }

    /// `n! = 1 * 2 * ... * n`
    ///
    /// `O(1)` if n is smaller than input in `new` method.
    pub fn fact(&self, n: usize) -> ModInt<Num> {
        if let Some(x) = self.fact.get(n as usize) {
            *x
        } else if n >= MOD {
            ModInt(0)
        } else {
            // Note that this is slow if `n` is large.
            // Precalculation is a possible solution but doesn't work for any module number.
            let mut res = ModInt(1);
            for a in 1..(n + 1) {
                res *= a;
            }
            res
        }
    }

    /// returns `y` such that `n! * y == 1`.
    ///
    /// `O(1)` if n is smaller than input in `new` method.
    pub fn factinv(&self, n: usize) -> ModInt<Num> {
        if let Some(x) = self.factinv.get(n) {
            *x
        } else {
            self.fact(n).pow(MOD-2)
        }
    }

    /// `nPr = n! / (n - r)!`
    ///
    /// `O(1)` if n and r are smaller than input in `new` method.
    pub fn perm(&self, n: usize, r: usize) -> ModInt<Num> {
        if n >= r {
            self.fact(n) * self.factinv(n - r)
        } else {
            ModInt(0)
        }
    }

    /// `nCr = n! / (n - r)! / r!`.
    ///
    /// `O(1)` if n and r are smaller than input in `new` method.
    pub fn comb(&self, n: usize, r: usize) -> ModInt<Num> {
        let m = MOD;
        if n >= m {
            self.comb(n % m, r % m) * self.comb(n / m, r / m) // Lucas' theorem
        } else if n >= r {
            self.fact(n) * self.factinv(n - r) * self.factinv(r)
        } else {
            ModInt(0)
        }
    }
}

fn solve() {
	let (s,k) = read!(String,i64);
	let c = s.chars().collect::<Vec<char>>();
	let n = c.len();
	let mut prev = c[n-1];
	let mut count = 1;
	let mut z = 1;
	let mut v = vec![];
	for i in (0..n-1).rev() {
		if c[i]=='1' {
			z += 1;
		}
		if c[i+1]==c[i] {
			count += 1;
		}
		else {
			match c[i] {
				'0' => v.push((1,count)),
				_ => v.push((0,count)),
			}
			count = 1;
		}
	}
	match c[0] {
		'0' => v.push((0,count+1)),
		_ => {
			v.push((1,count));
			v.push((0,1));
		},
	}
	let mut dp = vec![vec![vec![ModInt(0);2*z+2];2*z+2];n+2];
	dp[0][0][0] = ModInt(1);
	let mut comb = Comb::new(z+3);
	for (idx,&(val,count)) in v.iter().enumerate() {
		if val==0 {
			let t = count-1;
			if t==0 {
				for x in 0..z+1 {
					for m in 0..z+1 {
						dp[idx+1][x][m] = dp[idx+1][x][m] + dp[idx][x][m];
					}
				}
				continue;
			}
			for i in 0..z+2 {
				for j in 0..z+2 {
					if j>i {
						continue;
					}
					let x = i-j;
					let tmp = comb.comb(t+j-1,j);
					for m in 0..z+1 {
						dp[idx+1][x][m] = dp[idx+1][x][m] + dp[idx][i][m]*tmp;
					}
				}
			}
		}
		if val==1 {
			for i in 0..z+2 {
				for j in 0..z+2 {
					if count+j<i {
						continue;
					}
					let x = j+count-i;
					let p = max(0,count as i64 - i as i64) as usize;
					for m in 0..z+2 {
						dp[idx+1][x][m+p] = dp[idx+1][x][m+p] + dp[idx][j][m];
					}
				}
			}
		}
		// for x in 0..z+2 {
		// 	for m in 0..z+2 {
		// 		print!("{} ",dp[idx+1][x][m].0);
		// 	}
		// 	println!();
		// }
		// println!();
	}
	let mut ans = ModInt(0);
	for i in 0..min((z+2) as i64,k+1) {
		ans += dp[v.len()][0][i as usize];
		// print!("{} ",dp[v.len()][0][i as usize].0);
	}
	println!("{}",ans.0);
}

