const MOD: usize = 998244353;
const INF: i64 = std::i64::MAX/3;

use std::ops::{Add, AddAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign};

type Num = usize;

#[derive(Clone, Copy, Debug)]
pub struct ModInt<T: Copy + Clone>(pub T);

impl Add<ModInt<Num>> for ModInt<Num> {
    type Output = ModInt<Num>;
    fn add(self, rhs: ModInt<Num>) -> ModInt<Num> {
        self + rhs.0
    }
}

impl Add<Num> for ModInt<Num> {
    type Output = ModInt<Num>;
    fn add(self, rhs: Num) -> ModInt<Num> {
        let mut t = rhs + self.0;
        if t >= MOD {
            t = t - MOD;
        }
        ModInt(t)
    }
}

impl Sub<Num> for ModInt<Num> {
    type Output = ModInt<Num>;
    fn sub(self, rhs: Num) -> ModInt<Num> {
        let rhs = if rhs >= MOD { rhs % MOD } else { rhs };
        let value = if self.0 < rhs { self.0 + MOD } else { self.0 };
        ModInt(value - rhs)
    }
}

impl Sub<ModInt<Num>> for ModInt<Num> {
    type Output = ModInt<Num>;
    fn sub(self, rhs: ModInt<Num>) -> ModInt<Num> {
        self - rhs.0
    }
}

impl AddAssign<Num> for ModInt<Num> {
    fn add_assign(&mut self, other: Num) {
        *self = *self + other;
    }
}
impl AddAssign<ModInt<Num>> for ModInt<Num> {
    fn add_assign(&mut self, other: ModInt<Num>) {
        *self = *self + other;
    }
}

impl SubAssign<Num> for ModInt<Num> {
    fn sub_assign(&mut self, other: Num) {
        *self = *self - other;
    }
}

impl SubAssign<ModInt<Num>> for ModInt<Num> {
    fn sub_assign(&mut self, other: ModInt<Num>) {
        *self = *self - other;
    }
}

impl Div<Num> for ModInt<Num> {
    type Output = ModInt<Num>;
    fn div(self, rhs: Num) -> ModInt<Num> {
        self * ModInt(rhs).pow(MOD - 2)
    }
}

impl Div<ModInt<Num>> for ModInt<Num> {
    type Output = ModInt<Num>;
    fn div(self, rhs: ModInt<Num>) -> ModInt<Num> {
        self / rhs.0
    }
}

impl DivAssign<Num> for ModInt<Num> {
    fn div_assign(&mut self, rhs: Num) {
        *self = *self / rhs
    }
}
impl DivAssign<ModInt<Num>> for ModInt<Num> {
    fn div_assign(&mut self, rhs: ModInt<Num>) {
        *self = *self / rhs
    }
}

impl Mul<ModInt<Num>> for ModInt<Num> {
    type Output = ModInt<Num>;

    fn mul(self, rhs: ModInt<Num>) -> ModInt<Num> {
        self * rhs.0
    }
}
impl Mul<Num> for ModInt<Num> {
    type Output = ModInt<Num>;

    fn mul(self, rhs: Num) -> ModInt<Num> {
        let t = (self.0 * rhs) % MOD;
        ModInt(t)
    }
}

impl MulAssign<Num> for ModInt<Num> {
    fn mul_assign(&mut self, rhs: Num) {
        *self = *self * rhs;
    }
}

impl MulAssign<ModInt<Num>> for ModInt<Num> {
    fn mul_assign(&mut self, rhs: ModInt<Num>) {
        *self = *self * rhs;
    }
}

impl ModInt<Num> {
    pub fn pow(self, e: usize) -> ModInt<Num> {
        let mut result = ModInt(1);
        let mut cur = self;
        let mut e = e;
        while e > 0 {
            if e & 1 == 1 {
                result *= cur;
            }
            e >>= 1;
            cur *= cur;
        }
        result
    }
}

pub struct Comb {
    fact: Vec<ModInt<Num>>,
    factinv: Vec<ModInt<Num>>,
}

impl Comb {
    /// Create a object that provides effiecint computation of combinations
    /// for input smaller than `n`.
    ///
    /// This requires `O(n)` time.
    pub fn new(n: usize) -> Comb {
        let mut fact: Vec<ModInt<Num>> = vec![ModInt(0); n + 1];
        let mut factinv: Vec<ModInt<Num>> = vec![ModInt(0); n + 1];
        fact[0] = ModInt(1);
        for i in 0..n {
            fact[i + 1] = fact[i] * (i + 1);
        }
        factinv[n] = fact[n].pow(MOD-2);
        for i in (0..n).rev() {
            factinv[i] = factinv[i + 1] * (i + 1);
        }
        Comb {
            fact: fact,
            factinv: factinv,
        }
    }

    /// `n! = 1 * 2 * ... * n`
    ///
    /// `O(1)` if n is smaller than input in `new` method.
    pub fn fact(&self, n: usize) -> ModInt<Num> {
        if let Some(x) = self.fact.get(n as usize) {
            *x
        } else if n >= MOD {
            ModInt(0)
        } else {
            // Note that this is slow if `n` is large.
            // Precalculation is a possible solution but doesn't work for any module number.
            let mut res = ModInt(1);
            for a in 1..(n + 1) {
                res *= a;
            }
            res
        }
    }

    /// returns `y` such that `n! * y == 1`.
    ///
    /// `O(1)` if n is smaller than input in `new` method.
    pub fn factinv(&self, n: usize) -> ModInt<Num> {
        if let Some(x) = self.factinv.get(n) {
            *x
        } else {
            self.fact(n).pow(MOD-2)
        }
    }

    /// `nPr = n! / (n - r)!`
    ///
    /// `O(1)` if n and r are smaller than input in `new` method.
    pub fn perm(&self, n: usize, r: usize) -> ModInt<Num> {
        if n >= r {
            self.fact(n) * self.factinv(n - r)
        } else {
            ModInt(0)
        }
    }

    /// `nCr = n! / (n - r)! / r!`.
    ///
    /// `O(1)` if n and r are smaller than input in `new` method.
    pub fn comb(&self, n: usize, r: usize) -> ModInt<Num> {
        let m = MOD;
        if n >= m {
            self.comb(n % m, r % m) * self.comb(n / m, r / m) // Lucas' theorem
        } else if n >= r {
            self.fact(n) * self.factinv(n - r) * self.factinv(r)
        } else {
            ModInt(0)
        }
    }
}

fn solve() {
	let (s,k) = read!(String,i64);
	let c = s.chars().collect::<Vec<char>>();
	let n = c.len();
	let z = c.len()+1;
	let mut dp = vec![vec![vec![ModInt(0);2*z+2];2*z+2];z+2];
	dp[0][0][0] = ModInt(1);
	let mut prev = c[n-1];
	let mut count = 1;
	let mut v = vec![];
	for i in (0..n-1).rev() {
		if c[i+1]==c[i] {
			count += 1;
		}
		else {
			match c[i] {
				'0' => v.push((1,count)),
				_ => v.push((0,count)),
			}
			count = 1;
		}
	}
	match c[0] {
		'0' => v.push((0,count+1)),
		_ => {
			v.push((1,count));
			v.push((0,1));
		},
	}
	let mut comb = Comb::new(n+1);
	for (idx,&(val,count)) in v.iter().enumerate() {
		if val==0 {
			let t = count-1;
			if t==0 {
				for x in 0..z+1 {
					for m in 0..z+1 {
						dp[idx+1][x][m] = dp[idx+1][x][m] + dp[idx][x][m];
					}
				}
				continue;
			}
			for i in 0..z+2 {
				for j in 0..z+2 {
					if j>i {
						continue;
					}
					let x = i-j;
					let tmp = comb.comb(t+j-1,j);
					for m in 0..z+1 {
						dp[idx+1][x][m] = dp[idx+1][x][m] + dp[idx][i][m]*tmp;
					}
				}
			}
		}
		if val==1 {
			for i in 0..z+2 {
				for j in 0..z+2 {
					if count+j<i {
						continue;
					}
					let x = j+count-i;
					let p = max(0,count as i64 - i as i64) as usize;
					for m in 0..z+2 {
						dp[idx+1][x][m+p] = dp[idx+1][x][m+p] + dp[idx][j][m];
					}
				}
			}
		}
		// for x in 0..z+2 {
		// 	for m in 0..z+2 {
		// 		print!("{} ",dp[idx+1][x][m].0);
		// 	}
		// 	println!();
		// }
		// println!();
	}
	let mut ans = ModInt(0);
	for i in 0..min((z+2) as i64,k+1) {
		ans += dp[v.len()][0][i as usize];
		// print!("{} ",dp[v.len()][0][i as usize].0);
	}
	println!("{}",ans.0);
}

fn run() {
    solve();
}
